export interface RepairResult {
  text: string;
  notes: string[];
}

/** 修复 AI / 手写 JSON 的常见问题：注释、尾逗号、中文引号、括号不配对。 */
export function repairJson(input: string): RepairResult {
  const notes: string[] = [];
  let text = input.replace(/^\uFEFF/, '');

  if (/[“”]/.test(text) || /[‘’]/.test(text)) {
    text = text.replace(/[“”]/g, '"').replace(/[‘’]/g, "'");
    notes.push('已替换中文引号');
  }

  const withoutComments = stripComments(text);
  if (withoutComments !== text) {
    notes.push('已移除注释');
    text = withoutComments;
  }

  const withoutTrailingCommas = text.replace(/,\s*([}\]])/g, '$1');
  if (withoutTrailingCommas !== text) {
    notes.push('已移除多余逗号');
    text = withoutTrailingCommas;
  }

  const balanced = balance(text);
  if (balanced.closers !== '') {
    notes.push(`已补齐 ${balanced.closers.length} 个括号`);
    text = balanced.text;
  }
  if (balanced.extraClosers > 0) {
    notes.push('发现多余的右括号，建议检查');
  }

  return { text, notes };
}

function stripComments(text: string): string {
  let output = '';
  let quote: string | null = null;
  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    const next = text[i + 1];

    if (quote) {
      output += char;
      if (char === '\\') {
        output += next ?? '';
        i += 1;
        continue;
      }
      if (char === quote) quote = null;
      continue;
    }

    if (char === '"' || char === "'") {
      quote = char;
      output += char;
      continue;
    }

    if (char === '/' && next === '/') {
      while (i < text.length && text[i] !== '\n') i += 1;
      output += '\n';
      continue;
    }
    if (char === '/' && next === '*') {
      i += 2;
      while (i < text.length && !(text[i] === '*' && text[i + 1] === '/')) i += 1;
      i += 1;
      continue;
    }
    output += char;
  }
  return output;
}

function balance(text: string): { text: string; closers: string; extraClosers: number } {
  let quote: string | null = null;
  const stack: string[] = [];
  let extraClosers = 0;

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    if (quote) {
      if (char === '\\') {
        i += 1;
        continue;
      }
      if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
      continue;
    }
    if (char === '{' || char === '[') stack.push(char);
    else if (char === '}' || char === ']') {
      const expected = char === '}' ? '{' : '[';
      if (stack[stack.length - 1] === expected) stack.pop();
      else extraClosers += 1;
    }
  }

  const closers = stack
    .slice()
    .reverse()
    .map((char) => (char === '{' ? '}' : ']'))
    .join('');

  return { text: closers ? text + closers : text, closers, extraClosers };
}
