import { useCallback, useEffect, useRef, useState } from 'react';
import type { SaveData } from '../engine/types';
import { AUTO_SLOT, manualSlot } from '../engine/types';
import { validateSave } from '../engine/validate';
import type { StorageAdapter } from '../storage/StorageAdapter';
import type { StoredPack } from '../storage/PackStore';
import { FileButton, packFileName } from './fileUtils';
import { describeSaveSlot, formatTime, type ToastKind } from './uiTypes';

export interface SaveDialogProps {
  open: boolean;
  pack: StoredPack;
  storage: StorageAdapter;
  onClose(): void;
  onLoad(save: SaveData): void;
  onExport(save: SaveData, filename: string): Promise<void>;
  makeSnapshot(slot: string): SaveData | null;
  notify(text: string, kind?: ToastKind): void;
}

const SLOTS = [AUTO_SLOT, ...Array.from({ length: 5 }, (_, i) => manualSlot(i + 1))];

export function SaveDialog({
  open,
  pack,
  storage,
  onClose,
  onLoad,
  onExport,
  makeSnapshot,
  notify,
}: SaveDialogProps) {
  const [saves, setSaves] = useState<SaveData[]>([]);
  const [busySlot, setBusySlot] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const closeRef = useRef<HTMLButtonElement>(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      const list = await storage.list(pack.manifest.id);
      setSaves(list);
    } catch (error) {
      notify(`读取存档失败：${(error as Error).message}`, 'error');
    } finally {
      setLoading(false);
    }
  }, [storage, pack.manifest.id, notify]);

  useEffect(() => {
    if (!open) return;
    setConfirmDelete(null);
    void refresh();
    closeRef.current?.focus();
  }, [open, refresh, refreshKey]);

  if (!open) return null;

  const saveToSlot = async (slot: string) => {
    const snapshot = makeSnapshot(slot);
    if (!snapshot) {
      notify('尚未进入任何节点，无法存档', 'error');
      return;
    }
    setBusySlot(slot);
    try {
      await storage.put(snapshot);
      setRefreshKey((key) => key + 1);
      notify(`已保存到 ${describeSaveSlot(slot)}`, 'success');
    } catch (error) {
      notify(`保存失败：${(error as Error).message}`, 'error');
    } finally {
      setBusySlot(null);
    }
  };

  const deleteSlot = async (slot: string) => {
    setBusySlot(slot);
    try {
      await storage.remove(pack.manifest.id, slot);
      setConfirmDelete(null);
      setRefreshKey((key) => key + 1);
      notify(`已删除 ${describeSaveSlot(slot)}`, 'success');
    } catch (error) {
      notify(`删除失败：${(error as Error).message}`, 'error');
    } finally {
      setBusySlot(null);
    }
  };

  const importSave = async (file: File) => {
    try {
      const text = await file.text();
      let data: unknown;
      try {
        data = JSON.parse(text);
      } catch {
        notify('存档文件不是合法 JSON', 'error');
        return;
      }
      const validation = validateSave(data, pack);
      if (validation.errors.length > 0) {
        notify(`导入失败：${validation.errors.join('；')}`, 'error');
        return;
      }
      for (const warning of validation.warnings) notify(warning, 'info');
      onLoad(data as SaveData);
      onClose();
    } catch (error) {
      notify(`读取存档文件失败：${(error as Error).message}`, 'error');
    }
  };

  const exportSave = async (save: SaveData, filename: string) => {
    try {
      await onExport(save, filename);
      notify('已导出存档', 'success');
    } catch (error) {
      notify(`导出失败：${(error as Error).message}`, 'error');
    }
  };

  const exportCurrent = () => {
    const snapshot = makeSnapshot(AUTO_SLOT);
    if (!snapshot) {
      notify('尚未进入任何节点，无法导出', 'error');
      return;
    }
    void exportSave(snapshot, packFileName(pack, 'current', snapshot.timestamp));
  };

  return (
    <div className="modal-backdrop" role="presentation" onClick={onClose}>
      <div
        className="modal"
        role="dialog"
        aria-modal="true"
        aria-label="存档管理"
        onClick={(event) => event.stopPropagation()}
      >
        <header className="modal-header">
          <div>
            <h2>存档</h2>
            <p className="muted">{pack.manifest.name}</p>
          </div>
          <button ref={closeRef} type="button" className="icon-btn" onClick={onClose} aria-label="关闭存档">
            ✕
          </button>
        </header>

        <p className="hint">
          自动存档固定写入 <code>auto_1</code>，不会覆盖手动槽位（<code>manual_1..5</code>）。
        </p>

        <ul className="save-slots" data-testid="save-slots">
          {SLOTS.map((slot) => {
            const save = saves.find((item) => item.slot === slot);
            const isAuto = slot.startsWith('auto_');
            return (
              <li className={`save-slot ${isAuto ? 'is-auto' : ''}`} key={slot} data-slot={slot}>
                <div className="save-slot-head">
                  <strong>{describeSaveSlot(slot)}</strong>
                  <code>{slot}</code>
                </div>
                {save ? (
                  <p className="save-slot-meta" data-testid={`save-meta-${slot}`}>
                    {save.currentNodeId} · 第 {save.history.length} 个节点 · {formatTime(save.timestamp)}
                  </p>
                ) : (
                  <p className="save-slot-meta muted">空槽位</p>
                )}
                <div className="save-slot-actions">
                  {save ? (
                    <>
                      <button
                        type="button"
                        className="btn btn-primary btn-sm"
                        onClick={() => {
                          onLoad(save);
                          onClose();
                        }}
                        data-testid={`load-${slot}`}
                      >
                        读取
                      </button>
                      {!isAuto && (
                        <button
                          type="button"
                          className="btn btn-sm"
                          onClick={() => void saveToSlot(slot)}
                          disabled={busySlot === slot}
                        >
                          覆盖
                        </button>
                      )}
                      <button
                        type="button"
                        className="btn btn-sm"
                        onClick={() => void exportSave(save, packFileName(pack, save.slot, save.timestamp))}
                        data-testid={`export-${slot}`}
                      >
                        导出
                      </button>
                      <button
                        type="button"
                        className="btn btn-sm btn-danger"
                        onClick={() => (confirmDelete === slot ? void deleteSlot(slot) : setConfirmDelete(slot))}
                        disabled={busySlot === slot}
                      >
                        {confirmDelete === slot ? '确认删除' : '删除'}
                      </button>
                    </>
                  ) : (
                    <button
                      type="button"
                      className="btn btn-sm"
                      onClick={() => void saveToSlot(slot)}
                      disabled={busySlot === slot}
                      data-testid={`save-${slot}`}
                    >
                      保存到此槽
                    </button>
                  )}
                </div>
              </li>
            );
          })}
        </ul>

        {loading && <p className="muted">读取中…</p>}

        <footer className="modal-footer">
          <FileButton
            label="导入存档文件"
            accept=".json,application/json"
            onFile={(file) => void importSave(file)}
            className="btn"
            testId="import-save-file"
          />
          <button type="button" className="btn" onClick={exportCurrent} data-testid="export-current">
            导出当前进度
          </button>
          <button type="button" className="btn btn-ghost" onClick={onClose}>
            关闭
          </button>
        </footer>
      </div>
    </div>
  );
}
