import type { ToastItem } from './uiTypes';

export function Toasts({ items }: { items: ToastItem[] }) {
  return (
    <div className="toasts" role="status" aria-live="polite" data-testid="toasts">
      {items.map((toast) => (
        <div className={`toast toast-${toast.kind}`} key={toast.id}>
          {toast.text}
        </div>
      ))}
    </div>
  );
}
