import { appDataDir, join } from '@tauri-apps/api/path';
import { exists, mkdir, readDir, readTextFile, remove, rename, writeTextFile } from '@tauri-apps/plugin-fs';
import type { SaveData } from '../engine/types';
import { validateSave } from '../engine/validate';
import type { StorageAdapter } from './StorageAdapter';

/** Phase 2：存档落在 %APPDATA%\<identifier>\saves\<packId>\<slot>.json */
export class TauriFsStorage implements StorageAdapter {
  readonly kind = 'tauri-fs' as const;
  private root = '';

  constructor(private readonly baseDirOverride?: string) {}

  async init(): Promise<void> {
    const base = this.baseDirOverride && this.baseDirOverride !== '' ? this.baseDirOverride : await appDataDir();
    this.root = await join(base, 'saves');
    await mkdir(this.root, { recursive: true });
  }

  get rootPath(): string {
    return this.root;
  }

  private dirFor(packId: string): Promise<string> {
    return join(this.root, packId);
  }

  private async fileFor(packId: string, slot: string): Promise<string> {
    return join(await this.dirFor(packId), `${slot}.json`);
  }

  async list(packId?: string): Promise<SaveData[]> {
    let packIds: string[];
    if (packId) {
      packIds = [packId];
    } else {
      const entries = await readDir(this.root);
      packIds = entries.filter((entry) => entry.isDirectory).map((entry) => entry.name);
    }

    const saves: SaveData[] = [];
    for (const id of packIds) {
      let entries;
      try {
        entries = await readDir(await this.dirFor(id));
      } catch {
        continue;
      }
      for (const entry of entries) {
        if (!entry.isFile || !entry.name.endsWith('.json')) continue;
        try {
          const file = await join(await this.dirFor(id), entry.name);
          const parsed: unknown = JSON.parse(await readTextFile(file));
          if (validateSave(parsed).errors.length === 0) saves.push(parsed as SaveData);
        } catch {
          // 坏档跳过，不影响其他存档
        }
      }
    }
    return saves.sort((a, b) => b.timestamp - a.timestamp);
  }

  async get(packId: string, slot: string): Promise<SaveData | null> {
    try {
      const raw = await readTextFile(await this.fileFor(packId, slot));
      const parsed: unknown = JSON.parse(raw);
      return validateSave(parsed).errors.length === 0 ? (parsed as SaveData) : null;
    } catch {
      return null;
    }
  }

  async put(save: SaveData): Promise<void> {
    const { errors } = validateSave(save);
    if (errors.length > 0) throw new Error(`存档不合法：${errors.join('；')}`);

    const dir = await this.dirFor(save.packId);
    await mkdir(dir, { recursive: true });

    const target = await join(dir, `${save.slot}.json`);
    const temp = `${target}.tmp`;
    await writeTextFile(temp, JSON.stringify(save, null, 2));

    // Windows 下 rename 不能覆盖已存在文件：先删旧档再原子替换。
    if (await exists(target)) await remove(target);
    await rename(temp, target);
  }

  async remove(packId: string, slot: string): Promise<void> {
    const file = await this.fileFor(packId, slot);
    if (await exists(file)) await remove(file);
  }
}
