import { appDataDir, join } from '@tauri-apps/api/path';
import {
  exists,
  mkdir,
  readDir,
  readTextFile,
  remove,
  writeFile,
  writeTextFile,
} from '@tauri-apps/plugin-fs';
import type { ContentPack, GameState, Manifest, PackSummary, StoryNode } from '../engine/types';
import { isJsonObject } from '../engine/util';
import type { PackStore, StoredPack } from './PackStore';

interface PackMeta {
  importedAt: number;
  warnings: string[];
}

const EMPTY_META: PackMeta = { importedAt: 0, warnings: [] };

/** Phase 2：内容包解包后落在 %APPDATA%\<identifier>\packs\<packId>\ */
export class TauriPackStore implements PackStore {
  private root = '';

  constructor(private readonly baseDirOverride?: string) {}

  async init(): Promise<void> {
    const base = this.baseDirOverride && this.baseDirOverride !== '' ? this.baseDirOverride : await appDataDir();
    this.root = await join(base, 'packs');
    await mkdir(this.root, { recursive: true });
  }

  get rootPath(): string {
    return this.root;
  }

  private dirFor(id: string): Promise<string> {
    return join(this.root, id);
  }

  private async readMeta(dir: string): Promise<PackMeta> {
    try {
      const raw = await readTextFile(await join(dir, 'meta.json'));
      const parsed = JSON.parse(raw) as Partial<PackMeta>;
      return {
        importedAt: typeof parsed.importedAt === 'number' ? parsed.importedAt : 0,
        warnings: Array.isArray(parsed.warnings) ? parsed.warnings.filter((item) => typeof item === 'string') : [],
      };
    } catch {
      return EMPTY_META;
    }
  }

  async list(): Promise<PackSummary[]> {
    const entries = await readDir(this.root);
    const packs: PackSummary[] = [];
    for (const entry of entries) {
      if (!entry.isDirectory) continue;
      try {
        const dir = await this.dirFor(entry.name);
        const manifest = JSON.parse(await readTextFile(await join(dir, 'manifest.json'))) as Manifest;
        const nodes = JSON.parse(await readTextFile(await join(dir, 'story.json'))) as StoryNode[];
        const meta = await this.readMeta(dir);
        packs.push({
          id: manifest.id,
          name: manifest.name,
          version: manifest.version,
          engineVersion: manifest.engineVersion,
          entry: manifest.entry,
          nodeCount: Array.isArray(nodes) ? nodes.length : 0,
          importedAt: meta.importedAt,
        });
      } catch {
        // 目录损坏则跳过
      }
    }
    return packs.sort((a, b) => b.importedAt - a.importedAt);
  }

  async get(id: string): Promise<StoredPack | null> {
    const dir = await this.dirFor(id);
    try {
      const manifest = JSON.parse(await readTextFile(await join(dir, 'manifest.json'))) as Manifest;
      const nodes = JSON.parse(await readTextFile(await join(dir, 'story.json'))) as StoryNode[];
      const initialState = JSON.parse(await readTextFile(await join(dir, 'state.json'))) as GameState;
      const meta = await this.readMeta(dir);

      let battles: StoredPack['battles'];
      try {
        const raw = await readTextFile(await join(dir, 'battles.json'));
        const parsed = JSON.parse(raw) as unknown;
        if (isJsonObject(parsed) && isJsonObject(parsed.battles)) {
          battles = parsed.battles as unknown as StoredPack['battles'];
        } else if (isJsonObject(parsed)) {
          battles = parsed as unknown as StoredPack['battles'];
        }
      } catch {
        battles = undefined;
      }

      let assets: StoredPack['assets'];
      try {
        const raw = await readTextFile(await join(dir, 'assets.json'));
        const parsed = JSON.parse(raw) as unknown;
        if (isJsonObject(parsed)) assets = parsed as unknown as StoredPack['assets'];
      } catch {
        assets = undefined;
      }

      const imagePaths: Record<string, string> = {};
      let imageEntries: { name: string; isFile: boolean }[] = [];
      try {
        imageEntries = await readDir(await join(dir, 'images'));
      } catch {
        imageEntries = [];
      }
      for (const entry of imageEntries) {
        if (!entry.isFile) continue;
        const dot = entry.name.lastIndexOf('.');
        if (dot <= 0) continue;
        const logicalName = entry.name.slice(0, dot);
        const ext = entry.name.slice(dot + 1).toLowerCase();
        if (!['webp', 'png', 'jpg', 'jpeg'].includes(ext)) continue;
        imagePaths[logicalName] = await join(await join(dir, 'images'), entry.name);
      }

      const pack: ContentPack = { manifest, nodes, initialState, battles, assets };
      const stored: StoredPack = {
        id: manifest.id,
        manifest: pack.manifest,
        nodes: pack.nodes,
        initialState: pack.initialState,
        battles: pack.battles,
        assets: pack.assets,
        images: {},
        imagePaths,
        importedAt: meta.importedAt,
        warnings: meta.warnings,
      };
      return stored;
    } catch {
      return null;
    }
  }

  async put(pack: StoredPack): Promise<void> {
    const dir = await this.dirFor(pack.id);
    await mkdir(dir, { recursive: true });
    await mkdir(await join(dir, 'images'), { recursive: true });

    await writeTextFile(await join(dir, 'manifest.json'), JSON.stringify(pack.manifest, null, 2));
    await writeTextFile(await join(dir, 'story.json'), JSON.stringify(pack.nodes, null, 2));
    await writeTextFile(await join(dir, 'state.json'), JSON.stringify(pack.initialState, null, 2));
    const meta: PackMeta = { importedAt: pack.importedAt, warnings: pack.warnings };
    await writeTextFile(await join(dir, 'meta.json'), JSON.stringify(meta, null, 2));
    if (pack.battles && Object.keys(pack.battles).length > 0) {
      await writeTextFile(await join(dir, 'battles.json'), JSON.stringify({ version: 1, battles: pack.battles }, null, 2));
    }
    if (pack.assets && Object.keys(pack.assets).length > 0) {
      await writeTextFile(await join(dir, 'assets.json'), JSON.stringify(pack.assets, null, 2));
    }

    const imagesDir = await join(dir, 'images');
    for (const [logicalName, image] of Object.entries(pack.images)) {
      const ext = image.mime === 'image/png' ? 'png' : image.mime === 'image/jpeg' ? 'jpg' : 'webp';
      await writeFile(await join(imagesDir, `${logicalName}.${ext}`), image.bytes);
    }
  }

  async remove(id: string): Promise<void> {
    const dir = await this.dirFor(id);
    if (await exists(dir)) await remove(dir, { recursive: true });
  }
}
