import type { SceneView } from '../engine/engine';
import type { GameState } from '../engine/types';
import type { StoredPack } from '../storage/PackStore';
import type { AssetResolver } from '../assets/AssetResolver';
import { computeStageSlots, tierLabel } from './slots';
import { SLOT_LABELS } from './uiTypes';

export interface DebugDrawerProps {
  open: boolean;
  pack: StoredPack;
  scene: SceneView | null;
  state: GameState;
  history: string[];
  resolver: AssetResolver;
  storageLabel: string;
  storageRoot: string;
  onClose(): void;
}

export function DebugDrawer({
  open,
  pack,
  scene,
  state,
  history,
  resolver,
  storageLabel,
  storageRoot,
  onClose,
}: DebugDrawerProps) {
  if (!open) return null;
  const slots = scene ? computeStageSlots(scene, resolver, state) : null;

  return (
    <aside className="debug-drawer" role="dialog" aria-modal="false" aria-label="调试面板" data-testid="debug-panel">
      <header className="debug-header">
        <h2>调试</h2>
        <button type="button" className="icon-btn" onClick={onClose} aria-label="关闭调试面板">
          ✕
        </button>
      </header>

      <section>
        <h3>节点</h3>
        <p>
          <code>{scene?.nodeId ?? '—'}</code> · {scene?.layout ?? '—'}
        </p>
      </section>

      <section>
        <h3>存储</h3>
        <p>{storageLabel}</p>
        <p className="debug-path" data-testid="storage-root">
          <code>{storageRoot}</code>
        </p>
      </section>

      <section>
        <h3>视觉槽位</h3>
        {slots ? (
          <ul className="debug-slots">
            {[slots.bg, slots.player, ...slots.npcs, slots.map]
              .filter((item) => item !== null)
              .map((item) => (
                <li key={`${item.slot}-${item.name}`}>
                  <span className="chip">{SLOT_LABELS[item.slot] ?? item.slot}</span>
                  <code>{item.name}</code>
                  <span className={`tier tier-${item.tier}`} data-testid={`tier-${item.slot}`}>
                    L{item.tier} {tierLabel(item.tier)}
                  </span>
                </li>
              ))}
            {slots.bg === null && slots.player === null && slots.npcs.length === 0 && slots.map === null && (
              <li className="muted">本节点没有声明任何图片</li>
            )}
          </ul>
        ) : (
          <p className="muted">无节点</p>
        )}
      </section>

      <section>
        <h3>状态 state</h3>
        <pre className="debug-json" data-testid="debug-state">
          {JSON.stringify(state, null, 2)}
        </pre>
      </section>

      <section>
        <h3>历史 history（{history.length}）</h3>
        <ol className="debug-history">
          {history.map((id, index) => (
            <li key={`${id}-${index}`}>
              <code>{id}</code>
            </li>
          ))}
        </ol>
      </section>

      <section>
        <h3>内容包提示（{pack.warnings.length}）</h3>
        {pack.warnings.length === 0 ? (
          <p className="muted">无</p>
        ) : (
          <ul className="debug-warnings">
            {pack.warnings.map((warning, index) => (
              <li key={index}>{warning}</li>
            ))}
          </ul>
        )}
      </section>

      {scene && scene.issues.length > 0 && (
        <section>
          <h3>运行时降级</h3>
          <ul className="debug-warnings">
            {scene.issues.map((issue, index) => (
              <li key={index}>{issue}</li>
            ))}
          </ul>
        </section>
      )}

      <footer className="debug-footer">
        引擎 0.1.0 · {pack.manifest.id}@{pack.manifest.version}
      </footer>
    </aside>
  );
}
