import type { SceneView } from '../engine/engine';
import type { GameState, VisualSlot } from '../engine/types';
import { getPath } from '../engine/paths';
import type { AssetResolver, AssetTier } from '../assets/AssetResolver';
import { hintForSlot, inferSlot } from '../assets/AssetResolver';

export interface RenderedSlot {
  slot: VisualSlot;
  name: string;
  alt: string;
  url: string;
  tier: AssetTier;
}

export interface StageSlots {
  bg: RenderedSlot | null;
  map: RenderedSlot | null;
  player: RenderedSlot | null;
  npcs: RenderedSlot[];
}

/** 把节点 images 解析成四个标准槽位；playerPortrait 支持 bindState 动态换图。 */
export function computeStageSlots(view: SceneView, resolver: AssetResolver, state: GameState): StageSlots {
  const slots: StageSlots = { bg: null, map: null, player: null, npcs: [] };
  for (const ref of view.images) {
    if (!ref || typeof ref.placeholder !== 'string' || ref.placeholder === '') continue;
    const slot = inferSlot(ref);
    let name = ref.placeholder;
    if (slot === 'playerPortrait' && typeof ref.bindState === 'string' && ref.bindState !== '') {
      const bound = getPath(state, ref.bindState);
      if (typeof bound === 'string' && bound !== '') name = bound;
    }
    const asset = resolver.resolve(name, hintForSlot(slot));
    const rendered: RenderedSlot = {
      slot,
      name,
      alt: ref.alt ?? name,
      url: asset.url,
      tier: asset.tier,
    };
    if (slot === 'bg') slots.bg = rendered;
    else if (slot === 'map') slots.map = rendered;
    else if (slot === 'playerPortrait') slots.player = rendered;
    else slots.npcs.push(rendered);
  }
  return slots;
}

export function tierLabel(tier: AssetTier): string {
  if (tier === 1) return '包内图';
  if (tier === 2) return '内置占位';
  return '纯色块';
}
