import { useState, type ReactNode } from 'react';
import type { StageSlots, RenderedSlot } from './slots';
import { tierLabel } from './slots';

export interface StageProps {
  slots: StageSlots;
  showTiers: boolean;
  children?: ReactNode;
}

interface SlotImageProps {
  slot: RenderedSlot;
  className: string;
  showTier: boolean;
  caption?: string;
}

function SlotImage({ slot, className, showTier, caption }: SlotImageProps) {
  const [broken, setBroken] = useState(false);
  const label = caption ?? slot.alt;
  if (slot.slot === 'bg' && slot.tier === 3) {
    return (
      <div className="slot-bg-fallback" role="img" aria-label={label} data-tier={3} data-slot="bg" data-name={slot.name}>
        <img src={slot.url} alt="" aria-hidden="true" draggable={false} />
        <div className="slot-bg-fallback-label">
          <strong>{slot.name}</strong>
          <span>缺失资源 · 背景 bg</span>
        </div>
      </div>
    );
  }
  if (broken) {
    return (
      <div className={`${className} slot-broken`} role="img" aria-label={label} data-tier={slot.tier}>
        <span>{label}</span>
      </div>
    );
  }
  return (
    <span className={`${className}-wrap`} data-tier={slot.tier} data-slot={slot.slot} data-name={slot.name}>
      <img className={className} src={slot.url} alt={label} draggable={false} onError={() => setBroken(true)} />
      {showTier && (
        <em className="tier-badge">
          L{slot.tier} {tierLabel(slot.tier)}
        </em>
      )}
    </span>
  );
}

export function Stage({ slots, showTiers, children }: StageProps) {
  const [mapOpen, setMapOpen] = useState(false);
  return (
    <div className="stage">
      {slots.bg ? (
        <SlotImage slot={slots.bg} className="slot-bg" showTier={showTiers} caption={slots.bg.alt} />
      ) : (
        <div className="slot-bg slot-bg-empty" aria-hidden="true" />
      )}

      <div className="stage-figures">
        {slots.player && (
          <figure className="figure figure-player">
            <SlotImage slot={slots.player} className="slot-player" showTier={showTiers} caption={slots.player.alt} />
          </figure>
        )}
        {slots.npcs.length > 0 && (
          <div className="figure-group">
            {slots.npcs.map((npc, index) => (
              <figure className="figure" key={`${npc.name}-${index}`}>
                <SlotImage slot={npc} className="slot-npc" showTier={showTiers} caption={npc.alt} />
              </figure>
            ))}
          </div>
        )}
      </div>

      {slots.map && (
        <button
          type="button"
          className="slot-map"
          onClick={() => setMapOpen(true)}
          aria-label={`查看地图：${slots.map.alt}`}
        >
          <img src={slots.map.url} alt={slots.map.alt} draggable={false} />
          <span className="slot-map-label">地图</span>
          {showTiers && <em className="tier-badge tier-badge-map">L{slots.map.tier}</em>}
        </button>
      )}

      {children}

      {mapOpen && slots.map && (
        <div className="map-modal" role="dialog" aria-modal="true" aria-label="世界地图">
          <button type="button" className="map-modal-close" onClick={() => setMapOpen(false)} aria-label="关闭地图">
            ✕
          </button>
          <img src={slots.map.url} alt={slots.map.alt} />
          <p className="map-modal-caption">
            {slots.map.alt} · {tierLabel(slots.map.tier)}
          </p>
        </div>
      )}
    </div>
  );
}
