import { useEffect, useMemo, useState } from 'react';
import type { BattleActionId, BattleDefinition, BattleResult, BattleSnapshot } from '../engine/battle/types';
import { BattleSimulator } from '../engine/battle/simulator';
import type { AssetResolver } from '../assets/AssetResolver';

const INTENT_TEXT: Record<string, string> = {
  disarm: '她盯着你的武器——下一步可能把它打落',
  throwBody: '她抬起脚，下一步可能用石头砸你的身体',
  counter: '她盯住了你的手，准备反击',
  retreat: '她会后退，把距离拉回 5 格',
  hold: '她停在原地，等你先动',
  idle: '她暂时按兵不动',
};

const RESULT_TEXT: Record<BattleResult, string> = {
  win: '米埃尔倒在地上。',
  lose: '你再也抬不起手臂，眼前一黑。',
  flee: '你退到足够远的地方，转身离开。',
  stolen: '她带着你的短刀退进荒野。',
  confiscated: '所有人倒在地上，武器被她一一收走。',
  fled_armed: '她追上来夺走你的刀，才放你走。',
  fled_unarmed: '你空着手撤退，她没有追。',
  escaped: '她退到十格外，转身消失在荒野里。',
  stunnedFlee: '你趁她僵住，退到十格外。',
};

export interface BattleScreenProps {
  definition: BattleDefinition;
  resolver: AssetResolver;
  hasBlowgun?: boolean;
  proficiency?: number;
  samuelHelp?: boolean;
  forceBlowgun?: boolean;
  allowFlee?: boolean;
  onFinish(result: BattleResult, taken?: { weaponTaken: boolean; blowgunTaken: boolean }): void;
}

export function BattleScreen({ definition, resolver, hasBlowgun, proficiency, samuelHelp, forceBlowgun, allowFlee, onFinish }: BattleScreenProps) {
  const simulator = useMemo(
    () =>
      new BattleSimulator(definition, {
        hasBlowgun: Boolean(hasBlowgun),
        proficiency,
        samuelHelp,
        allowFlee: allowFlee ?? !forceBlowgun,
      }),
    [definition, hasBlowgun, forceBlowgun, proficiency, samuelHelp],
  );
  const [snap, setSnap] = useState<BattleSnapshot>(() => simulator.snapshot);

  useEffect(() => {
    setSnap(simulator.snapshot);
    const timer = window.setInterval(() => {
      simulator.tick(100);
      setSnap(simulator.snapshot);
    }, 100);
    return () => window.clearInterval(timer);
  }, [simulator]);

  const actors = snap.actors;
  const player = actors.find((actor) => actor.team === 'player');
  const enemy = actors.find((actor) => actor.team === 'enemy');

  const background = useMemo(
    () => (definition.background ? resolver.resolve(definition.background, 'bg') : null),
    [definition.background, resolver],
  );

  const portraits = useMemo(() => {
    const resolve = (name?: string) => (name ? resolver.resolve(name, 'portrait') : null);
    return { player: resolve(player?.portrait), enemy: resolve(enemy?.portrait) };
  }, [resolver, player?.portrait, enemy?.portrait]);

  const fleeAction = snap.actions.find((action) => action.id === 'flee');
  const stunFlee = snap.status.some((status) => status.startsWith('麻醉'));
  const fleeDisplay = fleeAction
    ? { ...fleeAction, label: stunFlee ? '趁麻醉撤离' : fleeAction.label }
    : null;
  const visibleActions = snap.actions.filter((action) => action.id !== 'flee');
  if (fleeDisplay) visibleActions.push(fleeDisplay);

  const handleAction = (id: BattleActionId) => {
    if (simulator.act(id)) setSnap(simulator.snapshot);
  };

  return (
    <div className="battle">
      {background && <img className="battle-bg" src={background.url} alt="" aria-hidden="true" />}

      <header className="battle-hud">
        <span className="battle-title">战斗</span>
        <span className="battle-distance-label">
          距离 <strong data-testid="battle-distance">{snap.distance}</strong> 格
        </span>
        <span className="battle-weapon" data-testid="battle-weapon">
          {snap.weapon.state === 'equipped'
            ? '武器：手上'
            : snap.weapon.state === 'stolen'
              ? '武器：被她拿走'
              : (snap.weapon.delta ?? 0) === 0
                ? '武器：脚下'
                : snap.weapon.delta! > 0
                  ? `武器：前方 ${snap.weapon.delta} 格`
                  : `武器：身后 ${Math.abs(snap.weapon.delta!)} 格`}
        </span>
        {snap.blowgun && (
          <span className="battle-weapon" data-testid="battle-blowgun">
            {snap.blowgun.state === 'equipped'
              ? '吹箭筒：手上'
              : snap.blowgun.state === 'stolen'
                ? '吹箭筒：被抢走'
                : (snap.blowgun.delta ?? 0) === 0
                  ? '吹箭筒：脚下'
                  : snap.blowgun.delta! > 0
                    ? `吹箭筒：前方 ${snap.blowgun.delta} 格`
                    : `吹箭筒：身后 ${Math.abs(snap.blowgun.delta!)} 格`}
          </span>
        )}
      </header>

      <div className="battle-stage">
        <div className="battle-side battle-side-player">
          <div className="battle-portrait battle-portrait-player">
            {portraits.player ? <img src={portraits.player.url} alt={player?.name ?? ''} /> : <div className="battle-portrait-empty" />}
          </div>
          <div className="battle-actor-info">
            <strong>{player?.name ?? '你'}</strong>
            <StaminaBar value={player?.stamina ?? 0} max={player?.maxStamina ?? 100} tone="player" />
            <GaugeBar value={player?.gauge ?? 0} tone="player" />
          </div>
        </div>

        <div className="battle-side battle-side-enemy">
          <div className="battle-portrait battle-portrait-enemy">
            {portraits.enemy ? <img src={portraits.enemy.url} alt={enemy?.name ?? ''} /> : <div className="battle-portrait-empty" />}
          </div>
          <div className="mier-status-list">
            {snap.status.map((status) => (
              <span key={status} className="mier-status" data-testid="battle-status">
                {status}
              </span>
            ))}
          </div>
          <div className="battle-actor-info">
            <strong>{enemy?.name ?? '米埃尔'}</strong>
            <StaminaBar value={enemy?.stamina ?? 0} max={enemy?.maxStamina ?? 100} tone="enemy" />
            <GaugeBar value={enemy?.gauge ?? 0} tone="enemy" />
          </div>
        </div>
      </div>

      <div className="battle-distance-track" aria-hidden="true">
        {Array.from({ length: snap.distanceConfig.max + 1 }, (_, index) => (
          <span
            key={index}
            className={[
              'battle-cell',
              index === snap.distance ? 'is-enemy' : '',
              index === 0 ? 'is-player' : '',
              index === snap.weapon.delta && snap.weapon.state === 'ground' ? 'is-weapon' : '',
              index === snap.blowgun?.delta && snap.blowgun?.state === 'ground' ? 'is-blowgun' : '',
            ]
              .filter(Boolean)
              .join(' ')}
            title={index === snap.weapon.cell && snap.weapon.state === 'ground' ? '掉落的武器' : undefined}
          />
        ))}
      </div>

      <div className="battle-intent" data-testid="battle-intent">
        下一步：{snap.intent ? INTENT_TEXT[snap.intent] ?? snap.intent : '—'}
      </div>

      <div className="battle-log" aria-live="polite">
        {snap.log.slice(-3).map((entry, index) => (
          <p key={`${index}-${entry.text}`} className={`battle-log-${entry.kind}`}>
            {entry.text}
          </p>
        ))}
      </div>

      <div className="battle-actions" data-testid="battle-actions">
        {visibleActions.map((action) => (
          <button
            key={action.id}
            type="button"
            className="battle-action"
            disabled={!action.available || snap.phase !== 'playerTurn'}
            onClick={() => handleAction(action.id)}
            data-testid={`battle-action-${action.id}`}
            title={action.reason}
          >
            <span>{action.label}</span>
            {action.reason && <small>{action.reason}</small>}
          </button>
        ))}
      </div>

      {snap.phase === 'finished' && snap.result && (        <div className="battle-result" role="dialog" aria-modal="true" aria-label="战斗结束" data-testid="battle-result">
          <div className="battle-result-card">
            <h2>
              {snap.result === 'win'
                ? '战斗胜利'
                : snap.result === 'lose'
                  ? '你倒下了'
                  : snap.result === 'stolen'
                    ? '武器被夺走'
                    : '脱离战斗'}
            </h2>
            <p>{RESULT_TEXT[snap.result]}</p>
            {snap.pinned && snap.result !== 'flee' && (
              <p className="battle-result-quip">她整理了一下被弄乱的衣服，轻轻地骂了一句：「臭流氓……乱摸个什么劲！」</p>
            )}
            <p className="muted">用时 {snap.elapsedSeconds.toFixed(1)} 秒</p>
            <button
              type="button"
              className="btn btn-primary"
              onClick={() =>
                onFinish(snap.result as BattleResult, {
                  weaponTaken: snap.weapon.state === 'stolen',
                  blowgunTaken: snap.blowgun?.state === 'stolen',
                })
              }
              data-testid="battle-continue"
            >
              继续
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export function StaminaBar({ value, max, tone }: { value: number; max: number; tone: 'player' | 'enemy' }) {
  const percent = Math.max(0, Math.min(100, (value / max) * 100));
  return (
    <div className={`battle-bar battle-bar-stamina ${tone}`}>
      <span style={{ width: `${percent}%` }} />
      <em>
        体力 {Math.round(value)}/{max}
      </em>
    </div>
  );
}

export function GaugeBar({ value, tone }: { value: number; tone: 'player' | 'enemy' }) {
  return (
    <div className={`battle-bar battle-bar-gauge ${tone}`}>
      <span style={{ width: `${Math.max(0, Math.min(100, value))}%` }} />
      <em>行动 {Math.round(value)}%</em>
    </div>
  );
}
