import { useMemo } from 'react';
import type { AssetResolver } from '../assets/AssetResolver';
import type { SceneView } from '../engine/engine';
import type { GameState } from '../engine/types';
import type { StoredPack } from '../storage/PackStore';
import { computeStageSlots } from './slots';
import { Stage } from './Stage';
import { MISSING_COPY, type MissingInfo } from './uiTypes';

export interface GameScreenProps {
  pack: StoredPack;
  state: GameState;
  scene: SceneView | null;
  missing: MissingInfo | null;
  resolver: AssetResolver;
  showTiers: boolean;
  onToggleTiers(): void;
  onBack(): void;
  onOpenSaves(): void;
  onOpenDebug(): void;
  onChoose(index: number): void;
  onReturnFromMissing(): void;
}

function StoryPanel({
  scene,
  overlay,
  onChoose,
  onBack,
}: {
  scene: SceneView;
  overlay: boolean;
  onChoose(index: number): void;
  onBack(): void;
}) {
  const visible = scene.choices.filter((choice) => choice.visible);
  return (
    <section className={overlay ? 'story story-overlay' : 'story story-flow'} data-testid="story">
      <p className="story-text" data-testid="story-text">
        {scene.text}
      </p>

      {scene.issues.length > 0 && (
        <ul className="issue-list" role="status">
          {scene.issues.map((issue, i) => (
            <li key={i}>{issue}</li>
          ))}
        </ul>
      )}

      <div className="choices" data-testid="choices">
        {visible.map((choice) => (
          <button
            type="button"
            key={choice.index}
            className="choice"
            data-testid={`choice-${choice.index}`}
            disabled={!choice.enabled}
            onClick={() => onChoose(choice.index)}
          >
            <span>{choice.text}</span>
            {!choice.enabled && <small>{choice.lockedReason ?? '未解锁'}</small>}
          </button>
        ))}
        {visible.length === 0 && (
          <div className="choice-empty">
            <p>内容包没有给出可选项，本节点到此为止。</p>
            <button type="button" className="btn" onClick={onBack}>
              回到标题
            </button>
          </div>
        )}
      </div>
    </section>
  );
}

export function GameScreen({
  pack,
  state,
  scene,
  missing,
  resolver,
  showTiers,
  onToggleTiers,
  onBack,
  onOpenSaves,
  onOpenDebug,
  onChoose,
  onReturnFromMissing,
}: GameScreenProps) {
  const slots = useMemo(
    () => (scene ? computeStageSlots(scene, resolver, state) : null),
    [scene, resolver, state],
  );
  const missingCopy = missing ? MISSING_COPY[missing.reason] : null;

  return (
    <div className={`game layout-${scene?.layout ?? 'stacked'}`} data-testid="game">
      <header className="hud">
        <button type="button" className="icon-btn" onClick={onBack} aria-label="返回标题">
          ←
        </button>
        <div className="hud-title">
          <strong>{pack.manifest.name}</strong>
          <span>
            v{pack.manifest.version} · <code data-testid="current-node">{scene?.nodeId ?? '—'}</code>
          </span>
        </div>
        <button type="button" className="btn btn-ghost" onClick={onOpenSaves} data-testid="open-saves">
          存档
        </button>
        <button type="button" className="btn btn-ghost" onClick={onOpenDebug} data-testid="open-debug">
          调试
        </button>
        <button
          type="button"
          className={`btn btn-ghost ${showTiers ? 'is-on' : ''}`}
          onClick={onToggleTiers}
          aria-pressed={showTiers}
          title="显示资源回退层级"
        >
          回退标记
        </button>
      </header>

      {slots ? (
        <Stage slots={slots} showTiers={showTiers}>
          {scene && scene.layout === 'background' && (
            <StoryPanel scene={scene} overlay onChoose={onChoose} onBack={onBack} />
          )}
        </Stage>
      ) : (
        <div className="stage stage-placeholder">
          <p>没有可显示的节点。</p>
        </div>
      )}

      {scene && scene.layout !== 'background' && (
        <StoryPanel scene={scene} overlay={false} onChoose={onChoose} onBack={onBack} />
      )}

      {missing && missingCopy && (
        <div className="missing-overlay" role="alertdialog" aria-modal="true" aria-label={missingCopy.title}>
          <div className="missing-card">
            <p className="error-code" data-testid="missing-code">
              {missingCopy.code}
            </p>
            <h2>{missingCopy.title}</h2>
            <p data-testid="missing-message">{missing.message}</p>
            <p className="muted">
              目标节点：<code>{missing.targetId}</code>
            </p>
            <p className="muted">{missingCopy.body}</p>
            <p className="muted">{missingCopy.hint}</p>
            <div className="missing-actions">
              {missingCopy.action === 'saves' && (
                <button type="button" className="btn btn-primary" onClick={onOpenSaves} data-testid="missing-saves">
                  读取其他存档
                </button>
              )}
              {missingCopy.action === 'back' && missing.returnNodeId && (
                <button type="button" className="btn btn-primary" onClick={onReturnFromMissing} data-testid="missing-back">
                  返回当前节点
                </button>
              )}
              <button type="button" className="btn" onClick={onBack} data-testid="missing-title">
                回到标题
              </button>
            </div>
            <p className="muted error-code-hint">反馈问题时请附上错误码 {missingCopy.code}</p>
          </div>
        </div>
      )}
    </div>
  );
}
