import { useRef } from 'react';
import type { StoredPack } from '../storage/PackStore';

export interface FileButtonProps {
  label: string;
  accept: string;
  onFile(file: File): void;
  disabled?: boolean;
  className?: string;
  testId?: string;
}

/**
 * 隐藏的 file input + 按钮。
 * Web 与 WebView2 都支持 File API，因此导入 zip / 存档统一走这里，不依赖 File System Access API。
 */
export function FileButton({ label, accept, onFile, disabled, className, testId }: FileButtonProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  return (
    <>
      <button
        type="button"
        className={className ?? 'btn'}
        disabled={disabled}
        onClick={() => inputRef.current?.click()}
      >
        {label}
      </button>
      <input
        ref={inputRef}
        type="file"
        accept={accept}
        hidden
        data-testid={testId ?? `file-${label}`}
        onChange={(event) => {
          const file = event.target.files?.[0];
          if (file) onFile(file);
          event.target.value = '';
        }}
      />
    </>
  );
}

export function packFileName(pack: StoredPack, slot: string, timestamp: number): string {
  return `${pack.manifest.id}_${slot}_${timestamp}.json`;
}
