export type ColorBlockHint = 'bg' | 'portrait' | 'map';

/**
 * 三级资源回退里与平台无关的第 2、3 级：
 * 2) 框架内置占位图（Vite 打包成 data URI）
 * 3) 运行时生成的纯色块（带逻辑名）
 */
const BUILTIN_PLACEHOLDERS = import.meta.glob('./placeholders/*.svg', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

function basename(path: string): string {
  const clean = path.replace(/\\/g, '/');
  const file = clean.slice(clean.lastIndexOf('/') + 1);
  return file.replace(/\.[^.]+$/, '');
}

export function resolveBuiltin(logicalName: string): string | undefined {
  for (const [path, url] of Object.entries(BUILTIN_PLACEHOLDERS)) {
    if (basename(path) === logicalName) return url;
  }
  return undefined;
}

function hashHue(name: string): number {
  let hash = 0;
  for (let i = 0; i < name.length; i += 1) hash = (hash * 31 + name.charCodeAt(i)) >>> 0;
  return hash % 360;
}

export function colorBlockSvg(logicalName: string, hint: ColorBlockHint): string {
  const width = hint === 'portrait' ? 720 : 1280;
  const height = hint === 'portrait' ? 960 : 720;
  const hue = hashHue(logicalName);
  const from = `hsl(${hue} 32% 22%)`;
  const to = `hsl(${(hue + 40) % 360} 38% 12%)`;
  const safeName = logicalName.replace(/[<>&]/g, '');
  const displayName = safeName.length > 20 ? `${safeName.slice(0, 19)}…` : safeName;
  const slotLabel = hint === 'bg' ? '背景 bg' : hint === 'map' ? '地图 map' : '立绘 portrait';
  const fillOpacity = hint === 'portrait' ? 0.62 : 1;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">
    <stop offset="0" stop-color="${from}"/><stop offset="1" stop-color="${to}"/>
  </linearGradient></defs>
  <rect width="${width}" height="${height}" fill="url(#g)" fill-opacity="${fillOpacity}"/>
  <rect x="24" y="24" width="${width - 48}" height="${height - 48}" fill="none" stroke="rgba(255,255,255,0.18)" stroke-width="3" stroke-dasharray="14 10"/>
  <g fill="rgba(255,255,255,0.78)" font-family="ui-monospace,Consolas,monospace" text-anchor="start">
    <text x="44" y="${hint === 'portrait' ? 92 : 74}" font-size="${hint === 'portrait' ? 44 : 34}">${displayName}</text>
    <text x="44" y="${hint === 'portrait' ? 136 : 110}" font-size="${hint === 'portrait' ? 26 : 20}" fill="rgba(255,255,255,0.5)">缺失资源 · ${slotLabel}</text>
  </g>
</svg>`;
}

export function colorBlockDataUrl(logicalName: string, hint: ColorBlockHint): string {
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(colorBlockSvg(logicalName, hint))}`;
}
