import type {
  BattleActionConfig,
  BattleActionId,
  BattleActionView,
  BattleAiConfig,
  BattleDefinition,
  BattleIntent,
  BattleLogEntry,
  BattleParticipantDef,
  BattleResult,
  BattleSnapshot,
} from './types';

const ACTION_LABELS: Record<BattleActionId, string> = {
  moveCloser: '靠近',
  moveAway: '远离',
  melee: '近程攻击',
  throwStone: '丢石头',
  blowgun: '吹箭',
  pickupWeapon: '捡起武器',
  pickupBlowgun: '捡吹箭筒',
  dart: '让塞缪尔吹麻醉镖',
  pin: '扣住米埃尔',
  wait: '原地待机',
  flee: '逃离战斗',
};

const ACTION_DEFAULTS: Record<BattleActionId, BattleActionConfig> = {
  moveCloser: { staminaCost: 10 },
  moveAway: { staminaCost: 10 },
  melee: { staminaCost: 10, range: 1, enemyStaminaLoss: 0, dodge: 1 },
  throwStone: { staminaCost: 5, enemyStaminaLoss: 1, dodge: 1 },
  blowgun: { staminaCost: 5, enemyStaminaLoss: 5, dodge: 0 },
  pickupWeapon: { staminaCost: 5 },
  pickupBlowgun: { staminaCost: 5 },
  dart: { staminaCost: 0 },
  pin: { staminaCost: 0 },
  wait: { staminaCost: 0, staminaGain: 10 },
  flee: { staminaCost: 0 },
};

const AI_DEFAULTS: Required<BattleAiConfig> = {
  keepDistance: 5,
  retreatStaminaCost: 5,
  noChaseBeyond: 8,
  retreatActionCost: 50,
  kickActionCost: 50,
  kickDamage: 10,
  kickDistance: 1,
};

interface ActorState {
  def: BattleParticipantDef;
  stamina: number;
  gauge: number;
}

/**
 * 回合制决斗模拟器（纯逻辑，不依赖 DOM / 计时器）。
 * 行动值按速度填充，满 100 行动；玩家回合暂停，世界时间不推进。
 */
export class BattleSimulator {
  readonly definition: BattleDefinition;
  private readonly actorsState: ActorState[];
  private readonly actions: Record<BattleActionId, BattleActionConfig>;
  private readonly ai: Required<BattleAiConfig>;
  private readonly mode: 'duel' | 'challenge';
  private readonly options: { hasBlowgun: boolean; proficiency: number; samuelHelp: boolean; allowFlee?: boolean };
  private distance: number;
  private playerStep = 0;
  private weapon: { state: 'equipped' | 'ground' | 'stolen'; cell?: number };
  private blowgun: { state: 'equipped' | 'ground' | 'stolen'; cell?: number };
  private dartUsed = false;
  private dartUntil = 0;
  private mierSensitive = false;
  private phase: 'running' | 'playerTurn' | 'finished' = 'running';
  private logEntries: BattleLogEntry[] = [];
  private elapsed = 0;
  private result: BattleResult | undefined;
  private kicked = false;
  private playerLocked = false;
  private pinUsed = false;

  constructor(definition: BattleDefinition, options?: { hasBlowgun?: boolean; proficiency?: number; samuelHelp?: boolean; allowFlee?: boolean }) {
    this.definition = definition;
    this.options = {
      hasBlowgun: options?.hasBlowgun ?? false,
      proficiency: Math.max(0, Math.min(100, options?.proficiency ?? 0)),
      samuelHelp: options?.samuelHelp ?? false,
      allowFlee: options?.allowFlee ?? true,
    };
    this.blowgun = { state: this.options.hasBlowgun ? 'equipped' : 'stolen' };
    this.distance = definition.distance.initial;
    this.actorsState = definition.participants.map((participant) => ({
      def: participant,
      stamina: participant.stamina,
      gauge: 0,
    }));
    this.actions = { ...ACTION_DEFAULTS };
    for (const key of Object.keys(definition.actions ?? {}) as BattleActionId[]) {
      this.actions[key] = { ...ACTION_DEFAULTS[key], ...(definition.actions?.[key] ?? {}) };
    }
    this.ai = { ...AI_DEFAULTS, ...(definition.ai ?? {}) };
    this.mode = definition.mode === 'challenge' ? 'challenge' : 'duel';
    this.weapon = { state: 'equipped' };
    this.pushLog(`距离 ${this.distance} 格。`, 'info');
  }

  /** 推进时间；玩家回合或战斗结束时不再推进。 */
  tick(deltaMs: number): void {
    if (this.phase !== 'running') return;
    const dt = Math.max(0, Math.min(deltaMs, 500)) / 1000;
    this.elapsed += dt;

    if (this.playerLocked) {
      if (this.elapsed >= this.dartUntil) {
        const player = this.player();
        player.stamina = Math.max(0, player.stamina - 10);
        this.distance = Math.min(this.definition.distance.max, 2);
        this.playerLocked = false;
        this.pushLog('麻醉结束，米埃尔把你撞开，体力 -10。', 'damage');
        this.phase = 'playerTurn';
        this.resolveOutcome();
      }
      return;
    }

    const regen = this.definition.time?.regenPerSecond ?? 1;
    for (const actor of this.actorsState) {
      actor.stamina = Math.min(actor.def.stamina, actor.stamina + regen * dt);
    }

    const threshold = this.definition.actionValue?.threshold ?? 100;
    for (const actor of this.actorsState) {
      if (actor.def.team === 'enemy' && this.elapsed < this.dartUntil) continue;
      actor.gauge = Math.min(threshold, actor.gauge + actor.def.speed * dt);
    }

    const enemy = this.enemy();
    if (this.options.hasBlowgun) {
      if (enemy.stamina < 50) this.mierSensitive = true;
      if (this.mierSensitive) {
        enemy.stamina = Math.min(enemy.def.stamina, enemy.stamina + 10 * dt);
        if (enemy.stamina >= 50) {
          this.mierSensitive = false;
        } else if (this.elapsed >= this.dartUntil) {
          if (this.distance < this.definition.distance.max) {
            this.distance += 1;
            this.pushLog(`她向后退开，距离 ${this.distance} 格。`, 'enemy');
          } else {
            this.finish('escaped');
            return;
          }
        }
      }
    }

    if (this.mode !== 'challenge' && this.options.hasBlowgun && !this.mierSensitive && enemy.gauge >= threshold - 1e-6) {
      const player = this.player();
      if (this.blowgun.state === 'equipped') {
        this.blowgun = { state: 'ground', cell: this.playerStep };
        player.stamina = Math.max(0, player.stamina - 10);
        this.pushLog('米埃尔打落你的吹箭筒，体力 -10。', 'damage');
      } else {
        player.stamina = Math.max(0, player.stamina - 10);
        this.pushLog('米埃尔用石头砸中你，体力 -10。', 'damage');
      }
      enemy.gauge = 0;
      this.resolveOutcome();
      if (this.isFinished()) return;
    }

    if (this.mode === 'challenge') {
      // 挑战模式：她的每一步都只花 50 行动值，按「打落 → 逼近 → 踹 → 抢武器 → 拉开 10 格」推进。
      for (let guard = 0; guard < 8 && !this.isFinished(); guard += 1) {
        if (!this.challengeStep()) break;
      }
      if (this.isFinished()) return;
    } else if (!this.options.hasBlowgun && this.weapon.state === 'equipped' && enemy.gauge >= threshold - 1e-6) {
      // 武器还在手上：她行动值满了就先打落武器，然后保持满行动值待机。
      this.disarm(enemy);
      this.resolveOutcome();
      if (this.isFinished()) return;
    }

    // 武器被打落后，她不再主动出手，停在 100% 行动值等玩家触发。
    const player = this.player();
    if (player.gauge >= threshold - 1e-6) {
      this.phase = 'playerTurn';
    }
  }

  private challengeStep(): boolean {
    if (this.phase !== 'running') return false;
    const enemy = this.enemy();
    const threshold = this.definition.actionValue?.threshold ?? 100;
    if (enemy.gauge < threshold - 1e-6) return false;
    const cost = this.ai.retreatActionCost;

    const hasGroundItems = this.weapon.state === 'ground' || (this.options.hasBlowgun && this.blowgun.state === 'ground');
    if (this.distance <= 1 && !hasGroundItems && this.elapsed >= this.dartUntil) {
      const player = this.player();
      player.stamina = Math.max(0, player.stamina - 10);
      this.distance = Math.min(this.definition.distance.max, 2);
      enemy.gauge = Math.max(0, enemy.gauge - cost);
      this.pushLog('米埃尔一脚把你踢开，距离回到 2 格，体力 -10。', 'damage');
      this.resolveOutcome();
      return !this.isFinished();
    }

    if (this.options.hasBlowgun) {
      // 先打落吹箭筒，再打落武器；两样都捡走后逐格后退
      if (this.blowgun.state === 'equipped') {
        this.blowgun = { state: 'ground', cell: this.playerStep };
        const player = this.player();
        player.stamina = Math.max(0, player.stamina - 10);
        enemy.gauge = Math.max(0, enemy.gauge - cost);
        this.pushLog('米埃尔打落你的吹箭筒，体力 -10。', 'damage');
        return !this.isFinished();
      }
      if (this.weapon.state === 'equipped') {
        this.disarm(enemy);
        enemy.gauge = Math.max(0, enemy.gauge - cost);
        return !this.isFinished();
      }
      if (this.weapon.state === 'ground') {
        const items: Array<{ kind: 'weapon' | 'blowgun'; cell: number }> = [];
        if (this.blowgun.state === 'ground') items.push({ kind: 'blowgun', cell: this.blowgun.cell ?? this.playerStep });
        items.push({ kind: 'weapon', cell: this.weapon.cell ?? this.playerStep });
        const target = items.sort((a, b) => b.cell - a.cell)[0];
        const offset = target.cell - this.playerStep;
        const targetDistance = Math.max(0, offset);

        if (this.distance > targetDistance) {
          this.distance = Math.max(this.definition.distance.min, this.distance - 1);
          enemy.gauge = Math.max(0, enemy.gauge - cost);
          this.pushLog(`她绕开你，朝地上的东西走去，距离 ${this.distance} 格。`, 'enemy');
          return true;
        }
        if (offset < 0 && !this.kicked) {
          this.kicked = true;
          const player = this.player();
          player.stamina = Math.max(0, player.stamina - 10);
          enemy.gauge = Math.max(0, enemy.gauge - cost);
          this.pushLog('你挡在她和掉落物之间，她一脚把你踹开，体力 -10。', 'damage');
          this.resolveOutcome();
          return !this.isFinished();
        }
        enemy.gauge = Math.max(0, enemy.gauge - cost);
        if (target.kind === 'blowgun') {
          this.blowgun = { state: 'stolen' };
          this.pushLog('她捡起你的吹箭筒。', 'enemy');
        } else {
          this.weapon = { state: 'stolen' };
          this.pushLog('她捡起你的短刀。', 'enemy');
        }
        return true;
      }
      if (this.weapon.state === 'stolen') {
        const max = this.definition.distance.max;
        if (this.distance < max) {
          this.distance += 1;
          enemy.gauge = Math.max(0, enemy.gauge - cost);
          this.pushLog(`她向后退开，距离 ${this.distance} 格。`, 'enemy');
          return true;
        }
        this.finish('stolen');
        return false;
      }
    }

    if (this.weapon.state === 'equipped') {
      this.disarm(enemy);
      enemy.gauge = Math.max(0, enemy.gauge - cost);
      return !this.isFinished();
    }

    // 抢到武器后，一步步退到她那一侧的 10 格，再离开
    if (this.weapon.state === 'stolen') {
      const max = this.definition.distance.max;
      if (this.distance < max) {
        this.distance = Math.min(max, this.distance + 1);
        enemy.gauge = Math.max(0, enemy.gauge - cost);
        this.pushLog(`她向后跃开，距离 ${this.distance} 格。`, 'enemy');
        return true;
      }
      this.finish('stolen');
      return false;
    }

    if (this.weapon.state !== 'ground') return false;

    // 她的目标是武器：武器在你前方（你后退了）就直接走向武器；在你脚下或身后就先踹开你
    const cell = this.weapon.cell ?? this.playerStep;
    const ahead = Math.max(0, cell - this.playerStep);
    const needKick = cell <= this.playerStep;
    const targetDistance = ahead;

    if (this.distance > targetDistance) {
      this.distance = Math.max(this.definition.distance.min, this.distance - 1);
      enemy.gauge = Math.max(0, enemy.gauge - cost);
      this.pushLog(`她朝地上的短刀走去，距离 ${this.distance} 格。`, 'enemy');
      return true;
    }

    if (needKick && !this.kicked) {
      this.kicked = true;
      const player = this.player();
      player.stamina = Math.max(0, player.stamina - this.ai.kickDamage);
      enemy.gauge = Math.max(0, enemy.gauge - cost);
      this.pushLog(`她一脚踹开你，体力 -${this.ai.kickDamage}。`, 'damage');
      this.resolveOutcome();
      return !this.isFinished();
    }

    if (this.weapon.state === 'ground') {
      const player = this.player();
      this.weapon = { state: 'stolen' };
      enemy.gauge = Math.max(0, enemy.gauge - cost);
      this.pushLog('她捡起你的短刀。', 'enemy');
      if (player.stamina <= 0) this.resolveOutcome();
      return !this.isFinished();
    }
    return false;
  }

  private isFinished(): boolean {
    return this.phase === 'finished';
  }

  /** 玩家行动；只有 phase=playerTurn 时有效，非法动作返回 false。 */
  act(action: BattleActionId): boolean {
    if (this.phase !== 'playerTurn') return false;
    const view = this.actionsView().find((item) => item.id === action);
    if (!view || !view.available) return false;

    const player = this.player();
    const config = this.actions[action];

    switch (action) {
      case 'moveCloser': {
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        this.distance = Math.max(this.definition.distance.min, this.distance - 1);
        this.playerStep += 1;
        this.pushLog(`你向前逼近，距离 ${this.distance} 格。`, 'player');
        break;
      }
      case 'moveAway': {
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        this.distance = Math.min(this.definition.distance.max, this.distance + 1);
        this.playerStep -= 1;
        this.pushLog(`你向后退开，距离 ${this.distance} 格。`, 'player');
        if (this.distance >= this.definition.distance.fleeAt) {
          player.gauge = 0;
          this.phase = 'playerTurn';
          this.resolveOutcome();
          return true;
        }
        break;
      }
      case 'melee': {
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        this.playerAttack(config, '你挥刀砍向米埃尔');
        break;
      }
      case 'throwStone': {
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        this.playerAttack(config, '你捡起一块石头砸向米埃尔');
        break;
      }
      case 'blowgun': {
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        const hit = Math.random() * 100 < this.options.proficiency;
        this.pushLog(hit ? '吹箭命中米埃尔，体力 -5。' : '吹箭偏了，扎在岩壁上。', hit ? 'damage' : 'player');
        if (hit) this.enemy().stamina = Math.max(0, this.enemy().stamina - 5);
        break;
      }
      case 'pickupBlowgun': {
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        this.blowgun = { state: 'equipped' };
        this.pushLog('你捡回了吹箭筒。', 'player');
        break;
      }
      case 'pin': {
        if (this.distance > 1 || this.elapsed >= this.dartUntil) return false;
        this.playerLocked = true;
        this.pinUsed = true;
        this.phase = 'running';
        this.pushLog('你死死扣住米埃尔，把她压在原地。', 'player');
        return true;
      }
      case 'dart': {
        if (this.dartUsed) return false;
        this.dartUsed = true;
        this.dartUntil = this.elapsed + 10;
        this.mierSensitive = true;
        this.pushLog('塞缪尔吹出麻醉镖，米埃尔僵在原地。', 'enemy');
        return true;
      }
      case 'pickupWeapon': {
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        this.weapon = { state: 'equipped' };
        this.pushLog('你捡回了短刀。', 'player');
        break;
      }
      case 'wait': {
        const gain = config.staminaGain ?? 0;
        player.stamina = Math.min(player.def.stamina, player.stamina + gain);
        this.pushLog(`你原地调整呼吸，体力 +${gain}。`, 'player');
        break;
      }
      case 'flee': {
        if (this.elapsed < this.dartUntil && !this.playerLocked) {
          this.pushLog('你趁米埃尔僵在原地，退到十格外。', 'player');
          this.finish('stunnedFlee');
        } else {
          this.finish('flee');
        }
        return true;
      }
    }
    this.enemyReaction(action);
    if (this.isFinished()) return true;

    player.gauge = 0;
    this.phase = 'running';
    this.resolveOutcome();
    return true;
  }

  get snapshot(): BattleSnapshot {
    const threshold = this.definition.actionValue?.threshold ?? 100;
    return {
      id: this.definition.id,
      phase: this.phase,
      distance: this.distance,
      distanceConfig: this.definition.distance,
      actors: this.actorsState.map((actor) => ({
        id: actor.def.id,
        name: actor.def.name,
        team: actor.def.team,
        stamina: Math.round(actor.stamina * 10) / 10,
        maxStamina: actor.def.stamina,
        gauge: Math.round((actor.gauge / threshold) * 100),
        gaugeThreshold: threshold,
        portrait: actor.def.portrait,
      })),
      weapon: {
        ...this.weapon,
        delta: this.weapon.state === 'ground' ? (this.weapon.cell ?? 0) - this.playerStep : undefined,
      },
      blowgun: this.options.hasBlowgun
        ? {
            state: this.blowgun.state,
            cell: this.blowgun.cell,
            delta: this.blowgun.state === 'ground' ? (this.blowgun.cell ?? 0) - this.playerStep : undefined,
          }
        : undefined,
      status: [
        ...(this.mierSensitive ? ['敏感'] : []),
        ...(this.elapsed < this.dartUntil ? [`麻醉 ${Math.ceil(this.dartUntil - this.elapsed)}s`, '无法行动'] : []),
      ],
      pinned: this.pinUsed,
      intent: this.intent(),
      actions: this.actionsView(),
      log: this.logEntries.slice(-40),
      result: this.result,
      elapsedSeconds: Math.round(this.elapsed * 10) / 10,
    };
  }

  // ---------- 内部 ----------

  private player(): ActorState {
    const player = this.actorsState.find((actor) => actor.def.team === 'player');
    if (!player) throw new Error('战斗定义缺少 player 阵营参战者');
    return player;
  }

  private enemy(): ActorState {
    const enemy = this.actorsState.find((actor) => actor.def.team === 'enemy');
    if (!enemy) throw new Error('战斗定义缺少 enemy 阵营参战者');
    return enemy;
  }

  private playerAttack(config: BattleActionConfig, text: string): void {
    const enemy = this.enemy();
    const dodged = (config.dodge ?? 0) >= 1;
    this.pushLog(`${text}。`, 'player');
    if (dodged) {
      this.pushLog('米埃尔轻轻侧身，石头擦着她的头发飞了过去。', 'enemy');
      // 闪避也要消耗体力：丢石头固定掉 1 点
      if (config.enemyStaminaLoss) {
        enemy.stamina = Math.max(0, enemy.stamina - config.enemyStaminaLoss);
      }
      return;
    }
    enemy.stamina = Math.max(0, enemy.stamina - (config.enemyStaminaLoss ?? 0));
    this.pushLog(`命中，米埃尔体力 -${config.enemyStaminaLoss ?? 0}。`, 'damage');
  }

  /** 玩家做出触发动作时，蓄势待发的米埃尔立刻回应。 */
  private enemyReaction(action: BattleActionId): void {
    if (this.mode === 'challenge') return;
    const enemy = this.enemy();
    const player = this.player();
    const threshold = this.definition.actionValue?.threshold ?? 100;
    if (enemy.gauge < threshold - 1e-6) return;

    if (action === 'pickupWeapon' && this.weapon.state === 'equipped') {
      this.disarm(enemy);
      enemy.gauge = 0;
      return;
    }
    if (action === 'throwStone') {
      this.bodyThrow(enemy);
      enemy.gauge = 0;
      return;
    }
    if (action === 'moveCloser' && this.weapon.state === 'ground') {
      const initial = this.definition.distance.initial;

      // 贴脸：抬脚踹开，拉开 1 格并造成伤害
      if (this.distance <= 0) {
        enemy.gauge = Math.max(0, enemy.gauge - this.ai.kickActionCost);
        player.stamina = Math.max(0, player.stamina - this.ai.kickDamage);
        this.distance = Math.min(this.definition.distance.max, this.ai.kickDistance);
        this.pushLog(`她抬脚把你踹开，距离 ${this.distance} 格，体力 -${this.ai.kickDamage}。`, 'damage');
        this.resolveOutcome();
        return;
      }

      // 还没贴脸：花 50 行动值回到初始距离，顺手丢一块石头
      if (this.distance < initial) {
        enemy.gauge = Math.max(0, enemy.gauge - this.ai.retreatActionCost);
        this.distance = Math.min(this.definition.distance.max, initial);
        this.pushLog(`她向后跃开，距离回到 ${this.distance} 格。`, 'enemy');
        this.bodyThrow(enemy);
      }
    }
  }

  private disarm(actor: ActorState): void {
    actor.stamina = Math.max(0, actor.stamina - 1);
    const player = this.player();
    player.stamina = Math.max(0, player.stamina - 10);
    this.weapon = { state: 'ground', cell: this.playerStep };
    this.pushLog('米埃尔踢起一块碎石，砸在你手腕上，体力 -10。短刀脱手。', 'damage');
    this.pushLog('武器掉在你脚下。', 'info');
    this.resolveOutcome();
  }

  private bodyThrow(actor: ActorState): void {
    actor.stamina = Math.max(0, actor.stamina - 1);
    const player = this.player();
    player.stamina = Math.max(0, player.stamina - 10);
    this.pushLog('石头砸中你的身体，体力 -10。', 'damage');
    this.resolveOutcome();
  }

  private intent(): BattleIntent | null {
    if (this.phase === 'finished') return null;
    const enemy = this.enemy();
    const threshold = this.definition.actionValue?.threshold ?? 100;
    if (this.weapon.state === 'equipped' && enemy.gauge >= threshold - 1e-6) return 'disarm';
    if (enemy.gauge >= threshold - 1e-6) return 'hold';
    return 'idle';
  }

  private actionsView(): BattleActionView[] {
    const player = this.player();
    const list: BattleActionView[] = [];
    const build = (id: BattleActionId, available: boolean, reason?: string) => {
      list.push({ id, label: ACTION_LABELS[id], available, reason });
    };

    const enrich = (id: BattleActionId): string => {
      const config = this.actions[id];
      const parts: string[] = [];
      if (config.staminaCost > 0) parts.push(`体力 -${config.staminaCost}`);
      if (config.staminaGain) parts.push(`体力 +${config.staminaGain}`);
      if (id === 'melee') parts.push('距离 ≤1');
      return parts.join(' · ');
    };

    const stunFlee = this.elapsed < this.dartUntil && !this.playerLocked;
    build(
      'flee',
      stunFlee || (this.options.allowFlee !== false && this.distance >= this.definition.distance.fleeAt),
      stunFlee ? '趁麻醉撤离' : `距离 ≥${this.definition.distance.fleeAt}`,
    );

    build(
      'moveCloser',
      this.distance > this.definition.distance.min && player.stamina >= this.actions.moveCloser.staminaCost,
      this.distance <= this.definition.distance.min ? '已经贴脸' : enrich('moveCloser'),
    );
    build(
      'moveAway',
      this.distance < this.definition.distance.max && player.stamina >= this.actions.moveAway.staminaCost,
      this.distance >= this.definition.distance.max ? '已到最远' : enrich('moveAway'),
    );
    build(
      'melee',
      this.weapon.state === 'equipped' &&
        this.distance <= (this.actions.melee.range ?? 1) &&
        player.stamina >= this.actions.melee.staminaCost,
      this.weapon.state !== 'equipped' ? '需要武器' : this.distance > 1 ? '距离太远' : enrich('melee'),
    );
    build('throwStone', player.stamina >= this.actions.throwStone.staminaCost, enrich('throwStone'));
    if (this.options.hasBlowgun) {
      build(
        'blowgun',
        this.blowgun.state === 'equipped' && player.stamina >= this.actions.blowgun.staminaCost,
        `命中率 ${this.options.proficiency}% · 体力 -5`,
      );
      build(
        'pickupBlowgun',
        this.blowgun.state === 'ground' && (this.blowgun.cell ?? 0) === this.playerStep && player.stamina >= 5,
        this.blowgun.state !== 'ground' ? '吹箭筒在手上' : '体力 -5',
      );
    }
    if (this.playerLocked) return [];
    if (this.options.samuelHelp) {
      build('dart', !this.dartUsed, this.dartUsed ? '本场已用' : '塞缪尔 · 冻结 10 秒');
      build('pin', this.distance <= 1 && this.elapsed < this.dartUntil, '需要麻醉并贴近米埃尔');
    }
    build(
      'pickupWeapon',
      this.weapon.state === 'ground' &&
        (this.weapon.cell ?? 0) === this.playerStep &&
        player.stamina >= this.actions.pickupWeapon.staminaCost,
      this.weapon.state !== 'ground'
        ? '武器在手上'
        : (this.weapon.cell ?? 0) > this.playerStep
          ? `武器在你前方 ${(this.weapon.cell ?? 0) - this.playerStep} 格`
          : (this.weapon.cell ?? 0) < this.playerStep
            ? `武器在你身后 ${this.playerStep - (this.weapon.cell ?? 0)} 格`
            : enrich('pickupWeapon'),
    );
    build('wait', true, enrich('wait'));

    return list;
  }

  /** 麻醉期间强制撤离，绕过行动列表校验。 */
  escapeStunned(): boolean {
    if (this.phase === 'finished') return false;
    if (this.elapsed >= this.dartUntil) return false;
    this.pushLog('你趁米埃尔僵在原地，退到十格外。', 'player');
    this.finish('stunnedFlee');
    return true;
  }

  private resolveOutcome(): void {
    if (this.phase === 'finished') return;
    const enemy = this.enemy();
    const player = this.player();
    if (enemy.stamina <= 0) {
      this.finish('win');
      return;
    }
    if (player.stamina <= 0) {
      this.finish('lose');
    }
  }

  private finish(result: BattleResult): void {
    if (this.phase === 'finished') return;
    this.result = result;
    this.phase = 'finished';
    const text =
      result === 'win'
        ? '米埃尔倒在地上。'
        : result === 'lose'
          ? '你再也抬不起手臂，眼前一黑。'
          : result === 'stolen'
            ? this.options.hasBlowgun
              ? '她带着你的短刀和吹箭筒退进荒野。'
              : '她带着你的短刀退进荒野，没有再回头。'
            : '你退到足够远的地方，转身离开。';
    this.pushLog(text, 'info');
  }

  private pushLog(text: string, kind: BattleLogEntry['kind']): void {
    this.logEntries.push({ text, kind });
    if (this.logEntries.length > 120) this.logEntries.shift();
  }
}
