import type { GameState } from './types';
import { getPath } from './paths';

const TOKEN = /\{\{\s*([^{}]+?)\s*\}\}/g;

/**
 * {{path.to.value}} 变量插值。
 * 找不到的键渲染为 [未知:path]，任何情况下都不抛错。
 */
export function interpolate(text: string, state: GameState): string {
  if (typeof text !== 'string' || text === '') return typeof text === 'string' ? text : '';
  return text.replace(TOKEN, (_match, raw: string) => {
    const path = raw.trim();
    if (path === '') return '[未知:]';
    const value = getPath(state, path);
    if (value === undefined) return `[未知:${path}]`;
    if (value === null) return 'null';
    if (typeof value === 'object') return JSON.stringify(value);
    return String(value);
  });
}

/** 提取文本里引用到的所有路径，供校验器提示"内容包引用了不存在的变量"。 */
export function collectTokens(text: string): string[] {
  const out: string[] = [];
  if (typeof text !== 'string') return out;
  for (const match of text.matchAll(TOKEN)) out.push(match[1].trim());
  return out;
}
