import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { invoke } from '@tauri-apps/api/core';
import { App } from './ui/App';
import { createRuntime } from './storage/platform';
import './styles.css';

const container = document.getElementById('root');
if (!container) throw new Error('缺少 #root 节点');

const root = createRoot(container);

function logToFile(message: string): void {
  if (typeof window === 'undefined' || !('__TAURI_INTERNALS__' in window)) return;
  void invoke('cradle_log', { message }).catch(() => undefined);
}

window.addEventListener('error', (event) => {
  logToFile(`window error: ${event.message} @ ${event.filename}:${event.lineno}`);
});
window.addEventListener('unhandledrejection', (event) => {
  logToFile(`unhandled rejection: ${String(event.reason)}`);
});
logToFile('frontend boot');

const isTauri = typeof window !== 'undefined' && '__TAURI_INTERNALS__' in window;

if (isTauri && 'serviceWorker' in navigator) {
  void navigator.serviceWorker.getRegistrations().then((items) => items.forEach((item) => void item.unregister()));
  if ('caches' in window) {
    void caches.keys().then((keys) => keys.forEach((key) => void caches.delete(key)));
  }
}

if (!isTauri && import.meta.env.PROD && 'serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    void navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`).catch(() => undefined);
  });
}

createRuntime()
  .then((runtime) => {
    root.render(
      <StrictMode>
        <App runtime={runtime} />
      </StrictMode>,
    );
    logToFile(`frontend mounted (${runtime.platform})`);
  })
  .catch((error: unknown) => {
    const message = error instanceof Error ? error.message : String(error);
    logToFile(`runtime init failed: ${message}`);
    root.render(
      <div className="fatal">
        <h1>Cradle 启动失败</h1>
        <p>{message}</p>
        <p>日志：%LOCALAPPDATA%\dev.cradle.framework\crash.log</p>
        <button type="button" className="btn btn-primary" onClick={() => window.location.reload()}>
          重新加载
        </button>
      </div>,
    );
  });
