import type {
  AssetMapping,
  Choice,
  Condition,
  Effects,
  GameState,
  ImageRef,
  JsonValue,
  Layout,
  StoryNode,
  VisualSlot,
} from '../types';
import { isJsonObject } from '../util';

export interface DslOptions {
  state: GameState;
  assets?: Record<string, AssetMapping>;
}

export interface DslParseResult {
  nodes: StoryNode[];
  problems: string[];
}

interface DraftNode {
  id: string;
  line: number;
  textLines: string[];
  images: ImageRef[];
  choices: Choice[];
  effects: Effects;
  layout?: Layout;
  problems: string[];
}

const TAG_SLOT: Record<string, VisualSlot> = {
  背景: 'bg',
  bg: 'bg',
  立绘: 'npcPortraits',
  角色: 'npcPortraits',
  npc: 'npcPortraits',
  道具: 'npcPortraits',
  item: 'npcPortraits',
  地图: 'map',
  map: 'map',
  主控: 'playerPortrait',
  主角: 'playerPortrait',
  player: 'playerPortrait',
};

const OP_SET = new Set(['==', '!=', '>', '>=', '<', '<=']);

/**
 * 极简剧本 DSL → story.json 节点数组。
 *
 * ```
 * # node_id [背景: 荒野·白日]
 * 正文，支持 {{path}} 插值。
 * [立绘: 米埃尔·平静] [道具: 石头]
 * (flags.metMier = true)
 * * 选项文本 -> target [if player.fear <= 60] (flags.x = 1)
 * ```
 */
export function parseDsl(script: string, options: DslOptions): DslParseResult {
  const problems: string[] = [];
  const lines = script.replace(/\r\n?/g, '\n').split('\n');
  const nodes: StoryNode[] = [];
  let current: DraftNode | null = null;
  let lastLineWasBlank = false;

  const finish = () => {
    if (!current) return;
    const text = current.textLines
      .join('\n')
      .replace(/^\n+/, '')
      .replace(/\n+$/, '')
      .replace(/\n{3,}/g, '\n\n');
    const layout = current.layout ?? (current.images.some((image) => image.slot === 'bg') ? 'background' : 'stacked');
    const node: StoryNode = { id: current.id, layout, text };
    if (current.images.length > 0) node.images = current.images;
    if (current.choices.length > 0) node.choices = current.choices;
    if (Object.keys(current.effects).length > 0) node.effects = current.effects;
    nodes.push(node);
    problems.push(...current.problems);
    current = null;
  };

  lines.forEach((rawLine, index) => {
    const lineNo = index + 1;
    const line = rawLine.trim();

    if (line.startsWith('//') || line === '') {
      if (current) {
        if (line === '' && !lastLineWasBlank) current.textLines.push('');
        lastLineWasBlank = line === '';
      }
      return;
    }
    lastLineWasBlank = false;

    const heading = /^#\s+(.+)$/.exec(line);
    if (heading) {
      finish();
      const { id, tags } = splitHeading(heading[1]);
      current = {
        id,
        line: lineNo,
        textLines: [],
        images: [],
        choices: [],
        effects: {},
        problems: [],
      };
      applyTags(current, tags, lineNo, options, problems);
      return;
    }

    if (!current) {
      problems.push(`第 ${lineNo} 行：节点之外的文本（缺少 # 标题）`);
      return;
    }

    if (/^(?:\s*\[[^\]]+\])+\s*$/.test(line)) {
      applyTags(current, line, lineNo, options, problems);
      return;
    }

    const effectLine = /^\((.+)\)$/.exec(line);
    if (effectLine) {
      current.effects = mergeEffects(current.effects, parseEffects(effectLine[1], lineNo, options.state, problems));
      return;
    }

    const choiceMatch = /^[*\-]\s+(.+)$/.exec(line);
    if (choiceMatch) {
      const choice = parseChoice(choiceMatch[1], lineNo, options.state, problems);
      if (choice) current.choices.push(choice);
      return;
    }

    current.textLines.push(rawLine.replace(/\s+$/, ''));
  });

  finish();

  const ids = new Set<string>();
  for (const node of nodes) {
    if (ids.has(node.id)) problems.push(`节点 id 重复：${node.id}`);
    ids.add(node.id);
  }
  for (const node of nodes) {
    for (const choice of node.choices ?? []) {
      if (!ids.has(choice.targetId)) problems.push(`节点 "${node.id}" 的选项指向不存在的节点 "${choice.targetId}"`);
    }
  }

  return { nodes, problems };
}

function splitHeading(value: string): { id: string; tags: string } {
  const tagIndex = value.indexOf('[');
  if (tagIndex === -1) return { id: value.trim(), tags: '' };
  return { id: value.slice(0, tagIndex).trim(), tags: value.slice(tagIndex) };
}

function applyTags(
  node: DraftNode,
  text: string,
  lineNo: number,
  options: DslOptions,
  problems: string[],
): void {
  const tagPattern = /\[([^\]:：]+)\s*[:：]\s*([^\]]+)\]/g;
  let match: RegExpExecArray | null;
  while ((match = tagPattern.exec(text)) !== null) {
    const key = match[1].trim();
    const value = match[2].trim();
    if (key === '布局' || key.toLowerCase() === 'layout') {
      if (value === 'background' || value === '背景') node.layout = 'background';
      else if (value === 'stacked' || value === '对话') node.layout = 'stacked';
      else problems.push(`第 ${lineNo} 行：未知布局 "${value}"`);
      continue;
    }
    const slot = TAG_SLOT[key];
    if (!slot) {
      problems.push(`第 ${lineNo} 行：未知标签 "${key}"（支持 背景/立绘/道具/地图/主控/布局）`);
      continue;
    }
    const mapping = options.assets?.[value];
    if (mapping) {
      node.images.push({
        slot,
        placeholder: mapping.placeholder,
        alt: mapping.alt ?? value,
      });
      continue;
    }
    if (/^[A-Za-z0-9_-]+$/.test(value)) {
      node.images.push({ slot, placeholder: value, alt: value });
      continue;
    }
    node.images.push({ slot, placeholder: value, alt: value });
    problems.push(
      `第 ${lineNo} 行：资源 "${value}" 没有映射到逻辑名，已原样使用（可在 assets.json 里配置，或直接写逻辑名）`,
    );
  }
}

function parseChoice(
  body: string,
  lineNo: number,
  state: GameState,
  problems: string[],
): Choice | null {
  const arrow = /^(.*?)\s*->\s*(\S+)\s*([\s\S]*)$/.exec(body);
  if (!arrow) {
    problems.push(`第 ${lineNo} 行：选项缺少 "-> 目标节点"`);
    return null;
  }
  let text = arrow[1].trim();
  const targetId = arrow[2].trim();
  let rest = arrow[3].trim();

  let condition: Condition | undefined;
  const ifMatch = /\[if\s+([^\]]+)\]/i.exec(rest);
  if (ifMatch) {
    condition = parseCondition(ifMatch[1], lineNo, state, problems);
    rest = rest.replace(ifMatch[0], '').trim();
  }

  let effects: Effects | undefined;
  const effectMatch = /\(([^()]*)\)\s*$/.exec(rest);
  if (effectMatch) {
    const parsed = parseEffects(effectMatch[1], lineNo, state, problems);
    if (Object.keys(parsed).length > 0) effects = parsed;
    rest = rest.replace(effectMatch[0], '').trim();
  }

  if (rest !== '') text += ` ${rest}`;
  if (text === '') {
    problems.push(`第 ${lineNo} 行：选项文本为空`);
    return null;
  }

  const choice: Choice = { text, targetId };
  if (condition) choice.condition = condition;
  if (effects) choice.effects = effects;
  return choice;
}

function parseEffects(clause: string, lineNo: number, state: GameState, problems: string[]): Effects {
  const effects: Effects = {};
  for (const piece of splitTopLevel(clause)) {
    const item = piece.trim();
    if (item === '') continue;

    const push = /^(push|remove)\s*:\s*([^\s=]+)\s*=\s*(.+)$/i.exec(item);
    if (push) {
      const path = resolvePath(push[2], state, lineNo, problems);
      const value = parseValue(push[3]);
      const key = push[1].toLowerCase() === 'push' ? 'push' : 'remove';
      effects[key] = { ...(effects[key] ?? {}), [path]: value };
      continue;
    }

    const inc = /^([A-Za-z0-9_.\u4e00-\u9fa5]+)\s*([+-])\s*(.+)$/.exec(item);
    if (inc) {
      const path = resolvePath(inc[1], state, lineNo, problems);
      const amount = Number(parseValue(inc[3]));
      if (Number.isNaN(amount)) {
        problems.push(`第 ${lineNo} 行：无法解析数值 "${inc[3]}"`);
        continue;
      }
      const key = inc[2] === '+' ? 'inc' : 'dec';
      effects[key] = { ...(effects[key] ?? {}), [path]: amount };
      continue;
    }

    const set = /^([A-Za-z0-9_.\u4e00-\u9fa5]+)\s*=\s*(.+)$/.exec(item);
    if (set) {
      const path = resolvePath(set[1], state, lineNo, problems);
      effects.set = { ...(effects.set ?? {}), [path]: parseValue(set[2]) };
      continue;
    }

    problems.push(`第 ${lineNo} 行：无法解析 effect "${item}"`);
  }
  return effects;
}

function resolvePath(raw: string, state: GameState, lineNo: number, problems: string[]): string {
  if (raw.includes('.')) return raw;
  const groups = Object.entries(state).filter(
    ([, value]) => isJsonObject(value) && Object.prototype.hasOwnProperty.call(value, raw),
  );
  if (groups.length === 1) return `${groups[0][0]}.${raw}`;
  if (groups.length > 1) {
    problems.push(
      `第 ${lineNo} 行：字段 "${raw}" 同时出现在 ${groups.map(([key]) => key).join(' / ')}，请写全路径`,
    );
    return raw;
  }
  problems.push(`第 ${lineNo} 行：字段 "${raw}" 不在 state.json 中，已按原样使用`);
  return raw;
}

function splitTopLevel(text: string): string[] {
  const parts: string[] = [];
  let current = '';
  let quote: string | null = null;
  for (const char of text) {
    if (quote) {
      current += char;
      if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
      current += char;
      continue;
    }
    if (char === ',') {
      parts.push(current);
      current = '';
      continue;
    }
    current += char;
  }
  parts.push(current);
  return parts;
}

function parseValue(raw: string): JsonValue {
  const value = raw.trim();
  if (/^-?\d+(\.\d+)?$/.test(value)) return Number(value);
  if (value === 'true') return true;
  if (value === 'false') return false;
  if (value === 'null') return null;
  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    return value.slice(1, -1);
  }
  return value;
}

function mergeEffects(base: Effects, extra: Effects): Effects {
  const merged: Effects = { ...base };
  if (extra.set) merged.set = { ...(merged.set ?? {}), ...extra.set };
  if (extra.inc) merged.inc = { ...(merged.inc ?? {}), ...extra.inc };
  if (extra.dec) merged.dec = { ...(merged.dec ?? {}), ...extra.dec };
  if (extra.push) merged.push = { ...(merged.push ?? {}), ...extra.push };
  if (extra.remove) merged.remove = { ...(merged.remove ?? {}), ...extra.remove };
  if (extra.limit) merged.limit = { ...(merged.limit ?? {}), ...extra.limit };
  return merged;
}

// ---------- 条件表达式 ----------

type Token = { type: 'path' | 'op' | 'value' | 'paren' | 'keyword'; value: string };

function tokenize(expression: string): Token[] {
  const pattern =
    /(>=|<=|==|!=|>|<|\(|\)|\bnot\b|\band\b|\bor\b|"[^"]*"|'[^']*'|[A-Za-z0-9_.\u4e00-\u9fa5-]+)/gi;
  const tokens: Token[] = [];
  let match: RegExpExecArray | null;
  while ((match = pattern.exec(expression)) !== null) {
    const raw = match[0];
    const lower = raw.toLowerCase();
    if (lower === 'and' || lower === 'or' || lower === 'not') tokens.push({ type: 'keyword', value: lower });
    else if (raw === '(' || raw === ')') tokens.push({ type: 'paren', value: raw });
    else if (OP_SET.has(raw)) tokens.push({ type: 'op', value: raw });
    else if (/^["']/.test(raw)) tokens.push({ type: 'value', value: raw.slice(1, -1) });
    else if (/^-?\d+(\.\d+)?$/.test(raw)) tokens.push({ type: 'value', value: raw });
    else if (raw === 'true' || raw === 'false' || raw === 'null') tokens.push({ type: 'value', value: raw });
    else tokens.push({ type: 'path', value: raw });
  }
  return tokens;
}

function parseCondition(expression: string, lineNo: number, state: GameState, problems: string[]): Condition | undefined {
  const tokens = tokenize(expression);
  let index = 0;

  const peek = () => tokens[index];
  const next = () => tokens[index++];

  const parseOr = (): Condition | null => {
    let left = parseAnd();
    while (peek()?.type === 'keyword' && peek().value === 'or') {
      next();
      const right = parseAnd();
      if (!left || !right) return null;
      left = { any: [left, right] };
    }
    return left;
  };

  const parseAnd = (): Condition | null => {
    let left = parseNot();
    while (peek()?.type === 'keyword' && peek().value === 'and') {
      next();
      const right = parseNot();
      if (!left || !right) return null;
      left = { all: [left, right] };
    }
    return left;
  };

  const parseNot = (): Condition | null => {
    if (peek()?.type === 'keyword' && peek().value === 'not') {
      next();
      const inner = parseNot();
      return inner ? { not: inner } : null;
    }
    return parsePrimary();
  };

  const parsePrimary = (): Condition | null => {
    const token = next();
    if (!token) return null;
    if (token.type === 'paren' && token.value === '(') {
      const inner = parseOr();
      if (peek()?.type === 'paren' && peek().value === ')') next();
      return inner;
    }
    if (token.type !== 'path') {
      problems.push(`第 ${lineNo} 行：条件里出现意外的 "${token.value}"`);
      return null;
    }
    const path = resolvePath(token.value, state, lineNo, problems);
    const op = peek();
    if (op?.type === 'op') {
      next();
      const valueToken = next();
      if (!valueToken) {
        problems.push(`第 ${lineNo} 行：条件缺少比较值`);
        return null;
      }
      return {
        stat: path,
        op: op.value as '==' | '!=' | '>' | '>=' | '<' | '<=',
        value: parseValue(valueToken.value),
      };
    }
    return { flag: path, eq: true };
  };

  const condition = parseOr();
  if (!condition) {
    problems.push(`第 ${lineNo} 行：条件解析失败：${expression}`);
    return undefined;
  }
  return condition;
}
