/** 内容包与运行时共享的数据契约。所有字段都必须可 JSON 序列化。 */

export type JsonPrimitive = string | number | boolean | null;
export type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };
export type GameState = { [key: string]: JsonValue };

/** 四标准视觉槽位 */
export type VisualSlot = 'bg' | 'playerPortrait' | 'npcPortraits' | 'map';

import type { BattleDefinition } from './battle/types';

/**
 * 节点无法显示的原因，用于区分「作者没写」与「内容包/存档/数据出问题」。
 * - unwritten：选项 targetId 在 story.json 中不存在
 * - entry-missing：manifest.entry 指向不存在的节点
 * - save-node-missing：读档时存档节点在当前内容包中不存在
 * - invalid-node：节点存在但结构不完整
 */
export type MissingReason = 'unwritten' | 'entry-missing' | 'save-node-missing' | 'invalid-node';

export interface ImageRef {
  /** 缺省时按 placeholder 前缀推断（bg_ / map_ / player_ / pc_ / char_） */
  slot?: VisualSlot;
  /** 逻辑名，不允许写路径 */
  placeholder: string;
  alt?: string;
  /** 仅 playerPortrait：从 state 读取图片逻辑名的路径，如 "player.portrait" */
  bindState?: string;
}

export interface Effects {
  set?: Record<string, JsonValue>;
  inc?: Record<string, number>;
  dec?: Record<string, number>;
  push?: Record<string, JsonValue>;
  remove?: Record<string, JsonValue>;
  /** 在 inc/dec 之后把数值上限压到指定值 */
  limit?: Record<string, number>;
}

export type ComparisonOp = '==' | '!=' | '>' | '>=' | '<' | '<=' | 'in' | 'not_in';

/**
 * 结构化条件，禁止字符串表达式求值。
 * 支持 all / any / not 嵌套，以及 stat / flag / path + op/value 或 eq/neq 简写。
 */
export type Condition =
  | { all: Condition[] }
  | { any: Condition[] }
  | { not: Condition }
  | { stat: string; op: ComparisonOp; value: JsonValue }
  | { flag: string; op: ComparisonOp; value: JsonValue }
  | { stat: string; eq: JsonValue }
  | { stat: string; neq: JsonValue }
  | { flag: string; eq: JsonValue }
  | { flag: string; neq: JsonValue };

export interface Choice {
  text: string;
  targetId: string;
  condition?: Condition;
  effects?: Effects;
  /** true：条件不满足时置灰显示；false/缺省：直接隐藏 */
  hideIfLocked?: boolean;
  /** 条件满足但满足 disabledIf 时置灰（仍显示） */
  disabledIf?: Condition;
  /** 选择后回滚到本场战斗开始前的 state */
  rewindBattle?: boolean;
  /** 回滚后仍保留的状态路径（如记忆类 flag） */
  rewindKeep?: string[];
}

export type Layout = 'background' | 'stacked';

export interface StoryNode {
  id: string;
  text: string;
  images?: ImageRef[];
  layout?: Layout;
  choices?: Choice[];
  effects?: Effects;
  /** 按条件替换正文（第一个满足的生效），用于阶段变化后的界面文案 */
  textVariants?: { condition?: Condition; text: string }[];
  /** 引用 battles.json 里的战斗 id；进入该节点时先打一场 */
  battle?: string;
  /** 进入后按权重随机跳转（用于拐人遇袭等随机事件） */
  randomNext?: { targetId: string; weight: number }[];
  /** 进入该节点后直接结束本局，回到标题 */
  endGame?: boolean;
}

export interface Manifest {
  id: string;
  name: string;
  version: string;
  engineVersion: string;
  entry: string;
}

export interface ContentPack {
  manifest: Manifest;
  nodes: StoryNode[];
  initialState: GameState;
  battles?: Record<string, BattleDefinition>;
  /** 简易剧本 DSL 里「显示名 → 逻辑名」的映射表（可选） */
  assets?: Record<string, AssetMapping>;
}

export interface AssetMapping {
  placeholder: string;
  slot?: VisualSlot;
  alt?: string;
}

export interface SaveData {
  saveVersion: number;
  engineVersion: string;
  packId: string;
  packVersion: string;
  slot: string;
  timestamp: number;
  currentNodeId: string;
  state: GameState;
  history: string[];
}

export interface PackSummary {
  id: string;
  name: string;
  version: string;
  engineVersion: string;
  entry: string;
  nodeCount: number;
  importedAt: number;
}

/** 存档槽位命名 */
export const AUTO_SLOT = 'auto_1';
export const MANUAL_SLOT_COUNT = 5;
export function manualSlot(n: number): string {
  return `manual_${n}`;
}
export function isAutoSlot(slot: string): boolean {
  return slot.startsWith('auto_');
}
