import { useEffect, useRef, useState } from 'react';
import type { BattleActionId, BattleDefinition, BattleResult } from '../engine/battle/types';
import { TeamBattleSimulator, type TeamBattleSnapshot } from '../engine/battle/teamSimulator';
import type { AssetResolver } from '../assets/AssetResolver';
import { StaminaBar, GaugeBar } from './BattleScreen';

const RESULT_TITLE: Record<string, string> = {
  win: '战斗胜利',
  lose: '你倒下了',
  flee: '脱离战斗',
  stolen: '武器被夺走',
  confiscated: '全员倒下',
  fled_armed: '带刀撤退',
  fled_unarmed: '空手撤退',
  escaped: '她逃走了',
};

const RESULT_TEXT: Record<string, string> = {
  win: '米埃尔倒在地上。',
  lose: '你再也抬不起手臂。',
  flee: '你退到足够远的地方。',
  stolen: '她带着你的短刀退进荒野。',
  confiscated: '所有人倒在地上。米埃尔把散落的武器一一收走，转身离开。',
  fled_armed: '你转身就跑。她追上来夺走你的刀，才放你走。',
  fled_unarmed: '你空着手撤退。她看了你一眼，没有追。',
  escaped: '她退到十格外，转身消失在荒野里。',
};

export interface TeamBattleScreenProps {
  definition: BattleDefinition;
  resolver: AssetResolver;
  allyCount: number;
  playerHasWeapon: boolean;
  hasBlowgun?: boolean;
  proficiency?: number;
  samuelHelp?: boolean;
  forceBlowgun?: boolean;
  onFinish(result: BattleResult): void;
}

export function TeamBattleScreen({
  definition,
  resolver,
  allyCount,
  playerHasWeapon,
  hasBlowgun,
  proficiency,
  samuelHelp,
  forceBlowgun,
  onFinish,
}: TeamBattleScreenProps) {
  const simulatorRef = useRef<TeamBattleSimulator | null>(null);
  if (simulatorRef.current === null) {
    simulatorRef.current = new TeamBattleSimulator(definition, {
      allyCount,
      playerHasWeapon,
      hasBlowgun: hasBlowgun || forceBlowgun,
      proficiency,
      samuelHelp,
    });
  }
  const simulator = simulatorRef.current;

  const [snap, setSnap] = useState<TeamBattleSnapshot>(() => simulator.getSnapshot());

  useEffect(() => {
    const timer = window.setInterval(() => {
      simulator.tick(100);
      setSnap(simulator.getSnapshot());
    }, 100);
    return () => window.clearInterval(timer);
  }, [simulator]);

  const players = snap.actors.filter((actor) => actor.team === 'player');
  const player = players.find((actor) => actor.id === 'thief');
  const allies = players.filter((actor) => actor.id !== 'thief');
  const mier = snap.actors.find((actor) => actor.team === 'enemy');
  const nearest = players.filter((actor) => !actor.down).reduce((min, actor) => Math.min(min, actor.distance ?? 0), 99);

  const resolve = (name?: string) => (name ? resolver.resolve(name, 'portrait') : null);
  const playerPortrait = resolve(player?.portrait ?? 'player_neutral');
  const enemyPortrait = resolve(mier?.portrait ?? 'char_mier_neutral');
  const background = definition.background ? resolver.resolve(definition.background, 'bg') : null;
  const distance = player?.distance ?? 0;
  const max = snap.distanceConfig.max;
  const canPin = snap.mierStatus.includes('被扣住') && snap.mierStatus.some((status) => status.startsWith('麻醉'));

  const act = (action: BattleActionId) => {
    simulator.act(action);
    setSnap(simulator.getSnapshot());
  };

  return (
    <div className="battle" data-testid="team-battle">
      {background && <img className="battle-bg" src={background.url} alt="" aria-hidden="true" />}

      <header className="battle-hud">
        <span className="battle-title">组队挑战</span>
        <span className="battle-distance-label">
          距离 <strong>{distance}</strong> 格
        </span>
        <span className="battle-weapon">
          武器：
          {player?.weapon === 'equipped' ? '手上' : player?.weapon === 'stolen' ? '空手' : '掉落'}
        </span>
      </header>

      <div className="battle-stage">
        <div className="team-allies" data-testid="team-roster">
          {allies.map((actor) => (
            <div key={actor.id} className={`team-ally ${actor.down ? 'is-down' : ''}`} data-testid={`team-actor-${actor.id}`}>
              <span>{actor.name}</span>
              <span>{actor.distance} 格</span>
              <span>{actor.stamina}/{actor.maxStamina}</span>
            </div>
          ))}
        </div>

        <div className="battle-side battle-side-player">
          <div className="battle-portrait battle-portrait-player">
            {playerPortrait ? <img src={playerPortrait.url} alt={player?.name ?? ''} /> : <div className="battle-portrait-empty" />}
          </div>
          <div className="battle-actor-info">
            <strong>{player?.name ?? '你'}</strong>
            <StaminaBar value={player?.stamina ?? 0} max={player?.maxStamina ?? 100} tone="player" />
            <GaugeBar value={player?.gauge ?? 0} tone="player" />
          </div>
        </div>

        <div className="battle-side battle-side-enemy">
          <div className="battle-portrait battle-portrait-enemy">
            {enemyPortrait ? <img src={enemyPortrait.url} alt={mier?.name ?? ''} /> : <div className="battle-portrait-empty" />}
          </div>
          <div className="mier-status-list">
            {snap.mierStatus.map((status) => (
              <span key={status} className="mier-status" data-testid="team-status" title="行动值消耗变为100%，并每秒恢复10体力">
                {status}
              </span>
            ))}
          </div>
          <div className="battle-actor-info">
            <strong>{mier?.name ?? '米埃尔'}</strong>
            <StaminaBar value={mier?.stamina ?? 0} max={mier?.maxStamina ?? 100} tone="enemy" />
            <GaugeBar value={mier?.gauge ?? 0} tone="enemy" />
          </div>
        </div>
      </div>

      <div className="battle-distance-track" aria-hidden="true">
        {Array.from({ length: max + 1 }, (_, index) => (
          <span
            key={index}
            className={['battle-cell', index === distance ? 'is-enemy' : '', index === 0 ? 'is-player' : ''].filter(Boolean).join(' ')}
          />
        ))}
      </div>

      <div className="battle-intent">最近目标：{nearest} 格</div>

      <div className="battle-log" aria-live="polite">
        {snap.log.slice(-3).map((entry, index) => (
          <p key={`${index}-${entry.text}`} className={`battle-log-${entry.kind}`}>
            {entry.text}
          </p>
        ))}
      </div>

      <div className="battle-actions" data-testid="team-actions">
        {canPin && (
          <button type="button" className="battle-action battle-action-wide" onClick={() => act('pin')} data-testid="team-pin">
            <span>扣住米埃尔</span>
            <small>锁住她，直到麻醉结束</small>
          </button>
        )}
        {snap.actions.filter((action) => !(canPin && action.id === 'pin')).map((action) => (
          <button
            key={action.id}
            type="button"
            className="battle-action"
            disabled={!action.available || snap.phase !== 'playerTurn'}
            onClick={() => act(action.id)}
            data-testid={`team-action-${action.id}`}
            title={action.reason}
          >
            <span>{action.label}</span>
            {action.reason && <small>{action.reason}</small>}
          </button>
        ))}
      </div>

      {snap.phase === 'finished' && snap.result && (
        <>
          <div className="battle-result" role="dialog" aria-modal="true" aria-label="战斗结束" data-testid="team-result">
            <div className="battle-result-card">
              <h2>{RESULT_TITLE[snap.result] ?? '战斗结束'}</h2>
              <p>{RESULT_TEXT[snap.result] ?? ''}</p>
              <button type="button" className="btn btn-primary" onClick={() => onFinish(snap.result!)} data-testid="team-continue">
                继续
              </button>
            </div>
          </div>
          <aside className="battle-report-panel" data-testid="team-report">
            <strong>战报</strong>
            {snap.log.map((entry, index) => (
              <p key={index} className={`battle-log-${entry.kind}`}>
                {entry.text}
              </p>
            ))}
          </aside>
        </>
      )}
    </div>
  );
}
