import { invoke } from '@tauri-apps/api/core';
import type { AssetResolver } from '../assets/AssetResolver';
import { WebAssetResolver } from '../assets/AssetResolver';
import { TauriAssetResolver } from '../assets/TauriAssetResolver';
import type { PackStore, StoredPack } from './PackStore';
import { WebIndexedDBPackStore } from './PackStore';
import type { StorageAdapter } from './StorageAdapter';
import { WebIndexedDBStorage } from './WebIndexedDBStorage';
import { TauriFsStorage } from './TauriFsStorage';
import { TauriPackStore } from './TauriPackStore';
import { tauriSaveExporter, webSaveExporter, type SaveExporter } from './exportSave';

export interface Runtime {
  platform: 'web' | 'tauri';
  storage: StorageAdapter;
  packStore: PackStore;
  exporter: SaveExporter;
  storageLabel: string;
  storageRoot: string;
  createResolver(pack: StoredPack): AssetResolver;
}

export function isTauri(): boolean {
  return typeof window !== 'undefined' && '__TAURI_INTERNALS__' in window;
}

/** 启动时按平台装配；Web 与原生各一套实现，引擎/UI 只依赖接口。 */
export async function createRuntime(): Promise<Runtime> {
  if (isTauri()) {
    // 便携模式由 Rust 侧决定（exe 同目录存在 portable.txt 或设置了 CRADLE_PORTABLE）；
    // 构建期 VITE_CRADLE_DATA_DIR 作为兜底，正常构建两者都没有，走系统 AppData。
    let override = (import.meta.env.VITE_CRADLE_DATA_DIR as string | undefined)?.trim();
    try {
      const runtimeDir = await invoke<string | null>('cradle_data_dir');
      if (typeof runtimeDir === 'string' && runtimeDir.trim() !== '') override = runtimeDir.trim();
    } catch {
      // 非 Tauri 或命令不可用：忽略
    }
    const storage = new TauriFsStorage(override || undefined);
    await storage.init();
    const packStore = new TauriPackStore(override || undefined);
    await packStore.init();
    return {
      platform: 'tauri',
      storage,
      packStore,
      exporter: tauriSaveExporter,
      storageLabel: 'Tauri 文件系统',
      storageRoot: storage.rootPath,
      createResolver: (pack: StoredPack) => new TauriAssetResolver(pack.imagePaths ?? {}),
    };
  }

  const storage = new WebIndexedDBStorage();
  await storage.init();
  const packStore = new WebIndexedDBPackStore();
  await packStore.init();
  return {
    platform: 'web',
    storage,
    packStore,
    exporter: webSaveExporter,
    storageLabel: 'IndexedDB',
    storageRoot: '浏览器 IndexedDB（内容包与存档）',
    createResolver: (pack: StoredPack) => new WebAssetResolver(pack.images),
  };
}
