import { save as saveDialog } from '@tauri-apps/plugin-dialog';
import { writeTextFile } from '@tauri-apps/plugin-fs';
import type { SaveData } from '../engine/types';

export interface SaveExporter {
  exportSave(save: SaveData, filename: string): Promise<void>;
}

/** Web：Blob + a[download] */
export const webSaveExporter: SaveExporter = {
  async exportSave(save, filename) {
    const blob = new Blob([JSON.stringify(save, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 2000);
  },
};

/** Tauri：系统保存对话框 + 直接写盘，文件管理器可见 */
export const tauriSaveExporter: SaveExporter = {
  async exportSave(save, filename) {
    const target = await saveDialog({
      defaultPath: filename,
      filters: [{ name: 'JSON', extensions: ['json'] }],
    });
    if (!target) return;
    await writeTextFile(target, JSON.stringify(save, null, 2));
  },
};
