import type { ImageRef, VisualSlot } from '../engine/types';
import { colorBlockDataUrl, resolveBuiltin, type ColorBlockHint } from './fallback';

export type AssetTier = 1 | 2 | 3;

export interface ResolvedAsset {
  url: string;
  tier: AssetTier;
  logicalName: string;
  alt?: string;
}

export type AssetHint = ColorBlockHint;

/**
 * 资源解析器统一接口：
 *   1) 内容包 images/ 内的同名图
 *   2) 框架内置 assets/placeholders/ 下的同名占位图
 *   3) 运行时生成的纯色块（带逻辑名文字）
 * 永不抛错、永不返回空，UI 层不得自行拼路径。
 */
export interface AssetResolver {
  resolve(logicalName: string, hint?: AssetHint): ResolvedAsset;
  dispose(): void;
}

export type AssetHintFromSlot = (slot: VisualSlot) => AssetHint;

export function hintForSlot(slot: VisualSlot): AssetHint {
  if (slot === 'bg') return 'bg';
  if (slot === 'map') return 'map';
  return 'portrait';
}

/** 按逻辑名前缀推断槽位，兼容未写 slot 的旧内容包。 */
export function inferSlot(ref: ImageRef): VisualSlot {
  if (ref.slot) return ref.slot;
  const name = ref.placeholder;
  if (name.startsWith('bg_')) return 'bg';
  if (name.startsWith('map_')) return 'map';
  if (name.startsWith('player_') || name.startsWith('pc_')) return 'playerPortrait';
  return 'npcPortraits';
}

export interface PackImage {
  bytes: Uint8Array;
  mime: string;
}

/** Web 端实现：包内 Blob URL → 内置 SVG → 生成色块。 */
export class WebAssetResolver implements AssetResolver {
  private readonly images: Record<string, PackImage>;
  private readonly urls = new Map<string, string>();
  private disposed = false;

  constructor(images: Record<string, PackImage>) {
    this.images = images;
  }

  resolve(logicalName: string, hint: AssetHint = 'portrait'): ResolvedAsset {
    const name = logicalName.trim();
    if (name === '') return this.resolve('__empty__', hint);

    const packImage = this.images[name];
    if (packImage) {
      let url = this.urls.get(name);
      if (!url) {
        const blob = new Blob([packImage.bytes as unknown as BlobPart], { type: packImage.mime });
        url = URL.createObjectURL(blob);
        this.urls.set(name, url);
      }
      return { url, tier: 1, logicalName: name };
    }

    const builtin = resolveBuiltin(name);
    if (builtin) return { url: builtin, tier: 2, logicalName: name };

    return { url: colorBlockDataUrl(name, hint), tier: 3, logicalName: name };
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    for (const url of this.urls.values()) URL.revokeObjectURL(url);
    this.urls.clear();
  }
}
