import type { Condition, ComparisonOp, GameState, JsonValue } from './types';
import { getPath } from './paths';
import { deepEqual, isJsonObject } from './util';

const PATH_KEYS = ['stat', 'flag', 'path'] as const;
const OPS: ReadonlySet<string> = new Set(['==', '!=', '>', '>=', '<', '<=', 'in', 'not_in']);

function compare(actual: JsonValue | undefined, op: ComparisonOp, expected: JsonValue): boolean {
  switch (op) {
    case '==':
      return deepEqual(actual, expected);
    case '!=':
      return !deepEqual(actual, expected);
    case '>':
    case '>=':
    case '<':
    case '<=': {
      if (typeof actual !== 'number' || typeof expected !== 'number') return false;
      if (op === '>') return actual > expected;
      if (op === '>=') return actual >= expected;
      if (op === '<') return actual < expected;
      return actual <= expected;
    }
    case 'in':
      return Array.isArray(expected) && expected.some((item) => deepEqual(actual, item));
    case 'not_in':
      return !(Array.isArray(expected) && expected.some((item) => deepEqual(actual, item)));
    default:
      return false;
  }
}

/**
 * 结构化条件求值。任何无法识别的结构一律视为 false（锁定），绝不抛错、绝不 eval。
 */
export function evaluateCondition(condition: Condition | undefined, state: GameState): boolean {
  if (condition === undefined) return true;
  if (!isJsonObject(condition)) return false;
  const record = condition as Record<string, JsonValue>;
  const keys = Object.keys(record);

  if (keys.length === 1) {
    const key = keys[0];
    const value = record[key];
    if (key === 'all') {
      return Array.isArray(value) && value.every((item) => evaluateCondition(item as Condition, state));
    }
    if (key === 'any') {
      return Array.isArray(value) && value.length > 0 && value.some((item) => evaluateCondition(item as Condition, state));
    }
    if (key === 'not') {
      return !evaluateCondition(value as Condition, state);
    }
  }

  const pathKey = keys.find((k) => (PATH_KEYS as readonly string[]).includes(k));
  if (pathKey === undefined) return false;
  const path = record[pathKey];
  if (typeof path !== 'string' || path === '') return false;
  const actual = getPath(state, path);

  if ('op' in record) {
    const op = record.op;
    if (typeof op !== 'string' || !OPS.has(op)) return false;
    if (!('value' in record)) return false;
    return compare(actual, op as ComparisonOp, record.value);
  }
  if ('eq' in record) return deepEqual(actual, record.eq);
  if ('neq' in record) return !deepEqual(actual, record.neq);
  return false;
}

/** 校验条件结构，返回人可读的问题；用于内容包导入时提示创作者。 */
export function inspectCondition(condition: unknown, path = 'condition'): string[] {
  if (condition === undefined) return [];
  if (!isJsonObject(condition)) return [`${path}: 条件必须是对象`];
  const record = condition;
  const keys = Object.keys(record);
  if (keys.length === 0) return [`${path}: 条件对象为空`];

  if (keys.length === 1) {
    const key = keys[0];
    if (key === 'all' || key === 'any') {
      const arr = record[key];
      if (!Array.isArray(arr)) return [`${path}.${key}: 必须是数组`];
      return arr.flatMap((item, i) => inspectCondition(item, `${path}.${key}[${i}]`));
    }
    if (key === 'not') return inspectCondition(record.not, `${path}.not`);
  }

  const pathKey = keys.find((k) => (PATH_KEYS as readonly string[]).includes(k));
  if (pathKey === undefined) return [`${path}: 缺少 stat/flag/path 选择器`];
  const problems: string[] = [];
  if (typeof record[pathKey] !== 'string' || record[pathKey] === '') {
    problems.push(`${path}.${pathKey}: 必须是非空字符串路径`);
  }
  const hasOp = 'op' in record;
  const hasEq = 'eq' in record;
  const hasNeq = 'neq' in record;
  if (hasOp) {
    if (!OPS.has(String(record.op))) problems.push(`${path}.op: 不支持的运算符 ${String(record.op)}`);
    if (!('value' in record)) problems.push(`${path}: op 缺少 value`);
  } else if (!hasEq && !hasNeq) {
    problems.push(`${path}: 需要 op+value 或 eq/neq`);
  }
  return problems;
}
