import { useState } from 'react';
import type { PackSummary } from '../engine/types';
import { FileButton } from './fileUtils';
import { formatTime } from './uiTypes';

export interface HomeScreenProps {
  packs: PackSummary[];
  busy: boolean;
  platformLabel: string;
  storageLabel: string;
  onImportPack(file: File): void;
  onImportSave(file: File): void;
  onOpenPack(summary: PackSummary): void;
  onDeletePack(summary: PackSummary): void;
  onLoadSample(): void;
  onOpenAuthor(): void;
}

export function HomeScreen({
  packs,
  busy,
  platformLabel,
  storageLabel,
  onImportPack,
  onImportSave,
  onOpenPack,
  onDeletePack,
  onLoadSample,
  onOpenAuthor,
}: HomeScreenProps) {
  const [confirmId, setConfirmId] = useState<string | null>(null);

  return (
    <main className="home">
      <header className="home-hero">
        <p className="brand-mark">CRADLE</p>
        <h1>Cradle · 摇篮</h1>
        <p className="tagline">内容包驱动的文字 / 立绘游戏框架 · {platformLabel}</p>
      </header>

      <section className="home-actions" aria-label="导入">
        <FileButton
          label="导入内容包 (.zip)"
          accept=".zip,application/zip"
          onFile={onImportPack}
          disabled={busy}
          className="btn btn-primary"
          testId="import-pack"
        />
        <FileButton
          label="导入存档 (.json)"
          accept=".json,application/json"
          onFile={onImportSave}
          disabled={busy}
          testId="import-save"
        />
        <button type="button" className="btn" onClick={onLoadSample} disabled={busy} data-testid="load-sample">
          载入验收示例包
        </button>
        <button type="button" className="btn" onClick={onOpenAuthor} data-testid="open-author">
          创作模式
        </button>
      </section>

      <section className="pack-section" aria-label="内容包库">
        <h2>内容包库</h2>
        {packs.length === 0 ? (
          <div className="empty-state">
            <p>还没有导入任何内容包。</p>
            <p className="muted">
              内容包是一个 zip：<code>manifest.json</code> + <code>story.json</code> + <code>state.json</code> +{' '}
              <code>images/</code>。
            </p>
          </div>
        ) : (
          <ul className="pack-list" data-testid="pack-list">
            {packs.map((pack) => (
              <li className="pack-card" key={pack.id} data-testid={`pack-${pack.id}`}>
                <div className="pack-main">
                  <h3>{pack.name}</h3>
                  <p className="pack-meta">
                    <code>{pack.id}</code> · v{pack.version} · {pack.nodeCount} 个节点
                  </p>
                  <p className="pack-meta muted">导入于 {formatTime(pack.importedAt)}</p>
                </div>
                <div className="pack-actions">
                  <button
                    type="button"
                    className="btn btn-primary"
                    onClick={() => onOpenPack(pack)}
                    disabled={busy}
                    data-testid={`open-${pack.id}`}
                  >
                    开始
                  </button>
                  {confirmId === pack.id ? (
                    <>
                      <button
                        type="button"
                        className="btn btn-danger"
                        onClick={() => {
                          onDeletePack(pack);
                          setConfirmId(null);
                        }}
                      >
                        确认删除
                      </button>
                      <button type="button" className="btn btn-ghost" onClick={() => setConfirmId(null)}>
                        取消
                      </button>
                    </>
                  ) : (
                    <button type="button" className="btn btn-ghost" onClick={() => setConfirmId(pack.id)}>
                      删除
                    </button>
                  )}
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section className="home-notes">
        <h2>运行时能力</h2>
        <ul>
          <li>zip 在内存中解压（fflate），不依赖 File System Access API</li>
          <li>结构化条件（all / any / not、比较与集合），不使用 eval</li>
          <li>四视觉槽位：bg / playerPortrait / npcPortraits / map，三级资源回退</li>
          <li>{storageLabel} 存档，手动槽 + 独立自动槽，可导出 / 导入 JSON</li>
        </ul>
      </section>

      <footer className="home-footer">
        引擎 0.1.0 · {storageLabel} · 内容包与引擎分离 · 缺失资源与缺失节点一律降级显示
      </footer>
    </main>
  );
}
