import type { ContentPack, SaveData, StoryNode, VisualSlot } from './types';
import { getPath } from './paths';
import { inspectCondition } from './conditions';
import { isJsonObject, isPlainJson } from './util';

export const ENGINE_VERSION = '0.1.0';
export const SAVE_VERSION = 1;

export interface Semver {
  major: number;
  minor: number;
  patch: number;
}

export function parseSemver(value: unknown): Semver | null {
  if (typeof value !== 'string') return null;
  const match = /^(\d+)\.(\d+)\.(\d+)$/.exec(value.trim());
  if (!match) return null;
  return { major: Number(match[1]), minor: Number(match[2]), patch: Number(match[3]) };
}

export interface CompatResult {
  ok: boolean;
  exact: boolean;
  reason?: string;
}

/** 主/次版本必须一致；补丁号差异视为兼容。 */
export function checkEngineVersion(packEngineVersion: string): CompatResult {
  const pack = parseSemver(packEngineVersion);
  const engine = parseSemver(ENGINE_VERSION);
  if (!pack || !engine) {
    return { ok: false, exact: false, reason: `无法解析 engineVersion "${packEngineVersion}"（应为 x.y.z）` };
  }
  if (pack.major !== engine.major || pack.minor !== engine.minor) {
    return {
      ok: false,
      exact: false,
      reason: `内容包要求引擎 ${packEngineVersion}，当前引擎 ${ENGINE_VERSION}，主/次版本不一致，请更换对应引擎或内容包`,
    };
  }
  return { ok: true, exact: pack.patch === engine.patch };
}

const VALID_SLOTS: ReadonlySet<string> = new Set(['bg', 'playerPortrait', 'npcPortraits', 'map']);
const VALID_LAYOUTS: ReadonlySet<string> = new Set(['background', 'stacked']);
const EFFECT_KEYS: ReadonlySet<string> = new Set(['set', 'inc', 'dec', 'push', 'remove', 'limit']);

export interface PackValidation {
  errors: string[];
  warnings: string[];
}

function validateNode(
  node: StoryNode,
  index: number,
  knownIds: Set<string>,
  warnings: string[],
): string[] {
  const label = `story[${index}]`;
  const errors: string[] = [];
  if (!isJsonObject(node)) return [`${label}: 节点必须是对象`];
  if (typeof node.id !== 'string' || node.id.trim() === '') errors.push(`${label}: id 缺失`);
  if (typeof node.text !== 'string') errors.push(`${label}(${node.id}): text 必须是字符串`);
  if (node.layout !== undefined && !VALID_LAYOUTS.has(String(node.layout))) {
    errors.push(`${label}(${node.id}): layout 只能是 background / stacked`);
  }
  if (node.images !== undefined) {
    if (!Array.isArray(node.images)) errors.push(`${label}(${node.id}): images 必须是数组`);
    else {
      node.images.forEach((image, i) => {
        if (!isJsonObject(image) || typeof image.placeholder !== 'string' || image.placeholder === '') {
          errors.push(`${label}(${node.id}).images[${i}]: placeholder 缺失`);
          return;
        }
        if (image.slot !== undefined && !VALID_SLOTS.has(String(image.slot))) {
          warnings.push(`${label}(${node.id}).images[${i}]: 未知槽位 "${String(image.slot)}"，按 npcPortraits 处理`);
        }
        if (image.bindState !== undefined && String(image.slot) !== 'playerPortrait') {
          warnings.push(`${label}(${node.id}).images[${i}]: bindState 只对 playerPortrait 生效`);
        }
      });
    }
  }
  if (node.effects !== undefined && !isJsonObject(node.effects)) {
    errors.push(`${label}(${node.id}): effects 必须是对象`);
  } else if (isJsonObject(node.effects)) {
    for (const key of Object.keys(node.effects)) {
      if (!EFFECT_KEYS.has(key)) warnings.push(`${label}(${node.id}).effects: 未知操作 "${key}"，将被忽略`);
    }
  }
  if (node.choices !== undefined) {
    if (!Array.isArray(node.choices)) errors.push(`${label}(${node.id}): choices 必须是数组`);
    else {
      node.choices.forEach((choice, i) => {
        if (!isJsonObject(choice)) {
          errors.push(`${label}(${node.id}).choices[${i}]: 选项必须是对象`);
          return;
        }
        if (typeof choice.text !== 'string' || choice.text === '') errors.push(`${label}(${node.id}).choices[${i}]: text 缺失`);
        if (typeof choice.targetId !== 'string' || choice.targetId === '') {
          errors.push(`${label}(${node.id}).choices[${i}]: targetId 缺失`);
        } else if (!knownIds.has(choice.targetId)) {
          warnings.push(
            `${label}(${node.id}).choices[${i}]: 目标节点 "${choice.targetId}" 未填写，将显示「内容未填充」页`,
          );
        }
        errors.push(...inspectCondition(choice.condition, `${label}(${node.id}).choices[${i}].condition`));
        if (choice.disabledIf !== undefined) {
          errors.push(...inspectCondition(choice.disabledIf, `${label}(${node.id}).choices[${i}].disabledIf`));
        }
        if (choice.hideIfLocked !== undefined && typeof choice.hideIfLocked !== 'boolean') {
          errors.push(`${label}(${node.id}).choices[${i}]: hideIfLocked 必须是布尔值`);
        }
      });
    }
  }
  return errors;
}

export function validateContentPack(pack: ContentPack): PackValidation {
  const errors: string[] = [];
  const warnings: string[] = [];
  if (!isJsonObject(pack)) return { errors: ['内容包必须是对象'], warnings };

  const manifest = pack.manifest;
  if (!isJsonObject(manifest)) {
    errors.push('manifest.json 缺失或不是对象');
  } else {
    for (const field of ['id', 'name', 'version', 'engineVersion', 'entry'] as const) {
      if (typeof manifest[field] !== 'string' || manifest[field] === '') errors.push(`manifest.${field} 缺失`);
    }
    if (errors.length === 0) {
      const compat = checkEngineVersion(manifest.engineVersion);
      if (!compat.ok) errors.push(compat.reason ?? 'engineVersion 不兼容');
    }
  }

  if (!Array.isArray(pack.nodes)) {
    errors.push('story.json 必须是节点数组');
    return { errors, warnings };
  }
  if (pack.nodes.length === 0) errors.push('story.json 至少需要一个节点');

  const ids = new Set<string>();
  pack.nodes.forEach((node) => {
    if (isJsonObject(node) && typeof node.id === 'string') {
      if (ids.has(node.id)) errors.push(`节点 id 重复: ${node.id}`);
      ids.add(node.id);
    }
  });

  pack.nodes.forEach((node, i) => errors.push(...validateNode(node, i, ids, warnings)));

  if (isJsonObject(manifest) && typeof manifest.entry === 'string' && !ids.has(manifest.entry)) {
    errors.push(`manifest.entry 指向不存在的节点: ${manifest.entry}`);
  }

  if (!isJsonObject(pack.initialState)) errors.push('state.json 必须是对象');
  else if (!isPlainJson(pack.initialState)) errors.push('state.json 只能包含可 JSON 序列化的数据');

  validateBattles(pack, ids, errors, warnings);

  return { errors, warnings };
}

function validateBattles(
  pack: ContentPack,
  nodeIds: Set<string>,
  errors: string[],
  warnings: string[],
): void {
  const battles = pack.battles ?? {};
  const battleIds = new Set(Object.keys(battles));

  for (const node of pack.nodes) {
    if (!isJsonObject(node)) continue;
    if (typeof node.battle === 'string' && node.battle !== '' && !battleIds.has(node.battle)) {
      warnings.push(`节点 "${node.id}" 引用了未定义的战斗 "${node.battle}"，将按普通节点处理`);
    }
    if (Array.isArray(node.randomNext)) {
      if (node.randomNext.length === 0) {
        warnings.push(`节点 "${node.id}" 的 randomNext 为空，会直接显示该节点`);
      }
      node.randomNext.forEach((option, index) => {
        if (!isJsonObject(option) || typeof option.targetId !== 'string') {
          errors.push(`节点 "${node.id}" 的 randomNext[${index}] 缺少 targetId`);
          return;
        }
        if (typeof option.weight !== 'number' || !(option.weight > 0)) {
          errors.push(`节点 "${node.id}" 的 randomNext[${index}].weight 必须是正数`);
        }
        if (!nodeIds.has(option.targetId)) {
          warnings.push(`节点 "${node.id}" 的 randomNext[${index}] 指向不存在的节点 "${option.targetId}"`);
        }
      });
    }
  }

  for (const [id, battle] of Object.entries(battles)) {
    if (!isJsonObject(battle)) {
      errors.push(`battles.${id} 必须是对象`);
      continue;
    }
    if (battle.format !== 'duel') errors.push(`battles.${id}.format 目前只支持 "duel"`);
    for (const field of ['initial', 'min', 'max', 'fleeAt'] as const) {
      if (typeof battle.distance?.[field] !== 'number') errors.push(`battles.${id}.distance.${field} 必须是数字`);
    }
    for (const participant of battle.participants ?? []) {
      if (typeof participant.speed !== 'number' || participant.speed <= 0) {
        errors.push(`battles.${id}.participants["${participant.id}"].speed 必须是正数`);
      }
      if (typeof participant.stamina !== 'number' || participant.stamina <= 0) {
        errors.push(`battles.${id}.participants["${participant.id}"].stamina 必须是正数`);
      }
    }
    for (const [outcome, target] of Object.entries(battle.outcomes ?? {})) {
      if (typeof target !== 'string' || target === '') {
        errors.push(`battles.${id}.outcomes.${outcome} 必须是节点 id`);
      } else if (!nodeIds.has(target)) {
        warnings.push(`battles.${id}.outcomes.${outcome} 指向不存在的节点 "${target}"`);
      }
    }
  }
}

/** 校验引用到的 state 路径，返回在初始状态里找不到的路径（用于创作者提示）。 */
export function collectMissingStatePaths(pack: ContentPack): string[] {
  const missing = new Set<string>();
  const check = (text: string) => {
    for (const match of text.matchAll(/\{\{\s*([^{}]+?)\s*\}\}/g)) {
      const path = match[1].trim();
      if (path && getPath(pack.initialState, path) === undefined) missing.add(path);
    }
  };
  for (const node of pack.nodes) {
    check(node.text);
    for (const choice of node.choices ?? []) check(choice.text);
  }
  return [...missing];
}

export interface SaveValidation {
  errors: string[];
  warnings: string[];
}

export function isSaveData(data: unknown): data is SaveData {
  if (!isJsonObject(data)) return false;
  if (typeof data.saveVersion !== 'number' || data.saveVersion !== SAVE_VERSION) return false;
  if (typeof data.currentNodeId !== 'string') return false;
  if (!isJsonObject(data.state)) return false;
  return true;
}

export function validateSave(data: unknown, pack?: ContentPack): SaveValidation {
  const errors: string[] = [];
  const warnings: string[] = [];
  if (!isJsonObject(data)) return { errors: ['存档必须是 JSON 对象'], warnings };
  if (!isPlainJson(data)) return { errors: ['存档包含非 JSON 数据（Date/函数/DOM/循环引用）'], warnings };

  if (data.saveVersion !== SAVE_VERSION) {
    errors.push(`存档版本 saveVersion=${String(data.saveVersion)}，当前只支持 ${SAVE_VERSION}`);
  }
  if (typeof data.engineVersion !== 'string') errors.push('存档缺少 engineVersion');
  if (typeof data.packId !== 'string' || data.packId === '') errors.push('存档缺少 packId');
  if (typeof data.packVersion !== 'string') errors.push('存档缺少 packVersion');
  if (typeof data.slot !== 'string' || data.slot === '') errors.push('存档缺少 slot');
  else if (!/^(auto|manual)_\d+$/.test(data.slot)) warnings.push(`槽位命名不符合 auto_N / manual_N: ${data.slot}`);
  if (typeof data.timestamp !== 'number' || !Number.isFinite(data.timestamp)) errors.push('存档 timestamp 非法');
  if (typeof data.currentNodeId !== 'string' || data.currentNodeId === '') errors.push('存档缺少 currentNodeId');
  if (!isJsonObject(data.state)) errors.push('存档 state 必须是对象');
  if (!Array.isArray(data.history) || data.history.some((id) => typeof id !== 'string')) {
    errors.push('存档 history 必须是字符串数组');
  }

  if (pack) {
    if (typeof data.packId === 'string' && data.packId !== pack.manifest.id) {
      errors.push(`存档属于内容包 "${data.packId}"，与当前包 "${pack.manifest.id}" 不匹配`);
    }
    if (typeof data.currentNodeId === 'string' && !pack.nodes.some((n) => n.id === data.currentNodeId)) {
      warnings.push(`存档节点 "${data.currentNodeId}" 在当前内容包中不存在，读档后将进入缺失节点页`);
    }
    if (typeof data.packVersion === 'string' && data.packVersion !== pack.manifest.version) {
      warnings.push(`存档记录的内容包版本 ${data.packVersion} 与当前 ${pack.manifest.version} 不一致`);
    }
  }
  return { errors, warnings };
}

export const VALID_SLOT_VALUES: readonly VisualSlot[] = ['bg', 'playerPortrait', 'npcPortraits', 'map'];
