import type { ContentPack, GameState, ImageRef, Layout, MissingReason, SaveData, StoryNode } from './types';
import type { BattleDefinition, BattleResult } from './battle/types';
import { applyEffects } from './effects';
import { evaluateCondition } from './conditions';
import { interpolate } from './interpolate';
import { setPath } from './paths';
import { getPath } from './paths';
import { cloneJson, isJsonObject } from './util';
import { ENGINE_VERSION, SAVE_VERSION } from './validate';

function missingMessage(reason: MissingReason, nodeId: string): string {  switch (reason) {
    case 'unwritten':
      return `作者还没有填写节点 "${nodeId}"`;
    case 'entry-missing':
      return `内容包入口 "${nodeId}" 不存在`;
    case 'save-node-missing':
      return `存档节点 "${nodeId}" 在当前内容包中不存在`;
    case 'invalid-node':
      return `节点 "${nodeId}" 结构不完整`;
  }
}

export interface ChoiceView {
  index: number;
  text: string;
  targetId: string;
  visible: boolean;
  enabled: boolean;
  lockedReason?: string;
}

export interface SceneView {
  nodeId: string;
  layout: Layout;
  text: string;
  images: ImageRef[];
  choices: ChoiceView[];
  issues: string[];
  /** 该节点需要先打一场（battles.json 中的定义） */
  battle?: { id: string; definition: BattleDefinition };
  /** 进入后结束本局，回到标题 */
  endGame?: boolean;
}

export type NavigationResult =
  | { kind: 'node'; view: SceneView }
  | {
      kind: 'missing';
      reason: MissingReason;
      targetId: string;
      returnNodeId: string | null;
      message: string;
    }
  | { kind: 'invalid'; message: string };

function pickWeightedTarget(options: NonNullable<StoryNode['randomNext']>): string | null {
  const valid = options.filter(
    (option) =>
      typeof option.targetId === 'string' &&
      option.targetId !== '' &&
      Number.isFinite(option.weight) &&
      option.weight > 0,
  );
  if (valid.length === 0) return null;
  const total = valid.reduce((sum, option) => sum + option.weight, 0);
  let roll = Math.random() * total;
  for (const option of valid) {
    roll -= option.weight;
    if (roll < 0) return option.targetId;
  }
  return valid[valid.length - 1].targetId;
}

/**
 * 剧本运行时：只负责节点流转、条件判定、变量插值与状态变更。
 * 不认识任何具体的内容包字段，也不碰 UI / 存储 / 图片。
 */
export class StoryEngine {
  readonly pack: ContentPack;
  state: GameState;
  currentNodeId: string | null = null;
  history: string[] = [];
  private battleStartState: GameState | null = null;

  private readonly nodes: Map<string, StoryNode>;

  constructor(pack: ContentPack) {
    this.pack = pack;
    this.nodes = new Map(pack.nodes.map((node) => [node.id, node]));
    this.state = cloneJson(pack.initialState);
    this.migrateLegacyState();
  }

  /** 旧存档只有 flags.samuelMet 时，补上 samuel.met / 吹箭筒归属。 */
  private migrateLegacyState(): void {
    const flags = this.state.flags;
    if (!isJsonObject(flags) || flags.samuelMet !== true) return;
    const samuel = this.state.samuel;
    if (!isJsonObject(samuel) || samuel.met !== true) setPath(this.state, 'samuel.met', true);
    const blowgun = this.state.blowgun;
    if (!isJsonObject(blowgun) || blowgun.owned === undefined) setPath(this.state, 'blowgun.owned', true);
  }

  getNode(id: string): StoryNode | undefined {
    return this.nodes.get(id);
  }

  hasNode(id: string): boolean {
    return this.nodes.has(id);
  }

  start(): NavigationResult {
    return this.enter(this.pack.manifest.entry, 'entry-missing');
  }

  /** 进入节点：先执行节点 effects，再基于新状态渲染文本与选项。 */
  enter(nodeId: string, reason: MissingReason = 'unwritten', depth = 0): NavigationResult {
    const node = this.nodes.get(nodeId);
    if (!node) {
      return {
        kind: 'missing',
        reason,
        targetId: nodeId,
        returnNodeId: this.currentNodeId,
        message: missingMessage(reason, nodeId),
      };
    }
    if (typeof node.text !== 'string') {
      return {
        kind: 'missing',
        reason: 'invalid-node',
        targetId: nodeId,
        returnNodeId: this.currentNodeId,
        message: missingMessage('invalid-node', nodeId),
      };
    }
    if (node.battle) this.battleStartState = cloneJson(this.state);
    this.currentNodeId = nodeId;
    const problems = applyEffects(node.effects, this.state);
    if (this.history[this.history.length - 1] !== nodeId) this.history.push(nodeId);

    // 随机分流：用于「拐人时 50% 遇到米埃尔」这类事件，跳转本身不显示中转节点。
    if (depth < 8 && node.randomNext && node.randomNext.length > 0) {
      const target = pickWeightedTarget(node.randomNext);
      if (target && this.nodes.has(target)) {
        return this.enter(target, 'unwritten', depth + 1);
      }
    }

    return {
      kind: 'node',
      view: this.buildView(node, problems.map((p) => `${p.path || 'effects'}: ${p.message}`)),
    };
  }

  view(): SceneView | null {
    if (!this.currentNodeId) return null;
    const node = this.nodes.get(this.currentNodeId);
    if (!node) return null;
    return this.buildView(node, []);
  }

  choose(choiceIndex: number): NavigationResult {
    if (!this.currentNodeId) return { kind: 'invalid', message: '尚未开始游戏' };
    const node = this.nodes.get(this.currentNodeId);
    if (!node) return { kind: 'invalid', message: `当前节点 "${this.currentNodeId}" 不存在` };
    const choice = node.choices?.[choiceIndex];
    if (!choice) return { kind: 'invalid', message: `选项 #${choiceIndex} 不存在` };
    if (!evaluateCondition(choice.condition, this.state)) {
      return { kind: 'invalid', message: '该选项条件未满足' };
    }
    const problems = applyEffects(choice.effects, this.state);
    if (choice.rewindBattle && this.battleStartState) {
      const before = cloneJson(this.state);
      const keep: Record<string, unknown> = {};
      for (const path of choice.rewindKeep ?? []) keep[path] = getPath(before, path);
      this.state = cloneJson(this.battleStartState);
      for (const [path, value] of Object.entries(keep)) {
        if (value !== undefined) setPath(this.state, path, value as never);
      }
    }
    const result = this.enter(choice.targetId, 'unwritten');
    if (result.kind === 'node' && problems.length > 0) {
      result.view.issues.push(...problems.map((p) => `${p.path || 'effects'}: ${p.message}`));
    }
    return result;
  }

  /** 读档：直接恢复快照，不重放 effects。 */
  restore(save: SaveData): NavigationResult {
    this.state = cloneJson(save.state);
    this.migrateLegacyState();
    this.history = [...save.history];
    this.currentNodeId = save.currentNodeId;
    const node = this.nodes.get(save.currentNodeId);
    if (!node) {
      return {
        kind: 'missing',
        reason: 'save-node-missing',
        targetId: save.currentNodeId,
        returnNodeId: null,
        message: missingMessage('save-node-missing', save.currentNodeId),
      };
    }
    return { kind: 'node', view: this.buildView(node, []) };
  }

  snapshot(slot: string, timestamp = Date.now()): SaveData {
    if (!this.currentNodeId) throw new Error('尚未开始游戏，无法存档');
    return {
      saveVersion: SAVE_VERSION,
      engineVersion: ENGINE_VERSION,
      packId: this.pack.manifest.id,
      packVersion: this.pack.manifest.version,
      slot,
      timestamp,
      currentNodeId: this.currentNodeId,
      state: cloneJson(this.state),
      history: [...this.history],
    };
  }

  /** 战斗结束：把结果写回 state，再进入结果节点。 */
  finishBattle(battleId: string, result: BattleResult, targetId: string): NavigationResult {
    setPath(this.state, `battle.${battleId}.result`, result);
    setPath(this.state, `battle.${battleId}.finished`, true);
    return this.enter(targetId, 'unwritten');
  }

  private buildView(node: StoryNode, issues: string[]): SceneView {
    const choices: ChoiceView[] = (node.choices ?? []).map((choice, index) => {
      const allowed = evaluateCondition(choice.condition, this.state);
      const disabled = allowed && choice.disabledIf ? evaluateCondition(choice.disabledIf, this.state) : false;
      const locked = !allowed || disabled;
      const hidden = !allowed && choice.hideIfLocked !== true;
      return {
        index,
        text: interpolate(choice.text, this.state),
        targetId: choice.targetId,
        visible: !hidden,
        enabled: !locked,
        lockedReason: locked ? (disabled ? '条件未满足' : '条件未满足') : undefined,
      };
    });

    let battle: { id: string; definition: BattleDefinition } | undefined;
    if (node.battle) {
      const definition = this.pack.battles?.[node.battle];
      if (definition) {
        battle = { id: node.battle, definition };
      } else {
        issues.push(
          `节点 "${node.id}" 引用了未定义的战斗 "${node.battle}"（内容包可能缺少 battles.json，请重新导入）`,
        );
      }
    }

    const variant = node.textVariants?.find((item) => evaluateCondition(item.condition, this.state));
    return {
      nodeId: node.id,
      layout: node.layout ?? 'stacked',
      text: interpolate(variant?.text ?? node.text, this.state),
      images: node.images ?? [],
      choices,
      issues,
      battle,
      endGame: node.endGame === true,
    };
  }
}
