import type { SaveData } from '../engine/types';
import { isAutoSlot } from '../engine/types';
import { validateSave } from '../engine/validate';
import type { StorageAdapter } from './StorageAdapter';
import { getDatabase, requestAsPromise, SAVES_STORE, saveKey, txDone, type SaveRecord } from './idb';

export class WebIndexedDBStorage implements StorageAdapter {
  readonly kind = 'web-idb' as const;

  async init(): Promise<void> {
    await getDatabase();
  }

  async list(packId?: string): Promise<SaveData[]> {
    const db = await getDatabase();
    const tx = db.transaction(SAVES_STORE, 'readonly');
    const store = tx.objectStore(SAVES_STORE);
    const request = packId ? store.index('byPack').getAll(packId) : store.getAll();
    const records = (await requestAsPromise(request)) as SaveRecord[];
    await txDone(tx);
    return records.map((record) => record.save).sort((a, b) => b.timestamp - a.timestamp);
  }

  async get(packId: string, slot: string): Promise<SaveData | null> {
    const db = await getDatabase();
    const tx = db.transaction(SAVES_STORE, 'readonly');
    const record = (await requestAsPromise(tx.objectStore(SAVES_STORE).get(saveKey(packId, slot)))) as
      | SaveRecord
      | undefined;
    await txDone(tx);
    return record?.save ?? null;
  }

  async put(save: SaveData): Promise<void> {
    const { errors } = validateSave(save);
    if (errors.length > 0) throw new Error(`存档不合法：${errors.join('；')}`);
    if (!isAutoSlot(save.slot) && !/^manual_\d+$/.test(save.slot)) {
      throw new Error(`手动存档槽位必须是 manual_N，收到 "${save.slot}"`);
    }
    if (isAutoSlot(save.slot) && !/^auto_\d+$/.test(save.slot)) {
      throw new Error(`自动存档槽位必须是 auto_N，收到 "${save.slot}"`);
    }
    // 自动存档永远写入 auto_N 命名空间，结构上无法覆盖 manual_N；这里再显式断言一次。
    if (isAutoSlot(save.slot)) {
      const existing = await this.get(save.packId, save.slot);
      if (existing && !isAutoSlot(existing.slot)) {
        throw new Error('自动存档不得覆盖手动槽位');
      }
    }
    const db = await getDatabase();
    const tx = db.transaction(SAVES_STORE, 'readwrite');
    const record: SaveRecord = { key: saveKey(save.packId, save.slot), packId: save.packId, slot: save.slot, save };
    tx.objectStore(SAVES_STORE).put(record);
    await txDone(tx);
  }

  async remove(packId: string, slot: string): Promise<void> {
    const db = await getDatabase();
    const tx = db.transaction(SAVES_STORE, 'readwrite');
    tx.objectStore(SAVES_STORE).delete(saveKey(packId, slot));
    await txDone(tx);
  }
}
