import type { GameState, JsonValue } from './types';
import { isJsonObject } from './util';

const FORBIDDEN_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

/**
 * 点号路径解析。任何包含原型污染键的路径整体视为非法，返回空数组，
 * 避免 "a.__proto__.b" 被静默重写成 "a.b"。
 */
export function splitPath(path: string): string[] {
  if (typeof path !== 'string' || path.trim() === '') return [];
  const parts = path.split('.').map((s) => s.trim());
  if (parts.some((p) => p === '' || FORBIDDEN_KEYS.has(p))) return [];
  return parts;
}

export function getPath(state: GameState, path: string): JsonValue | undefined {
  const parts = splitPath(path);
  if (parts.length === 0) return undefined;
  let cur: JsonValue = state;
  for (const part of parts) {
    if (!isJsonObject(cur)) return undefined;
    const next: JsonValue | undefined = cur[part];
    if (next === undefined) return undefined;
    cur = next;
  }
  return cur;
}

export function setPath(state: GameState, path: string, value: JsonValue): boolean {
  const parts = splitPath(path);
  if (parts.length === 0) return false;
  let cur: Record<string, JsonValue> = state;
  for (let i = 0; i < parts.length - 1; i += 1) {
    const key = parts[i];
    const next = cur[key];
    if (!isJsonObject(next)) {
      const created: Record<string, JsonValue> = {};
      cur[key] = created;
      cur = created;
    } else {
      cur = next;
    }
  }
  cur[parts[parts.length - 1]] = value;
  return true;
}

export function deletePath(state: GameState, path: string): boolean {
  const parts = splitPath(path);
  if (parts.length === 0) return false;
  let cur: JsonValue = state;
  for (let i = 0; i < parts.length - 1; i += 1) {
    if (!isJsonObject(cur)) return false;
    const next: JsonValue | undefined = cur[parts[i]];
    if (next === undefined) return false;
    cur = next;
  }
  if (!isJsonObject(cur)) return false;
  const last = parts[parts.length - 1];
  if (!(last in cur)) return false;
  delete cur[last];
  return true;
}
