import type {
  BattleActionConfig,
  BattleActionId,
  BattleActionView,
  BattleDefinition,
  BattleLogEntry,
  BattleResult,
  BattleTeam,
} from './types';

export type TeamOrder = 'stone' | 'melee' | 'wait';

export interface TeamActorView {
  id: string;
  name: string;
  team: BattleTeam;
  stamina: number;
  maxStamina: number;
  gauge: number;
  gaugeThreshold: number;
  /** 到米埃尔的格距；米埃尔本人为 null */
  distance: number | null;
  weapon: 'equipped' | 'ground' | 'stolen';
  weaponOffset?: number;
  order?: TeamOrder;
  portrait?: string;
  down: boolean;
}

export interface TeamBattleSnapshot {
  id: string;
  phase: 'running' | 'playerTurn' | 'finished';
  distanceConfig: BattleDefinition['distance'];
  actors: TeamActorView[];
  actions: BattleActionView[];
  log: BattleLogEntry[];
  result?: BattleResult;
  elapsedSeconds: number;
  mierStatus: string[];
}

export interface TeamBattleOptions {
  allyCount: number;
  playerHasWeapon: boolean;
  hasBlowgun?: boolean;
  proficiency?: number;
  samuelHelp?: boolean;
}

interface Actor {
  id: string;
  name: string;
  team: BattleTeam;
  speed: number;
  stamina: number;
  maxStamina: number;
  gauge: number;
  distance: number;
  weapon: 'equipped' | 'ground' | 'stolen';
  blowgun: 'equipped' | 'ground' | 'stolen';
  weaponOffset: number;
  order?: TeamOrder;
  portrait?: string;
  down: boolean;
}

const ACTION_LABELS: Record<BattleActionId, string> = {
  moveCloser: '靠近',
  moveAway: '远离',
  melee: '近身',
  throwStone: '丢石头',
  blowgun: '吹箭',
  pickupWeapon: '捡起武器',
  pickupBlowgun: '捡吹箭筒',
  dart: '让塞缪尔吹麻醉镖',
  pin: '扣住米埃尔',
  wait: '原地待机',
  flee: '撤退',
};

const ACTION_DEFAULTS: Record<BattleActionId, BattleActionConfig> = {
  moveCloser: { staminaCost: 10 },
  moveAway: { staminaCost: 10 },
  melee: { staminaCost: 10, range: 1, enemyStaminaLoss: 1, dodge: 0 },
  throwStone: { staminaCost: 5, enemyStaminaLoss: 1, dodge: 0 },
  blowgun: { staminaCost: 5, enemyStaminaLoss: 5, dodge: 0 },
  pickupWeapon: { staminaCost: 5 },
  pickupBlowgun: { staminaCost: 5 },
  dart: { staminaCost: 0 },
  pin: { staminaCost: 0 },
  wait: { staminaCost: 0, staminaGain: 10 },
  flee: { staminaCost: 0 },
};

export class TeamBattleSimulator {
  readonly definition: BattleDefinition;

  private readonly actors: Actor[];
  private readonly player: Actor;
  private readonly mier: Actor;
  private readonly actions: Record<BattleActionId, BattleActionConfig>;
  private phase: 'running' | 'playerTurn' | 'finished' = 'running';
  private logEntries: BattleLogEntry[] = [];
  private elapsed = 0;
  private result: BattleResult | undefined;
  private readonly options: { hasBlowgun: boolean; proficiency: number; samuelHelp: boolean };
  private dartUsed = false;
  private dartUntil = 0;
  private mierSensitive = false;
  private grabbed = false;
  private pinned = false;

  constructor(definition: BattleDefinition, options: TeamBattleOptions) {
    this.definition = definition;
    this.options = {
      hasBlowgun: options.hasBlowgun ?? false,
      proficiency: Math.max(0, Math.min(100, options.proficiency ?? 0)),
      samuelHelp: options.samuelHelp ?? false,
    };
    this.actions = { ...ACTION_DEFAULTS };
    for (const key of Object.keys(definition.actions ?? {}) as BattleActionId[]) {
      this.actions[key] = { ...ACTION_DEFAULTS[key], ...(definition.actions?.[key] ?? {}) };
    }

    const playerDef = definition.participants.find((participant) => participant.team === 'player');
    const enemyDef = definition.participants.find((participant) => participant.team === 'enemy');
    const allyTemplate = definition.team?.ally ?? {};
    const initial = definition.distance.initial;

    this.player = {
      id: playerDef?.id ?? 'thief',
      name: playerDef?.name ?? '无名盗贼',
      team: 'player',
      speed: playerDef?.speed ?? 70,
      stamina: playerDef?.stamina ?? 100,
      maxStamina: playerDef?.stamina ?? 100,
      gauge: 0,
      distance: initial,
        weapon: options.playerHasWeapon ? 'equipped' : 'stolen',
        blowgun: options.hasBlowgun ? 'equipped' : 'stolen',
        weaponOffset: 0,
        portrait: playerDef?.portrait,
        down: false,
      };

    const allies: Actor[] = [];
    for (let index = 0; index < options.allyCount; index += 1) {
      const speed = allyTemplate.speed ?? 70;
      const stamina = allyTemplate.stamina ?? 100;
      allies.push({
        id: `ally${index + 1}`,
        name: allyTemplate.name ? `${allyTemplate.name}${index + 1}` : `盗贼 ${index + 2}`,
        team: 'player',
        speed,
        stamina,
        maxStamina: stamina,
        gauge: 0,
        distance: initial,
        weapon: 'equipped',
        blowgun: options.hasBlowgun ? 'equipped' : 'stolen',
        weaponOffset: 0,
        order: 'stone',
        portrait: allyTemplate.portrait ?? 'player_neutral',
        down: false,
      });
    }

    this.mier = {
      id: enemyDef?.id ?? 'mier',
      name: enemyDef?.name ?? '米埃尔',
      team: 'enemy',
      speed: enemyDef?.speed ?? 100,
      stamina: enemyDef?.stamina ?? 100,
      maxStamina: enemyDef?.stamina ?? 100,
      gauge: 0,
      distance: 0,
      weapon: 'stolen',
      blowgun: 'stolen',
      weaponOffset: 0,
      portrait: enemyDef?.portrait ?? 'char_mier_neutral',
      down: false,
    };

    this.actors = [this.player, ...allies, this.mier];
  }

  getSnapshot(): TeamBattleSnapshot {
    const threshold = this.definition.actionValue?.threshold ?? 100;
    return {
      id: this.definition.id,
      phase: this.phase,
      distanceConfig: this.definition.distance,
      actors: this.actors.map((actor) => ({
        id: actor.id,
        name: actor.name,
        team: actor.team,
        stamina: Math.round(actor.stamina * 10) / 10,
        maxStamina: actor.maxStamina,
        gauge: Math.round((actor.gauge / threshold) * 100),
        gaugeThreshold: threshold,
        distance: actor.team === 'enemy' ? null : actor.distance,
        weapon: actor.weapon,
        weaponOffset: actor.weapon === 'ground' ? actor.weaponOffset : undefined,
        order: actor.order,
        portrait: actor.portrait,
        down: actor.stamina <= 0,
      })),
      actions: this.actionsView(),
      log: this.logEntries.slice(-60),
      result: this.result,
      elapsedSeconds: Math.round(this.elapsed * 10) / 10,
      mierStatus: [
        ...(this.mierSensitive ? ['敏感'] : []),
        ...(this.elapsed < this.dartUntil ? [`麻醉 ${Math.ceil(this.dartUntil - this.elapsed)}s`, '无法行动'] : []),
        ...(this.grabbed ? ['被扣住'] : []),
      ],
    };
  }

  setOrder(actorId: string, order: TeamOrder): boolean {
    const actor = this.actors.find((item) => item.id === actorId && item.team === 'player');
    if (!actor || actor.id === this.player.id) return false;
    actor.order = order;
    this.pushLog(`${actor.name} 改为「${order === 'stone' ? '丢石头' : order === 'melee' ? '近身' : '待机'}」。`, 'info');
    return true;
  }

  tick(deltaMs: number): void {
    if (this.phase === 'finished') return;
    const dt = Math.max(0, Math.min(deltaMs, 500)) / 1000;
    const threshold = this.definition.actionValue?.threshold ?? 100;
    if (this.pinned) {
      this.elapsed += dt;
      const regen = (this.definition.time?.regenPerSecond ?? 1) + (this.mierSensitive ? 10 : 0);
      this.mier.stamina = Math.min(this.mier.maxStamina, this.mier.stamina + regen * dt);
      if (this.elapsed >= this.dartUntil) {
        this.mier.gauge = Math.min(threshold, this.mier.gauge + this.mier.speed * dt);
        if (this.mier.gauge >= threshold - 1e-6) {
          this.player.stamina = Math.max(0, this.player.stamina - 10);
          this.player.distance = Math.min(this.definition.distance.max, this.player.distance + 1);
          this.mier.gauge = 0;
          this.grabbed = false;
          this.pinned = false;
          this.pushLog('米埃尔用满行动值挣脱，把你撞退一格，体力 -10。', 'damage');
          this.phase = 'playerTurn';
          this.resolveOutcome();
        }
        return;
      }
      for (const ally of this.allies()) {
        if (ally.down || ally.stamina <= 0) continue;
        ally.gauge = Math.min(threshold, ally.gauge + ally.speed * dt);
        if (ally.gauge >= threshold - 1e-6) {
          this.allyAct(ally);
          ally.gauge = 0;
        }
      }
      if (this.elapsed >= this.dartUntil) {
        this.player.stamina = Math.max(0, this.player.stamina - 10);
        this.mier.gauge = 0;
        this.grabbed = false;
        this.pinned = false;
        this.pushLog('麻醉结束，米埃尔用尽全部行动值把你撞开，体力 -10。', 'damage');
        this.phase = 'playerTurn';
        this.resolveOutcome();
      }
      return;
    }
    if (this.grabbed) {
      this.elapsed += dt;
      if (this.dartUsed && this.elapsed >= this.dartUntil) {
        this.player.stamina = Math.max(0, this.player.stamina - 10);
        this.mier.gauge = 0;
        this.grabbed = false;
        this.pushLog('麻醉结束，米埃尔用尽行动值把你撞开，体力 -10。', 'damage');
        this.phase = 'playerTurn';
        this.resolveOutcome();
        return;
      }
      if (this.options.samuelHelp && (!this.dartUsed || this.elapsed < this.dartUntil)) {
        this.phase = 'playerTurn';
        return;
      }
      for (const ally of this.allies()) {
        if (ally.down || ally.stamina <= 0) continue;
        ally.gauge = Math.min(threshold, ally.gauge + ally.speed * dt);
        if (ally.gauge >= threshold - 1e-6) {
          this.allyAct(ally);
          ally.gauge = 0;
        }
      }
      if (this.player.stamina <= 0) {
        this.grabbed = false;
        this.syncDown();
        this.pushLog('你倒下了，米埃尔松开你，转向其他盗贼。', 'damage');
      }
      this.phase = 'running';
      this.resolveOutcome();
      return;
    }
    if (this.phase !== 'running') return;
    this.elapsed += dt;
    const regen = this.definition.time?.regenPerSecond ?? 1;

    this.syncDown();
    for (const actor of this.actors) {
      if (actor.down) continue;
      actor.stamina = Math.min(actor.maxStamina, actor.stamina + regen * dt);
      if (actor.team === 'enemy' && this.elapsed < this.dartUntil) continue;
      actor.gauge = Math.min(threshold, actor.gauge + actor.speed * dt);
    }

    if (this.options.hasBlowgun) {
      if (this.mier.stamina < 50) this.mierSensitive = true;
    }
    if (this.mierSensitive) {
      this.mier.stamina = Math.min(this.mier.maxStamina, this.mier.stamina + 10 * dt);
    }

    // 米埃尔优先行动：行动值每满 100 就花 50 丢一次石头
    while (this.mier.gauge >= threshold - 1e-6 && this.phase === 'running' && this.elapsed >= this.dartUntil) {
      this.mierAct();
    }

    // 队友按固定行为自动行动
    for (const ally of this.allies()) {
      if (this.phase !== 'running') break;
      if (ally.stamina > 0 && ally.gauge >= threshold - 1e-6) {
        this.allyAct(ally);
        ally.gauge = 0;
      }
    }

    if (this.phase !== 'running') return;

    if (this.player.stamina > 0 && !this.player.down && this.player.gauge >= threshold - 1e-6) {
      this.phase = 'playerTurn';
      return;
    }

    this.resolveOutcome();
  }

  act(action: BattleActionId): boolean {
    if (this.phase !== 'playerTurn') return false;
    const view = this.actionsView().find((item) => item.id === action);
    if (!view || !view.available) return false;

    const player = this.player;
    const config = this.actions[action];

    switch (action) {
      case 'moveCloser':
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        player.distance = Math.max(this.definition.distance.min, player.distance - 1);
        if (player.weapon === 'ground') player.weaponOffset += 1;
        this.pushLog(`你向前逼近，距离 ${player.distance} 格。`, 'player');
        break;
      case 'moveAway':
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        player.distance = Math.min(this.definition.distance.max, player.distance + 1);
        if (player.weapon === 'ground') player.weaponOffset -= 1;
        this.pushLog(`你向后退开，距离 ${player.distance} 格。`, 'player');
        break;
      case 'melee':
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        this.mier.stamina = Math.max(0, this.mier.stamina - (config.enemyStaminaLoss ?? 1));
        this.pushLog('你挥刀砍向米埃尔。', 'player');
        break;
      case 'throwStone':
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        this.mier.stamina = Math.max(0, this.mier.stamina - (config.enemyStaminaLoss ?? 1));
        this.pushLog('你捡起石头砸向米埃尔。', 'player');
        break;
      case 'pickupWeapon':
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        player.weapon = 'equipped';
        player.weaponOffset = 0;
        this.pushLog('你捡回了短刀。', 'player');
        break;
      case 'blowgun': {
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        const hit = Math.random() * 100 < this.options.proficiency;
        this.pushLog(hit ? '你吹出的箭命中米埃尔，体力 -5。' : '吹箭偏了。', hit ? 'damage' : 'player');
        if (hit) this.mier.stamina = Math.max(0, this.mier.stamina - 5);
        break;
      }
      case 'pickupBlowgun': {
        player.stamina = Math.max(0, player.stamina - config.staminaCost);
        player.blowgun = 'equipped';
        this.pushLog('你捡回了吹箭筒。', 'player');
        break;
      }
      case 'dart': {
        if (this.dartUsed) return false;
        this.dartUsed = true;
        this.dartUntil = this.elapsed + 10;
        this.mierSensitive = true;
        this.pushLog('塞缪尔吹出麻醉镖，米埃尔僵在原地。', 'enemy');
        return true;
      }
      case 'wait': {
        const gain = config.staminaGain ?? 0;
        player.stamina = Math.min(player.maxStamina, player.stamina + gain);
        this.pushLog(`你原地调整呼吸，体力 +${gain}。`, 'player');
        break;
      }
      case 'pin': {
        if (player.distance > 1) return false;
        if (player.distance > 0 && this.elapsed >= this.dartUntil) return false;
        this.pinned = true;
        this.grabbed = true;
        this.phase = 'running';
        this.pushLog('你死死扣住米埃尔，把她压在原地。', 'player');
        return true;
      }
      case 'flee':
        this.finish(player.weapon === 'equipped' ? 'fled_armed' : 'fled_unarmed');
        return true;
    }

    player.gauge = 0;
    this.phase = 'running';
    this.syncDown();
    this.resolveOutcome();
    return true;
  }

  private syncDown(): void {
    for (const actor of this.actors) {
      if (actor.stamina <= 0 && !actor.down) {
        actor.down = true;
        if (actor.team === 'player') {
          this.pushLog(`${actor.name} 倒下了！`, 'damage');
        }
      }
    }
  }

  // ---------- 内部 ----------

  private players(): Actor[] {
    return this.actors.filter((actor) => actor.team === 'player');
  }

  private allies(): Actor[] {
    return this.players().filter((actor) => actor.id !== this.player.id);
  }

  private mierAct(): void {
    if (this.mierSensitive && this.mier.stamina < 50) {
      const nearest = this.players()
        .filter((actor) => !actor.down)
        .sort((a, b) => a.distance - b.distance)[0];
      if (!nearest) {
        this.finish('escaped');
        return;
      }
      for (const actor of this.players()) actor.distance += 1;
      this.mier.gauge = Math.max(0, this.mier.gauge - 100);
      this.pushLog(`米埃尔向后退开，距离 ${nearest.distance + 1} 格。`, 'enemy');
      return;
    }

    const allies = this.players().filter(
      (actor) => actor.id !== this.player.id && !actor.down && actor.distance <= 10,
    );
    const playerTarget = this.player.down || this.player.distance > 10 ? null : this.player;

    // 贴脸时：熟练度不足 50、距离 0 不踢人；距离 1 踢开；熟练度足够则扣住
    if (!this.player.down && this.player.distance <= 1 && !this.dartUsed && this.elapsed >= this.dartUntil) {
      if (this.options.proficiency < 50) {
        if (this.player.distance === 1) {
          this.player.distance = Math.min(this.definition.distance.max, 2);
          this.player.stamina = Math.max(0, this.player.stamina - 10);
          this.mier.gauge = Math.max(0, this.mier.gauge - (this.mierSensitive ? 100 : 50));
          this.pushLog('米埃尔一脚把你踢开，距离回到 2 格，体力 -10。', 'damage');
          this.syncDown();
          this.resolveOutcome();
          return;
        }
      } else {
        this.grabbed = true;
        this.phase = 'playerTurn';
        this.pushLog('米埃尔一把扣住你，把你挡在身前。', 'damage');
        return;
      }
    }

    const target = allies[0] ?? playerTarget;
    if (!target) {
      this.mier.gauge = Math.max(0, this.mier.gauge - (this.mierSensitive ? 100 : 50));
      this.pushLog('米埃尔够不到任何人，原地等待。', 'enemy');
      return;
    }

    const costText = `（消耗 ${this.mierSensitive ? 100 : 50} 行动值）`;
    if (target.distance <= 0) {
      target.distance = Math.min(this.definition.distance.max, 1);
      target.stamina = Math.max(0, target.stamina - 10);
      this.pushLog(`米埃尔踹开 ${target.name}，体力 -10。${costText}`, 'damage');
    } else if (target.blowgun === 'equipped') {
      target.blowgun = 'ground';
      target.stamina = Math.max(0, target.stamina - 10);
      this.pushLog(`米埃尔打落 ${target.name} 的吹箭筒，体力 -10。${costText}`, 'damage');
    } else {
      target.stamina = Math.max(0, target.stamina - 10);
      this.pushLog(`米埃尔用石头砸中 ${target.name}，体力 -10。${costText}`, 'damage');
    }

    this.mier.gauge = Math.max(0, this.mier.gauge - (this.mierSensitive ? 100 : 50));
    this.syncDown();
    this.resolveOutcome();
  }

  private allyAct(ally: Actor): void {
    if (ally.distance > 10) {
      if (ally.stamina >= 10) {
        ally.stamina -= 10;
        ally.distance -= 1;
        this.pushLog(`${ally.name} 向前逼近到 ${ally.distance} 格。`, 'player');
      }
      return;
    }
    if (this.options.hasBlowgun) {
      if (ally.blowgun === 'ground') {
        ally.blowgun = 'equipped';
        this.pushLog(`${ally.name} 捡回了吹箭筒。`, 'player');
        return;
      }
      if (ally.blowgun === 'equipped' && ally.stamina >= 5) {
        ally.stamina -= 5;
        const hit = Math.random() * 100 < this.options.proficiency;
        if (hit && this.pinned) {
          this.mier.stamina = Math.max(0, this.mier.stamina - 10);
          this.pushLog(`${ally.name} 的飞镖命中被扣住的米埃尔，体力 -10。`, 'damage');
        } else if (hit && this.grabbed) {
          this.player.stamina = Math.max(0, this.player.stamina - 5);
          this.pushLog(`${ally.name} 的飞镖扎在你身上，体力 -5。`, 'damage');
        } else {
          this.pushLog(`${ally.name} 吹出一箭${hit ? '，命中米埃尔，体力 -5。' : '，偏了。'}`, hit ? 'damage' : 'player');
          if (hit) this.mier.stamina = Math.max(0, this.mier.stamina - 5);
        }
        return;
      }
    }
    const order = ally.order ?? 'stone';
    if (order === 'wait') {
      ally.stamina = Math.min(ally.maxStamina, ally.stamina + 10);
      this.pushLog(`${ally.name} 原地待机，体力 +10。`, 'info');
      return;
    }

    if (order === 'melee' && ally.weapon === 'equipped') {
      if (ally.distance <= 1) {
        if (ally.stamina >= 10) {
          ally.stamina -= 10;
          if (this.pinned) {
            this.mier.stamina = Math.max(0, this.mier.stamina - 10);
            this.pushLog(`${ally.name} 砍中被扣住的米埃尔，体力 -10。`, 'damage');
          } else if (this.grabbed) {
            this.player.stamina = Math.max(0, this.player.stamina - 5);
            this.pushLog(`${ally.name} 砍在你身上，体力 -5。`, 'damage');
          } else {
            this.mier.stamina = Math.max(0, this.mier.stamina - 1);
            this.pushLog(`${ally.name} 近身砍向米埃尔。`, 'player');
          }
          return;
        }
      } else if (ally.stamina >= 10) {
        ally.stamina -= 10;
        ally.distance = Math.max(this.definition.distance.min, ally.distance - 1);
        this.pushLog(`${ally.name} 向前逼近。`, 'player');
        return;
      }
    }

    if (ally.stamina >= 5) {
      ally.stamina -= 5;
      if (this.pinned) {
        this.mier.stamina = Math.max(0, this.mier.stamina - 10);
        this.pushLog(`${ally.name} 的石头命中被扣住的米埃尔，体力 -10。`, 'damage');
      } else if (this.grabbed) {
        this.player.stamina = Math.max(0, this.player.stamina - 5);
        this.pushLog(`${ally.name} 的石头砸在你身上，体力 -5。`, 'damage');
      } else {
        this.mier.stamina = Math.max(0, this.mier.stamina - 1);
        this.pushLog(`${ally.name} 丢出一块石头。`, 'player');
      }
      return;
    }

    ally.stamina = Math.min(ally.maxStamina, ally.stamina + 10);
    this.pushLog(`${ally.name} 体力不支，原地喘气。`, 'info');
  }

  private actionsView(): BattleActionView[] {
    const player = this.player;
    const list: BattleActionView[] = [];
    const add = (id: BattleActionId, available: boolean, reason?: string) => {
      list.push({ id, label: ACTION_LABELS[id], available, reason });
    };

    if (this.grabbed) {
      if (this.options.samuelHelp) add('dart', !this.dartUsed, this.dartUsed ? '本场已用' : '让塞缪尔吹麻醉镖');
      add('pin', this.elapsed < this.dartUntil, this.elapsed < this.dartUntil ? '限制米埃尔行动' : '需要先让塞缪尔吹麻醉镖');
      return list;
    }

    add('moveCloser', !this.grabbed && player.distance > this.definition.distance.min && player.stamina >= 10, this.grabbed ? '被米埃尔扣住' : `体力 -10 · 距离 ${player.distance}`);
    add('moveAway', !this.grabbed && player.distance < this.definition.distance.max && player.stamina >= 10, this.grabbed ? '被米埃尔扣住' : '体力 -10');
    add(
      'melee',
      player.weapon === 'equipped' && player.distance <= 1 && player.stamina >= 10,
      player.weapon !== 'equipped' ? '需要武器' : player.distance > 1 ? '距离太远' : '体力 -10',
    );
    add('throwStone', player.distance <= 10 && player.stamina >= 5, player.distance > 10 ? '距离超过 10 格' : '体力 -5');
    if (this.options.hasBlowgun) {
      add('blowgun', player.blowgun === 'equipped' && player.distance <= 10 && player.stamina >= 5, player.distance > 10 ? '距离超过 10 格' : `命中率 ${this.options.proficiency}%`);
      add('pickupBlowgun', player.blowgun === 'ground' && player.stamina >= 5, '体力 -5');
    }
    if (this.options.samuelHelp) add('dart', !this.dartUsed, this.dartUsed ? '本场已用' : '冻结 10 秒');
    if (player.distance <= 1 && this.elapsed < this.dartUntil) {
      add('pin', true, '限制米埃尔行动');
    } else if (player.distance === 0) {
      add('pin', true, '扣住她（会被撞开）');
    }
    add(
      'pickupWeapon',
      player.weapon === 'ground' && player.weaponOffset === 0 && player.stamina >= 5,
      player.weapon !== 'ground' ? '武器在手上' : player.weaponOffset !== 0 ? `武器在${player.weaponOffset > 0 ? '身后' : '前方'} ${Math.abs(player.weaponOffset)} 格` : '体力 -5',
    );
    add('wait', true, '体力 +10');
    add('flee', !this.grabbed, this.grabbed ? '被米埃尔扣住' : player.weapon === 'equipped' ? '带刀撤退（会被追）' : '空手撤退');
    return list;
  }

  private resolveOutcome(): void {
    if (this.phase === 'finished') return;
    if (this.mier.stamina <= 0) {
      this.finish('win');
      return;
    }
    if (this.players().every((actor) => actor.stamina <= 0)) {
      this.finish('confiscated');
    }
  }

  private finish(result: BattleResult): void {
    if (this.phase === 'finished') return;
    this.phase = 'finished';
    this.result = result;
    const text =
      result === 'confiscated'
        ? '所有人倒在地上。米埃尔把散落的武器一一收走，转身离开。'
        : result === 'fled_armed'
          ? '你转身就跑。她追上来夺走你的刀，才放你走。'
          : result === 'fled_unarmed'
            ? '你空着手撤退。她看了你一眼，没有追。'
            : result === 'win'
              ? '米埃尔倒在地上。'
              : '战斗结束。';
    this.pushLog(text, 'info');
  }

  private pushLog(text: string, kind: BattleLogEntry['kind']): void {
    this.logEntries.push({ text, kind });
    if (this.logEntries.length > 120) this.logEntries.shift();
  }
}
