import { useCallback, useEffect, useRef, useState } from 'react';
import type { NavigationResult, SceneView } from '../engine/engine';
import { StoryEngine } from '../engine/engine';
import type { PackSummary, SaveData } from '../engine/types';
import { AUTO_SLOT } from '../engine/types';
import { validateSave } from '../engine/validate';
import { getPath, setPath } from '../engine/paths';
import type { AssetResolver } from '../assets/AssetResolver';
import type { BattleDefinition, BattleResult } from '../engine/battle/types';
import type { StoredPack } from '../storage/PackStore';
import { parsePackZip } from '../storage/zip';
import type { Runtime } from '../storage/platform';
import { BattleScreen } from './BattleScreen';
import { TeamBattleScreen } from './TeamBattleScreen';
import { AuthorScreen } from './AuthorScreen';
import { DebugDrawer } from './DebugDrawer';
import { ErrorBoundary } from './ErrorBoundary';
import { GameScreen } from './GameScreen';
import { HomeScreen } from './HomeScreen';
import { SaveDialog } from './SaveDialog';
import { Toasts } from './Toasts';
import type { MissingInfo, ToastItem, ToastKind } from './uiTypes';

interface Session {
  stored: StoredPack;
  engine: StoryEngine;
  resolver: AssetResolver;
}

export function App({ runtime }: { runtime: Runtime }) {
  const { storage, packStore, exporter } = runtime;

  const [packs, setPacks] = useState<PackSummary[]>([]);
  const [session, setSession] = useState<Session | null>(null);
  const [scene, setScene] = useState<SceneView | null>(null);
  const [missing, setMissing] = useState<MissingInfo | null>(null);
  const [battle, setBattle] = useState<{ id: string; definition: BattleDefinition } | null>(null);
  const [toasts, setToasts] = useState<ToastItem[]>([]);
  const [busy, setBusy] = useState(false);
  const [fatal, setFatal] = useState<string | null>(null);
  const [saveOpen, setSaveOpen] = useState(false);
  const [debugOpen, setDebugOpen] = useState(false);
  const [authorOpen, setAuthorOpen] = useState(false);
  const [showTiers, setShowTiers] = useState(false);

  const resolverRef = useRef<AssetResolver | null>(null);
  const toastSeq = useRef(0);

  const notify = useCallback((text: string, kind: ToastKind = 'info') => {
    toastSeq.current += 1;
    const id = toastSeq.current;
    setToasts((prev) => [...prev.slice(-2), { id, kind, text }]);
    window.setTimeout(() => {
      setToasts((prev) => prev.filter((toast) => toast.id !== id));
    }, 5200);
  }, []);

  const refreshPacks = useCallback(async () => {
    setPacks(await packStore.list());
  }, [packStore]);

  useEffect(() => {
    let cancelled = false;
    refreshPacks()
      .then(() => undefined)
      .catch((error: unknown) => {
        if (!cancelled) setFatal(`读取内容包库失败：${(error as Error).message}`);
      });
    return () => {
      cancelled = true;
    };
  }, [refreshPacks]);

  const applyResult = useCallback(
    (engine: StoryEngine, result: NavigationResult) => {
      if (result.kind === 'node') {
        setScene(result.view);
        setMissing(null);
        setBattle(result.view.battle ?? null);
        void storage.put(engine.snapshot(AUTO_SLOT)).catch((error: unknown) => {
          notify(`自动存档失败：${(error as Error).message}`, 'error');
        });
        return;
      }
      if (result.kind === 'missing') {
        setMissing({
          reason: result.reason,
          targetId: result.targetId,
          returnNodeId: result.returnNodeId,
          message: result.message,
        });
        return;
      }
      notify(result.message, 'error');
    },
    [storage, notify],
  );

  const startSession = useCallback(
    (stored: StoredPack, initialSave?: SaveData) => {
      if (initialSave) {
        const validation = validateSave(initialSave, stored);
        if (validation.errors.length > 0) {
          notify(`读档失败：${validation.errors.join('；')}`, 'error');
          return;
        }
        for (const warning of validation.warnings) notify(warning, 'info');
      }
      resolverRef.current?.dispose();
      const engine = new StoryEngine(stored);
      const resolver = runtime.createResolver(stored);
      resolverRef.current = resolver;
      setSession({ stored, engine, resolver });
      setScene(null);
      setMissing(null);
      setBattle(null);
      setSaveOpen(false);
      setDebugOpen(false);
      setShowTiers(false);
      setToasts([]);
      applyResult(engine, initialSave ? engine.restore(initialSave) : engine.start());
    },
    [applyResult, notify, runtime],
  );

  const openPack = useCallback(
    async (summary: PackSummary) => {
      setBusy(true);
      try {
        const stored = await packStore.get(summary.id);
        if (!stored) {
          notify('内容包不存在，请重新导入 zip', 'error');
          await refreshPacks();
          return;
        }
        startSession(stored);
      } catch (error) {
        notify(`打开内容包失败：${(error as Error).message}`, 'error');
      } finally {
        setBusy(false);
      }
    },
    [packStore, startSession, notify, refreshPacks],
  );

  const importPackBuffer = useCallback(
    async (buffer: ArrayBuffer, source: string) => {
      setBusy(true);
      try {
        const imported = parsePackZip(buffer);
        const stored: StoredPack = {
          id: imported.pack.manifest.id,
          manifest: imported.pack.manifest,
          nodes: imported.pack.nodes,
          initialState: imported.pack.initialState,
          battles: imported.pack.battles,
          assets: imported.pack.assets,
          images: imported.images,
          importedAt: Date.now(),
          warnings: imported.warnings,
        };
        await packStore.put(stored);
        await refreshPacks();
        const extra = imported.warnings.length > 0 ? `（${imported.warnings.length} 条内容包提示，见游戏内调试面板）` : '';
        notify(`已导入《${stored.manifest.name}》${source}${extra}`, 'success');
      } catch (error) {
        notify((error as Error).message, 'error');
      } finally {
        setBusy(false);
      }
    },
    [packStore, refreshPacks, notify],
  );

  const importPackFile = useCallback(
    async (file: File) => {
      try {
        await importPackBuffer(await file.arrayBuffer(), '');
      } catch (error) {
        notify(`读取 zip 失败：${(error as Error).message}`, 'error');
      }
    },
    [importPackBuffer, notify],
  );

  const importSaveFile = useCallback(
    async (file: File) => {
      try {
        const text = await file.text();
        let data: unknown;
        try {
          data = JSON.parse(text);
        } catch {
          notify('存档文件不是合法 JSON', 'error');
          return;
        }
        const validation = validateSave(data);
        if (validation.errors.length > 0) {
          notify(`存档校验失败：${validation.errors.join('；')}`, 'error');
          return;
        }
        const save = data as SaveData;
        const stored = await packStore.get(save.packId);
        if (!stored) {
          notify(`缺少内容包 "${save.packId}"，请先导入对应的 zip`, 'error');
          return;
        }
        startSession(stored, save);
      } catch (error) {
        notify(`导入存档失败：${(error as Error).message}`, 'error');
      }
    },
    [packStore, startSession, notify],
  );

  const loadSample = useCallback(async () => {
    setBusy(true);
    try {
      const response = await fetch(`${import.meta.env.BASE_URL}sample/mier_arc_200.zip`);
      if (!response.ok) {
        notify('示例包不存在，请先运行 pnpm pack 生成', 'error');
        return;
      }
      await importPackBuffer(await response.arrayBuffer(), '（示例包）');
    } catch (error) {
      notify(`加载示例包失败：${(error as Error).message}`, 'error');
    } finally {
      setBusy(false);
    }
  }, [importPackBuffer, notify]);

  const closeSession = useCallback(() => {
    resolverRef.current?.dispose();
    resolverRef.current = null;
    setSession(null);
    setScene(null);
    setMissing(null);
    setBattle(null);
    setDebugOpen(false);
    setSaveOpen(false);
    void refreshPacks().catch(() => undefined);
  }, [refreshPacks]);

  useEffect(() => {
    if (scene?.endGame) closeSession();
  }, [scene, closeSession]);

  const deletePack = useCallback(
    async (summary: PackSummary) => {
      try {
        await packStore.remove(summary.id);
        await refreshPacks();
        if (session?.stored.id === summary.id) closeSession();
        notify(`已删除《${summary.name}》及其入口记录`, 'success');
      } catch (error) {
        notify(`删除失败：${(error as Error).message}`, 'error');
      }
    },
    [packStore, refreshPacks, session, closeSession, notify],
  );

  const choose = useCallback(
    (index: number) => {
      if (!session) return;
      applyResult(session.engine, session.engine.choose(index));
    },
    [session, applyResult],
  );

  const returnFromMissing = useCallback(() => {
    if (!session) return;
    const view = session.engine.view();
    if (view) {
      setScene(view);
      setMissing(null);
    } else {
      closeSession();
    }
  }, [session, closeSession]);

  const makeSnapshot = useCallback(
    (slot: string) => {
      if (!session) return null;
      if (!session.engine.currentNodeId) return null;
      return session.engine.snapshot(slot);
    },
    [session],
  );

  const loadSave = useCallback(
    (save: SaveData) => {
      if (!session) return;
      applyResult(session.engine, session.engine.restore(save));
      notify('已读取存档', 'success');
    },
    [session, applyResult, notify],
  );

  const finishBattle = useCallback(
    (result: BattleResult, taken?: { weaponTaken?: boolean; blowgunTaken?: boolean }) => {
      if (!session || !battle) return;
      const engine = session.engine;
      const battleId = battle.id;
      const target = battle.definition.outcomes[result];
      setBattle(null);
      if (!target) {
        notify(`战斗结果 "${result}" 没有配置目标节点`, 'error');
        closeSession();
        return;
      }
      if (taken) {
        setPath(engine.state, 'flags.battleHadWeapon', Number(getPath(engine.state, 'player.weaponCount') ?? 0) > 0);
        setPath(engine.state, 'flags.battleHadBlowgun', getPath(engine.state, 'blowgun.owned') === true);
        setPath(engine.state, 'flags.battleWeaponTaken', Boolean(taken.weaponTaken));
        setPath(engine.state, 'flags.battleBlowgunTaken', Boolean(taken.blowgunTaken));
        if (taken.weaponTaken) {
          setPath(engine.state, 'player.weaponCount', 0);
          setPath(engine.state, 'player.weaponStatus', 'lost');
        }
        if (taken.blowgunTaken) {
          setPath(engine.state, 'blowgun.owned', false);
        }
      }
      applyResult(engine, engine.finishBattle(battleId, result, target));
    },
    [session, battle, notify, closeSession, applyResult],
  );

  if (fatal) {
    return (
      <div className="fatal">
        <h1>Cradle 启动失败</h1>
        <p>{fatal}</p>
        <button type="button" className="btn btn-primary" onClick={() => window.location.reload()}>
          重新加载
        </button>
      </div>
    );
  }

  const battleState = session?.engine.state;
  const hasBlowgun = getPath(battleState ?? {}, 'blowgun.owned') === true;
  const samuelHelp = getPath(battleState ?? {}, 'samuel.dartUnlocked') === true;

  return (
    <ErrorBoundary>
      {session && battle ? (
        battle.definition.mode === 'team' ? (
          <TeamBattleScreen
            key={`${battle.id}-${hasBlowgun}-${samuelHelp}`}
            definition={battle.definition}
            resolver={session.resolver}
            allyCount={Number(session.engine.state.team && typeof session.engine.state.team === 'object' && 'members' in session.engine.state.team ? session.engine.state.team.members : 0) || 0}
            playerHasWeapon={Number(session.engine.state.player && typeof session.engine.state.player === 'object' && 'weaponCount' in session.engine.state.player ? session.engine.state.player.weaponCount : 0) > 0}
            hasBlowgun={hasBlowgun}
            proficiency={Number(session.engine.state.blowgun && typeof session.engine.state.blowgun === 'object' && 'proficiency' in session.engine.state.blowgun ? session.engine.state.blowgun.proficiency : 0) || 0}
            samuelHelp={samuelHelp}
            forceBlowgun={false}
            onFinish={finishBattle}
          />
        ) : (
          <BattleScreen
            key={`${battle.id}-${hasBlowgun}-${samuelHelp}`}
            definition={battle.definition}
            resolver={session.resolver}
            hasBlowgun={hasBlowgun}
            proficiency={Number(session.engine.state.blowgun && typeof session.engine.state.blowgun === 'object' && 'proficiency' in session.engine.state.blowgun ? session.engine.state.blowgun.proficiency : 0) || 0}
            samuelHelp={samuelHelp}
            forceBlowgun={false}
            onFinish={finishBattle}
          />
        )
      ) : session ? (
        <GameScreen
          pack={session.stored}
          state={session.engine.state}
          scene={scene}
          missing={missing}
          resolver={session.resolver}
          showTiers={showTiers}
          onToggleTiers={() => setShowTiers((value) => !value)}
          onBack={closeSession}
          onOpenSaves={() => setSaveOpen(true)}
          onOpenDebug={() => setDebugOpen(true)}
          onChoose={choose}
          onReturnFromMissing={returnFromMissing}
        />
      ) : (
        <HomeScreen
          packs={packs}
          busy={busy}
          platformLabel={runtime.platform === 'tauri' ? '桌面端' : 'Web'}
          storageLabel={runtime.storageLabel}
          onImportPack={(file) => void importPackFile(file)}
          onImportSave={(file) => void importSaveFile(file)}
          onOpenPack={(summary) => void openPack(summary)}
          onDeletePack={(summary) => void deletePack(summary)}
          onLoadSample={() => void loadSample()}
          onOpenAuthor={() => setAuthorOpen(true)}
        />
      )}

      {session && (
        <>
          <SaveDialog
            open={saveOpen}
            pack={session.stored}
            storage={storage}
            onClose={() => setSaveOpen(false)}
            onLoad={loadSave}
            onExport={(save, filename) => exporter.exportSave(save, filename)}
            makeSnapshot={makeSnapshot}
            notify={notify}
          />
          <DebugDrawer
            open={debugOpen}
            pack={session.stored}
            scene={scene}
            state={session.engine.state}
            history={session.engine.history}
            resolver={session.resolver}
            storageLabel={runtime.storageLabel}
            storageRoot={runtime.storageRoot}
            onClose={() => setDebugOpen(false)}
          />
        </>
      )}

      {busy && <div className="busy-indicator">处理中…</div>}
      {authorOpen && (
        <AuthorScreen
          runtime={runtime}
          packs={packs}
          onClose={() => setAuthorOpen(false)}
          onPlay={(stored) => startSession(stored)}
          onSaved={() => void refreshPacks()}
          notify={notify}
        />
      )}
      <Toasts items={toasts} />
    </ErrorBoundary>
  );
}
