import type { Effects, GameState, JsonValue } from './types';
import { getPath, setPath } from './paths';
import { cloneJson, deepEqual, isJsonObject } from './util';

export interface EffectProblem {
  path: string;
  message: string;
}

function isEffects(effects: unknown): effects is Effects {
  return isJsonObject(effects);
}

function numericDelta(
  state: GameState,
  path: string,
  delta: number,
  sign: 1 | -1,
  problems: EffectProblem[],
): void {
  if (typeof delta !== 'number' || !Number.isFinite(delta)) {
    problems.push({ path, message: '增量必须是有限数字' });
    return;
  }
  const current = getPath(state, path);
  if (current === undefined) {
    setPath(state, path, sign * delta);
    return;
  }
  if (typeof current !== 'number' || !Number.isFinite(current)) {
    problems.push({ path, message: `当前值不是数字（${JSON.stringify(current)}），已跳过 ${sign > 0 ? 'inc' : 'dec'}` });
    return;
  }
  setPath(state, path, current + sign * delta);
}

/**
 * 执行 effects 并原地修改 state。
 * 任何字段缺失/类型不符都降级为「跳过 + 记录问题」，不抛错。
 * 引擎不假设 state 结构，字段完全由内容包定义。
 */
export function applyEffects(effects: Effects | undefined, state: GameState): EffectProblem[] {
  const problems: EffectProblem[] = [];
  if (effects === undefined) return problems;
  if (!isEffects(effects)) {
    problems.push({ path: '', message: 'effects 必须是对象' });
    return problems;
  }

  for (const [path, value] of Object.entries(effects.set ?? {})) {
    if (!setPath(state, path, cloneJson(value))) problems.push({ path, message: '非法路径，已忽略 set' });
  }
  for (const [path, delta] of Object.entries(effects.inc ?? {})) numericDelta(state, path, delta, 1, problems);
  for (const [path, delta] of Object.entries(effects.dec ?? {})) numericDelta(state, path, delta, -1, problems);

  for (const [path, max] of Object.entries(effects.limit ?? {})) {
    const current = getPath(state, path);
    if (typeof current !== 'number' || !Number.isFinite(current)) {
      problems.push({ path, message: 'limit 目标不是数字，已跳过' });
      continue;
    }
    if (current > max) setPath(state, path, max);
  }

  for (const [path, value] of Object.entries(effects.push ?? {})) {
    const current = getPath(state, path);
    if (current === undefined) {
      setPath(state, path, [cloneJson(value)]);
      continue;
    }
    if (!Array.isArray(current)) {
      problems.push({ path, message: '目标不是数组，已跳过 push' });
      continue;
    }
    current.push(cloneJson(value));
  }

  for (const [path, value] of Object.entries(effects.remove ?? {})) {
    const current = getPath(state, path);
    if (current === undefined) continue;
    if (!Array.isArray(current)) {
      problems.push({ path, message: '目标不是数组，已跳过 remove' });
      continue;
    }
    const target: JsonValue = cloneJson(value);
    let removed = 0;
    for (let i = current.length - 1; i >= 0; i -= 1) {
      if (deepEqual(current[i], target)) {
        current.splice(i, 1);
        removed += 1;
      }
    }
    if (removed === 0) problems.push({ path, message: `数组中没有 ${JSON.stringify(target)}，remove 未生效` });
  }

  return problems;
}
