import { unzipSync } from 'fflate';
import type { AssetMapping, ContentPack, GameState, Manifest, StoryNode } from '../engine/types';
import type { BattleDefinition } from '../engine/battle/types';
import { validateContentPack } from '../engine/validate';
import { isJsonObject } from '../engine/util';
import type { PackImage } from '../assets/AssetResolver';

export class PackImportError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'PackImportError';
  }
}

export interface ImportedPack {
  pack: ContentPack;
  images: Record<string, PackImage>;
  warnings: string[];
  bytes: number;
}

const MIME_BY_EXT: Record<string, string> = {
  webp: 'image/webp',
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
};

const IMAGE_EXT_PRIORITY = ['webp', 'png', 'jpg', 'jpeg'];

function normalizePath(path: string): string {
  return path.replace(/\\/g, '/').replace(/^\.\//, '').replace(/^\/+/, '');
}

function baseName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1);
}

function extName(path: string): string {
  const base = baseName(path);
  const dot = base.lastIndexOf('.');
  return dot === -1 ? '' : base.slice(dot + 1).toLowerCase();
}

function decodeJson(bytes: Uint8Array, fileName: string): unknown {
  let text: string;
  try {
    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    throw new PackImportError(`${fileName} 不是合法的 UTF-8 文本`);
  }
  try {
    return JSON.parse(text);
  } catch (error) {
    throw new PackImportError(`${fileName} JSON 解析失败：${(error as Error).message}`);
  }
}

function readAs<T>(value: unknown, fileName: string, check: (v: unknown) => v is T, expectation: string): T {
  if (!check(value)) throw new PackImportError(`${fileName} 结构不正确：${expectation}`);
  return value;
}

function isManifest(value: unknown): value is Manifest {
  return (
    isJsonObject(value) &&
    typeof value.id === 'string' &&
    typeof value.name === 'string' &&
    typeof value.version === 'string' &&
    typeof value.engineVersion === 'string' &&
    typeof value.entry === 'string'
  );
}

function isNodeArray(value: unknown): value is StoryNode[] {
  return Array.isArray(value) && value.every((item) => isJsonObject(item) && typeof item.id === 'string');
}

function isState(value: unknown): value is GameState {
  return isJsonObject(value) && !Array.isArray(value);
}

function parseAssets(files: Map<string, Uint8Array>, prefix: string): Record<string, AssetMapping> | undefined {
  const found = [...files.keys()].find((path) => path.toLowerCase() === `${prefix}assets.json`.toLowerCase());
  if (!found) return undefined;

  const raw = decodeJson(files.get(found)!, 'assets.json');
  if (!isJsonObject(raw)) throw new PackImportError('assets.json 必须是对象');
  const assets: Record<string, AssetMapping> = {};
  for (const [name, value] of Object.entries(raw)) {
    if (!isJsonObject(value) || typeof value.placeholder !== 'string' || value.placeholder === '') {
      throw new PackImportError(`assets["${name}"].placeholder 缺失`);
    }
    assets[name] = {
      placeholder: value.placeholder,
      slot: typeof value.slot === 'string' ? (value.slot as AssetMapping['slot']) : undefined,
      alt: typeof value.alt === 'string' ? value.alt : undefined,
    };
  }
  return assets;
}

function parseBattles(files: Map<string, Uint8Array>, prefix: string): Record<string, BattleDefinition> | undefined {
  const found = [...files.keys()].find(
    (path) => path.toLowerCase() === `${prefix}battles.json`.toLowerCase(),
  );
  if (!found) return undefined;

  const raw = decodeJson(files.get(found)!, 'battles.json');
  const map = isJsonObject(raw) && isJsonObject(raw.battles) ? raw.battles : raw;
  if (!isJsonObject(map)) {
    throw new PackImportError('battles.json 结构不正确：需要 { "battles": { "<id>": { ... } } }');
  }

  const battles: Record<string, BattleDefinition> = {};
  for (const [id, value] of Object.entries(map)) {
    if (!isJsonObject(value)) throw new PackImportError(`battles.${id} 必须是对象`);
    const participants = value.participants;
    if (!Array.isArray(participants) || participants.length < 2) {
      throw new PackImportError(`battles.${id}.participants 至少需要两个参战者`);
    }
    for (const participant of participants) {
      if (!isJsonObject(participant) || typeof participant.id !== 'string' || typeof participant.team !== 'string') {
        throw new PackImportError(`battles.${id}.participants 条目需要 id 与 team`);
      }
      if (participant.team !== 'player' && participant.team !== 'enemy') {
        throw new PackImportError(`battles.${id}.participants 的 team 只能是 player / enemy`);
      }
    }
    if (!participants.some((p) => isJsonObject(p) && p.team === 'player')) {
      throw new PackImportError(`battles.${id} 缺少 player 阵营参战者`);
    }
    if (!participants.some((p) => isJsonObject(p) && p.team === 'enemy')) {
      throw new PackImportError(`battles.${id} 缺少 enemy 阵营参战者`);
    }
    if (!isJsonObject(value.distance) || typeof value.distance.initial !== 'number') {
      throw new PackImportError(`battles.${id}.distance.initial 缺失`);
    }
    battles[id] = { ...(value as unknown as BattleDefinition), id: typeof value.id === 'string' ? value.id : id };
  }
  return battles;
}

/**
 * 浏览器端内存解压 zip（fflate），不触碰 File System Access API。
 * 结构不符时抛出 PackImportError，带明确原因。
 */
export function parsePackZip(buffer: ArrayBuffer): ImportedPack {
  if (buffer.byteLength === 0) throw new PackImportError('zip 文件为空');
  let raw: Record<string, Uint8Array>;
  try {
    raw = unzipSync(new Uint8Array(buffer));
  } catch {
    throw new PackImportError('不是有效的 zip 文件，或文件已损坏');
  }

  const files = new Map<string, Uint8Array>();
  for (const [name, bytes] of Object.entries(raw)) {
    const path = normalizePath(name);
    if (path === '' || path.endsWith('/')) continue;
    files.set(path, bytes);
  }

  const manifestPath = [...files.keys()].find((path) => baseName(path).toLowerCase() === 'manifest.json');
  if (!manifestPath) throw new PackImportError('zip 根目录缺少 manifest.json');

  const prefix = manifestPath.slice(0, manifestPath.length - 'manifest.json'.length);
  const expected = ['story.json', 'state.json'];
  const located = new Map<string, string>();
  for (const file of expected) {
    const found = [...files.keys()].find(
      (path) => path.toLowerCase() === `${prefix}${file}`.toLowerCase(),
    );
    if (!found) throw new PackImportError(`zip 缺少 ${file}`);
    located.set(file, found);
  }

  const manifest = readAs(decodeJson(files.get(manifestPath)!, 'manifest.json'), 'manifest.json', isManifest, '需要 id/name/version/engineVersion/entry');
  const nodes = readAs(
    decodeJson(files.get(located.get('story.json')!)!, 'story.json'),
    'story.json',
    isNodeArray,
    '必须是节点数组',
  );
  const initialState = readAs(
    decodeJson(files.get(located.get('state.json')!)!, 'state.json'),
    'state.json',
    isState,
    '必须是对象',
  );

  const battles = parseBattles(files, prefix);
  const assets = parseAssets(files, prefix);
  const pack: ContentPack = { manifest, nodes, initialState, battles, assets };
  const validation = validateContentPack(pack);
  if (validation.errors.length > 0) {
    throw new PackImportError(`内容包校验失败：\n${validation.errors.join('\n')}`);
  }

  const warnings = [...validation.warnings];
  if (prefix !== '') warnings.push(`内容包文件位于子目录 "${prefix}"，已自动识别`);

  const images: Record<string, PackImage> = {};
  const chosenExt = new Map<string, string>();
  for (const [path, bytes] of files) {
    if (!path.startsWith(`${prefix}images/`)) continue;
    const ext = extName(path);
    if (!(ext in MIME_BY_EXT)) continue;
    const name = baseName(path).slice(0, baseName(path).length - ext.length - 1);
    if (name === '') continue;
    const previous = chosenExt.get(name);
    if (previous === undefined || IMAGE_EXT_PRIORITY.indexOf(ext) < IMAGE_EXT_PRIORITY.indexOf(previous)) {
      if (previous !== undefined) warnings.push(`图片 "${name}" 同时存在 .${previous} 与 .${ext}，已选用 .${ext}`);
      images[name] = { bytes, mime: MIME_BY_EXT[ext] };
      chosenExt.set(name, ext);
    }
  }

  let bytes = 0;
  for (const item of files.values()) bytes += item.byteLength;
  return { pack, images, warnings, bytes };
}

/** 供 Node 侧脚本 / 测试构造内容包使用。 */
export function isImportedPack(value: unknown): value is ImportedPack {
  return isJsonObject(value) && 'pack' in value && 'images' in value;
}
