import { convertFileSrc } from '@tauri-apps/api/core';
import type { AssetHint, AssetResolver, ResolvedAsset } from './AssetResolver';
import { colorBlockDataUrl, resolveBuiltin } from './fallback';

/**
 * Tauri 端实现：包内图片已经在磁盘上，tier 1 用 asset 协议 URL；
 * tier 2/3 复用与 Web 完全相同的回退逻辑。
 */
export class TauriAssetResolver implements AssetResolver {
  private readonly paths: Record<string, string>;

  constructor(paths: Record<string, string>) {
    this.paths = paths;
  }

  resolve(logicalName: string, hint: AssetHint = 'portrait'): ResolvedAsset {
    const name = logicalName.trim() === '' ? '__empty__' : logicalName.trim();
    const diskPath = this.paths[name];
    if (diskPath) return { url: convertFileSrc(diskPath), tier: 1, logicalName: name };
    const builtin = resolveBuiltin(name);
    if (builtin) return { url: builtin, tier: 2, logicalName: name };
    return { url: colorBlockDataUrl(name, hint), tier: 3, logicalName: name };
  }

  dispose(): void {
    // asset:// URL 不需要 revoke
  }
}
