import type { ContentPack, PackSummary } from '../engine/types';
import type { PackImage } from '../assets/AssetResolver';
import { getDatabase, PACKS_STORE, requestAsPromise, txDone } from './idb';
import { PlatformNotImplementedError } from './StorageAdapter';

export interface StoredPack extends ContentPack {
  id: string;
  images: Record<string, PackImage>;
  /** Tauri 端：图片逻辑名 → 磁盘绝对路径，供 asset 协议解析 */
  imagePaths?: Record<string, string>;
  importedAt: number;
  warnings: string[];
}

/** 内容包库：Phase 1 存 IndexedDB；Phase 2/3 换成文件系统解包目录。 */
export interface PackStore {
  init(): Promise<void>;
  list(): Promise<PackSummary[]>;
  get(id: string): Promise<StoredPack | null>;
  put(pack: StoredPack): Promise<void>;
  remove(id: string): Promise<void>;
}

export function summarize(pack: StoredPack): PackSummary {
  return {
    id: pack.manifest.id,
    name: pack.manifest.name,
    version: pack.manifest.version,
    engineVersion: pack.manifest.engineVersion,
    entry: pack.manifest.entry,
    nodeCount: pack.nodes.length,
    importedAt: pack.importedAt,
  };
}

export class WebIndexedDBPackStore implements PackStore {
  async init(): Promise<void> {
    await getDatabase();
  }

  async list(): Promise<PackSummary[]> {
    const db = await getDatabase();
    const tx = db.transaction(PACKS_STORE, 'readonly');
    const packs = (await requestAsPromise(tx.objectStore(PACKS_STORE).getAll())) as StoredPack[];
    await txDone(tx);
    return packs.map(summarize).sort((a, b) => b.importedAt - a.importedAt);
  }

  async get(id: string): Promise<StoredPack | null> {
    const db = await getDatabase();
    const tx = db.transaction(PACKS_STORE, 'readonly');
    const pack = (await requestAsPromise(tx.objectStore(PACKS_STORE).get(id))) as StoredPack | undefined;
    await txDone(tx);
    return pack ?? null;
  }

  async put(pack: StoredPack): Promise<void> {
    const db = await getDatabase();
    const tx = db.transaction(PACKS_STORE, 'readwrite');
    tx.objectStore(PACKS_STORE).put(pack);
    await txDone(tx);
  }

  async remove(id: string): Promise<void> {
    const db = await getDatabase();
    const tx = db.transaction(PACKS_STORE, 'readwrite');
    tx.objectStore(PACKS_STORE).delete(id);
    await txDone(tx);
  }
}

