import { useMemo, useState } from 'react';
import { zipSync } from 'fflate';
import { save as saveDialog } from '@tauri-apps/plugin-dialog';
import { writeFile } from '@tauri-apps/plugin-fs';
import type { AssetMapping, ContentPack, PackSummary, StoryNode } from '../engine/types';
import { validateContentPack } from '../engine/validate';
import { parseDsl } from '../engine/dsl/parser';
import { repairJson } from '../engine/dsl/repair';
import type { StoredPack } from '../storage/PackStore';
import { isTauri, type Runtime } from '../storage/platform';
import { FileButton } from './fileUtils';
import type { ToastKind } from './uiTypes';

interface Draft {
  id: string;
  name: string;
  version: string;
  engineVersion: string;
  entry: string;
  stateText: string;
  storyText: string;
  battlesText: string;
  assetsText: string;
  scriptText: string;
}

type Mode = 'dsl' | 'json';

const STATE_TEMPLATE = `{
  "player": { "name": "旅人", "hp": 10 },
  "flags": { "ready": false },
  "world": { "day": 1 }
}`;

const STORY_TEMPLATE = `[
  {
    "id": "start",
    "layout": "stacked",
    "text": "这是你的剧本开头。",
    "choices": [{ "text": "继续", "targetId": "end" }]
  },
  {
    "id": "end",
    "text": "故事到这里。",
    "choices": []
  }
]`;

const BATTLES_TEMPLATE = `{
  "version": 1,
  "battles": {}
}`;

const BATTLES_EXAMPLE = `{
  "version": 1,
  "battles": {
    "my_duel": {
      "format": "duel",
      "distance": { "initial": 6, "min": 0, "max": 10, "fleeAt": 10 },
      "time": { "regenPerSecond": 1 },
      "actionValue": { "threshold": 100 },
      "participants": [
        { "id": "player", "name": "主角", "team": "player", "speed": 70, "stamina": 100 },
        { "id": "enemy", "name": "对手", "team": "enemy", "speed": 100, "stamina": 100 }
      ],
      "actions": {
        "moveCloser": { "staminaCost": 10 },
        "moveAway": { "staminaCost": 10 },
        "melee": { "staminaCost": 10, "range": 1, "enemyStaminaLoss": 10, "dodge": 0.5 },
        "throwStone": { "staminaCost": 5, "enemyStaminaLoss": 1, "dodge": 0.5 },
        "pickupWeapon": { "staminaCost": 5 },
        "wait": { "staminaCost": 0, "staminaGain": 10 }
      },
      "outcomes": { "win": "end", "lose": "end", "flee": "end" }
    }
  }
}`;

const ASSETS_TEMPLATE = `{
  "米埃尔·平静": { "placeholder": "char_mier_neutral", "slot": "npcPortraits", "alt": "米埃尔·平静" }
}`;

const DSL_TEMPLATE = `# start [背景: bg_wilderness_day]
这是你的剧本开头。

* 继续 -> end (flags.ready = true)
* 需要条件才出现的选项 -> end [if flags.ready == true]

# end
故事到这里。
`;

const BUILTIN_ASSETS = ['player_neutral', 'char_mier_serious', 'char_mier_back', 'item_stone'];

function blankDraft(): Draft {
  return {
    id: 'my_story',
    name: '我的剧本',
    version: '0.1.0',
    engineVersion: '0.1.0',
    entry: 'start',
    stateText: STATE_TEMPLATE,
    storyText: STORY_TEMPLATE,
    battlesText: BATTLES_TEMPLATE,
    assetsText: ASSETS_TEMPLATE,
    scriptText: DSL_TEMPLATE,
  };
}

function parseJson(text: string, label: string): unknown {
  try {
    return JSON.parse(text);
  } catch (error) {
    throw new Error(`${label} JSON 解析失败：${(error as Error).message}`);
  }
}

function parseAssets(text: string): Record<string, AssetMapping> | undefined {
  if (text.trim() === '') return undefined;
  const raw = parseJson(text, 'assets');
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    throw new Error('assets.json 必须是对象');
  }
  const assets: Record<string, AssetMapping> = {};
  for (const [name, value] of Object.entries(raw as Record<string, unknown>)) {
    if (typeof value !== 'object' || value === null) throw new Error(`assets["${name}"] 必须是对象`);
    const record = value as Record<string, unknown>;
    if (typeof record.placeholder !== 'string' || record.placeholder === '') {
      throw new Error(`assets["${name}"].placeholder 缺失`);
    }
    assets[name] = {
      placeholder: record.placeholder,
      slot: typeof record.slot === 'string' ? (record.slot as AssetMapping['slot']) : undefined,
      alt: typeof record.alt === 'string' ? record.alt : undefined,
    };
  }
  return assets;
}

function parseBattles(text: string): ContentPack['battles'] {
  if (text.trim() === '') return undefined;
  const raw = parseJson(text, 'battles');
  if (typeof raw === 'object' && raw !== null && 'battles' in raw) {
    const battles = (raw as { battles: unknown }).battles;
    if (typeof battles === 'object' && battles !== null) return battles as ContentPack['battles'];
    throw new Error('battles.json 的 battles 必须是对象');
  }
  return raw as ContentPack['battles'];
}

function normalizeNodes(nodes: StoryNode[]): StoryNode[] {
  return nodes.map((node) => ({
    ...node,
    images: node.images?.map((image) => ({ ...image, alt: image.alt ?? image.placeholder })),
  }));
}

interface BuildResult {
  pack: ContentPack;
  parserWarnings: string[];
  battlesJson: string | null;
  assetsJson: string | null;
}

function buildPack(draft: Draft, mode: Mode): BuildResult {
  const state = parseJson(draft.stateText, 'state');
  if (typeof state !== 'object' || state === null || Array.isArray(state)) {
    throw new Error('state.json 必须是对象');
  }

  let nodes: StoryNode[];
  let parserWarnings: string[] = [];

  if (mode === 'dsl') {
    const parsed = parseDsl(draft.scriptText, {
      state: state as ContentPack['initialState'],
      assets: parseAssets(draft.assetsText),
    });
    if (parsed.nodes.length === 0) {
      throw new Error(parsed.problems.join('\n') || '简易剧本里没有解析出任何节点');
    }
    nodes = parsed.nodes;
    parserWarnings = parsed.problems;
  } else {
    const raw = parseJson(draft.storyText, 'story');
    if (!Array.isArray(raw)) throw new Error('story.json 必须是节点数组');
    nodes = raw as StoryNode[];
  }

  const battles = parseBattles(draft.battlesText);
  const assets = parseAssets(draft.assetsText);

  const pack: ContentPack = {
    manifest: {
      id: draft.id.trim(),
      name: draft.name.trim() || draft.id.trim(),
      version: draft.version.trim() || '0.1.0',
      engineVersion: draft.engineVersion.trim() || '0.1.0',
      entry: draft.entry.trim(),
    },
    nodes: normalizeNodes(nodes),
    initialState: state as ContentPack['initialState'],
    battles,
    assets,
  };

  return {
    pack,
    parserWarnings,
    battlesJson: battles && Object.keys(battles).length > 0 ? JSON.stringify({ version: 1, battles }, null, 2) : null,
    assetsJson: assets && Object.keys(assets).length > 0 ? JSON.stringify(assets, null, 2) : null,
  };
}

export interface AuthorScreenProps {
  runtime: Runtime;
  packs: PackSummary[];
  onClose(): void;
  onPlay(pack: StoredPack): void;
  onSaved(): void;
  notify(text: string, kind?: ToastKind): void;
}

export function AuthorScreen({ runtime, packs, onClose, onPlay, onSaved, notify }: AuthorScreenProps) {
  const [draft, setDraft] = useState<Draft>(blankDraft);
  const [mode, setMode] = useState<Mode>('dsl');
  const [status, setStatus] = useState<{ kind: 'ok' | 'error' | 'warn'; lines: string[] } | null>(null);
  const [busy, setBusy] = useState(false);

  const update = (patch: Partial<Draft>) => setDraft((current) => ({ ...current, ...patch }));

  const assetNames = useMemo(() => {
    const names = new Set(BUILTIN_ASSETS);
    try {
      const assets = parseAssets(draft.assetsText);
      for (const value of Object.values(assets ?? {})) names.add(value.placeholder);
    } catch {
      // 忽略，保存时会提示
    }
    return [...names];
  }, [draft.assetsText]);

  const runBuild = (): BuildResult | null => {
    try {
      return buildPack(draft, mode);
    } catch (error) {
      setStatus({ kind: 'error', lines: (error as Error).message.split('\n') });
      return null;
    }
  };

  const save = async (play: boolean) => {
    setStatus(null);
    const built = runBuild();
    if (!built) return;

    const validation = validateContentPack(built.pack);
    if (validation.errors.length > 0) {
      setStatus({ kind: 'error', lines: validation.errors });
      return;
    }

    const warnings = [...built.parserWarnings, ...validation.warnings];
    const stored: StoredPack = {
      ...built.pack,
      id: built.pack.manifest.id,
      images: {},
      importedAt: Date.now(),
      warnings,
    };

    setBusy(true);
    try {
      await runtime.packStore.put(stored);
      onSaved();
      if (play) {
        onPlay(stored);
        onClose();
      } else {
        notify('已保存到内容包库', 'success');
        setStatus({
          kind: warnings.length > 0 ? 'warn' : 'ok',
          lines: warnings.length > 0 ? warnings : ['已保存'],
        });
      }
    } catch (error) {
      setStatus({ kind: 'error', lines: [`保存失败：${(error as Error).message}`] });
    } finally {
      setBusy(false);
    }
  };

  const exportZip = async () => {
    setStatus(null);
    const built = runBuild();
    if (!built) return;
    const validation = validateContentPack(built.pack);
    if (validation.errors.length > 0) {
      setStatus({ kind: 'error', lines: validation.errors });
      return;
    }

    const files: Record<string, Uint8Array> = {
      'manifest.json': new TextEncoder().encode(JSON.stringify(built.pack.manifest, null, 2)),
      'state.json': new TextEncoder().encode(JSON.stringify(built.pack.initialState, null, 2)),
      'story.json': new TextEncoder().encode(JSON.stringify(built.pack.nodes, null, 2)),
    };
    if (built.battlesJson) files['battles.json'] = new TextEncoder().encode(built.battlesJson);
    if (built.assetsJson) files['assets.json'] = new TextEncoder().encode(built.assetsJson);

    const zipped = zipSync(files, { level: 9 });
    const filename = `${built.pack.manifest.id}.zip`;
    try {
      if (isTauri()) {
        const target = await saveDialog({ defaultPath: filename, filters: [{ name: 'zip', extensions: ['zip'] }] });
        if (target) {
          await writeFile(target, zipped);
          notify('已导出 zip', 'success');
        }
      } else {
        const blob = new Blob([zipped as unknown as BlobPart], { type: 'application/zip' });
        const url = URL.createObjectURL(blob);
        const anchor = document.createElement('a');
        anchor.href = url;
        anchor.download = filename;
        document.body.appendChild(anchor);
        anchor.click();
        anchor.remove();
        window.setTimeout(() => URL.revokeObjectURL(url), 2000);
        notify('已导出 zip', 'success');
      }
    } catch (error) {
      setStatus({ kind: 'error', lines: [`导出失败：${(error as Error).message}`] });
    }
  };

  const toJson = () => {
    const built = runBuild();
    if (!built) return;
    update({ storyText: JSON.stringify(built.pack.nodes, null, 2) });
    setMode('json');
    setStatus({
      kind: built.parserWarnings.length > 0 ? 'warn' : 'ok',
      lines: built.parserWarnings.length > 0 ? built.parserWarnings : ['已转换为 JSON'],
    });
  };

  const repairAll = () => {
    const notes: string[] = [];
    const fix = (text: string, label: string) => {
      const result = repairJson(text);
      if (result.notes.length > 0) notes.push(`${label}：${result.notes.join('，')}`);
      return result.text;
    };
    update({
      stateText: fix(draft.stateText, 'state'),
      storyText: fix(draft.storyText, 'story'),
      battlesText: fix(draft.battlesText, 'battles'),
      assetsText: fix(draft.assetsText, 'assets'),
    });
    setStatus({ kind: notes.length > 0 ? 'ok' : 'warn', lines: notes.length > 0 ? notes : ['没有发现需要修复的问题'] });
  };

  const loadPack = async (id: string) => {
    if (!id) return;
    const stored = await runtime.packStore.get(id);
    if (!stored) {
      setStatus({ kind: 'error', lines: ['读取内容包失败'] });
      return;
    }
    setMode('json');
    update({
      id: stored.manifest.id,
      name: stored.manifest.name,
      version: stored.manifest.version,
      engineVersion: stored.manifest.engineVersion,
      entry: stored.manifest.entry,
      stateText: JSON.stringify(stored.initialState, null, 2),
      storyText: JSON.stringify(stored.nodes, null, 2),
      battlesText: stored.battles ? JSON.stringify({ version: 1, battles: stored.battles }, null, 2) : BATTLES_TEMPLATE,
      assetsText: stored.assets ? JSON.stringify(stored.assets, null, 2) : '{}',
      scriptText: DSL_TEMPLATE,
    });
    setStatus({ kind: 'ok', lines: [`已载入《${stored.manifest.name}》，当前为 JSON 视图`] });
  };

  const importScript = async (file: File) => {
    update({ scriptText: await file.text() });
    setMode('dsl');
    setStatus({ kind: 'ok', lines: [`已导入 ${file.name}，点「转换为 JSON」或直接保存试玩`] });
  };

  return (
    <div className="author" data-testid="author-screen">
      <header className="author-header">
        <div>
          <h1>创作模式</h1>
          <p>写简易剧本或 JSON，保存后立刻试玩，或导出 zip 分享</p>
        </div>
        <button type="button" className="btn" onClick={onClose}>
          返回
        </button>
      </header>

      <div className="author-tabs">
        <button
          type="button"
          className={`author-tab ${mode === 'dsl' ? 'is-active' : ''}`}
          onClick={() => setMode('dsl')}
          data-testid="author-tab-dsl"
        >
          简易剧本
        </button>
        <button
          type="button"
          className={`author-tab ${mode === 'json' ? 'is-active' : ''}`}
          onClick={() => setMode('json')}
          data-testid="author-tab-json"
        >
          JSON
        </button>
      </div>

      <div className="author-body">
        <section className="author-section">
          <h2>基本信息</h2>
          <div className="author-row">
            <label className="field">
              <span>内容包 id</span>
              <input value={draft.id} data-testid="author-id" onChange={(event) => update({ id: event.target.value })} />
            </label>
            <label className="field">
              <span>显示名</span>
              <input value={draft.name} onChange={(event) => update({ name: event.target.value })} />
            </label>
            <label className="field">
              <span>版本</span>
              <input value={draft.version} onChange={(event) => update({ version: event.target.value })} />
            </label>
            <label className="field">
              <span>引擎版本</span>
              <input value={draft.engineVersion} onChange={(event) => update({ engineVersion: event.target.value })} />
            </label>
            <label className="field">
              <span>入口节点</span>
              <input value={draft.entry} onChange={(event) => update({ entry: event.target.value })} />
            </label>
          </div>
          <div className="author-row">
            <label className="field">
              <span>载入已有内容包</span>
              <select defaultValue="" onChange={(event) => void loadPack(event.target.value)}>
                <option value="">选择…</option>
                {packs.map((pack) => (
                  <option key={pack.id} value={pack.id}>
                    {pack.name}（{pack.id}）
                  </option>
                ))}
              </select>
            </label>
          </div>
        </section>

        <section className="author-section">
          <h2>初始状态 state.json</h2>
          <textarea
            className="author-textarea"
            spellCheck={false}
            value={draft.stateText}
            onChange={(event) => update({ stateText: event.target.value })}
            data-testid="author-state"
          />
        </section>

        {mode === 'dsl' ? (
          <>
            <section className="author-section">
              <div className="author-section-head">
                <h2>简易剧本</h2>
                <div className="author-inline-actions">
                  <FileButton label="导入 .md/.txt" accept=".md,.txt,text/plain" onFile={(file) => void importScript(file)} className="btn btn-sm" />
                  <button type="button" className="btn btn-sm" onClick={() => update({ scriptText: DSL_TEMPLATE })}>
                    载入模板
                  </button>
                  <button type="button" className="btn btn-sm" onClick={toJson} data-testid="author-to-json">
                    转换为 JSON
                  </button>
                </div>
              </div>
              <p className="author-hint">
                # 节点id [背景: 名] / 正文 / [立绘: 名] / (effects) / * 选项 -&gt; 目标 [if 条件] (effects)
              </p>
              <textarea
                className="author-textarea author-textarea-script"
                spellCheck={false}
                value={draft.scriptText}
                onChange={(event) => update({ scriptText: event.target.value })}
                data-testid="author-script"
              />
            </section>

            <section className="author-section">
              <h2>资源映射 assets.json（可选）</h2>
              <p className="author-hint">
                把「显示名」映射到图片逻辑名，例如 米埃尔·平静 → char_mier_neutral。没有映射时按原名当逻辑名（走占位图/色块）。
              </p>
              <textarea
                className="author-textarea"
                spellCheck={false}
                value={draft.assetsText}
                onChange={(event) => update({ assetsText: event.target.value })}
              />
              <p className="author-hint">内置占位图逻辑名：{assetNames.map((name) => <code key={name}>{name}</code>)}</p>
            </section>
          </>
        ) : (
          <>
            <section className="author-section">
              <h2>剧本 story.json</h2>
              <textarea
                className="author-textarea author-textarea-story"
                spellCheck={false}
                value={draft.storyText}
                onChange={(event) => update({ storyText: event.target.value })}
              />
            </section>

            <section className="author-section">
              <h2>战斗 battles.json（可选）</h2>
              <textarea
                className="author-textarea"
                spellCheck={false}
                value={draft.battlesText}
                onChange={(event) => update({ battlesText: event.target.value })}
              />
              <button type="button" className="btn btn-sm" onClick={() => update({ battlesText: BATTLES_EXAMPLE })}>
                填入战斗模板
              </button>
            </section>

            <section className="author-section">
              <h2>资源映射 assets.json（可选）</h2>
              <textarea
                className="author-textarea"
                spellCheck={false}
                value={draft.assetsText}
                onChange={(event) => update({ assetsText: event.target.value })}
              />
            </section>
          </>
        )}

        <details className="author-cheatsheet">
          <summary>字段速查（不剧透，只讲格式）</summary>
          <div>
            <h3>节点</h3>
            <p>
              <code>id</code> / <code>text</code> / <code>layout</code>（background | stacked）/ <code>images</code> /{' '}
              <code>choices</code> / <code>effects</code> / <code>battle</code>
            </p>
            <h3>选项</h3>
            <p>
              <code>text</code> / <code>targetId</code> / <code>condition</code> / <code>effects</code> /{' '}
              <code>hideIfLocked</code>
            </p>
            <h3>条件</h3>
            <p>
              <code>{'{ "all": [...] }'}</code>、<code>{'{ "any": [...] }'}</code>、<code>{'{ "not": ... }'}</code>；
              叶子写成 <code>{'{ "stat": "player.hp", "op": ">=", "value": 1 }'}</code> 或{' '}
              <code>{'{ "flag": "flags.x", "eq": true }'}</code>。运算符：{' '}
              <code>== != &gt; &gt;= &lt; &lt;= in not_in</code>
            </p>
            <h3>effects</h3>
            <p>
              <code>set</code> / <code>inc</code> / <code>dec</code> / <code>push</code> / <code>remove</code>，
              路径用点号，如 <code>player.fearOfMier</code>。
            </p>
            <h3>战斗</h3>
            <p>
              <code>distance</code> / <code>time.regenPerSecond</code> / <code>actionValue.threshold</code> /{' '}
              <code>participants[]</code>（team: player | enemy）/ <code>actions</code> /{' '}
              <code>outcomes</code>（win / lose / flee 对应节点 id）。动作：moveCloser、moveAway、melee、
              throwStone、pickupWeapon、wait、flee。
            </p>
          </div>
        </details>

        {status && (
          <div className={`author-status ${status.kind}`} data-testid="author-status">
            {status.lines.map((line, index) => (
              <p key={index}>{line}</p>
            ))}
          </div>
        )}
      </div>

      <footer className="author-actions">
        <button type="button" className="btn btn-sm" onClick={() => setDraft(blankDraft())}>
          重置模板
        </button>
        <button type="button" className="btn btn-sm" onClick={repairAll} data-testid="author-repair">
          修复 JSON
        </button>
        <button type="button" className="btn btn-sm" onClick={() => void save(false)} disabled={busy}>
          仅保存
        </button>
        <button type="button" className="btn btn-sm" onClick={() => void exportZip()} disabled={busy}>
          导出 zip
        </button>
        <button
          type="button"
          className="btn btn-primary"
          onClick={() => void save(true)}
          disabled={busy}
          data-testid="author-save-play"
        >
          保存并试玩
        </button>
      </footer>
    </div>
  );
}
